/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20130703-14","meetingId":"h25-cm07","date":"2013年7月3日","dateIso":"2013-07-03","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山元委員長","kind":"提案","question":"以上、調査事項の項目につきまして、区の動向等を踏まえて、適宜、各委員の意見・要望もお聞きしながら、柔軟に進めていきたいと考えております。今期１年間、このような形で進めさせてほしいと求めましたので、どうかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それはそれとして伺ったのですけれども、それから４項目について、できたら事前にいただきたかった。やはり数週間かかるわけですから、その辺の配慮、私たちもより正確につかむための配慮をしてほしいと求めました。","respondent":"山元委員長","answer":"正副でちょっと検討させていただいて、またどのようにしたらいいかを検討しますので、お時間をいただきたいと思います。よろしいですか。","id":"exchange-002"},{"speaker":"あべ委員","kind":"質問・要望","question":"今の件なのですけれども、ご検討いただけるということで、お任せしてもいいのかなと思うのですが、やはり今のペーパーをできるだけ早いうちに手元にいただきたいと要望します。","respondent":"山元委員長、柏原行財政改革担当課長","answer":"お二方のご意見をいただきまして、十分に検討させていただいて、なるべく意に沿えるように頑張りたいと思います。ないようですので、先に進めさせていただきたいと思います。 昨年１１月末ですけれども、これに基づいたコスト比較等と個別検討を国で行いまして、昨年１１月２６日に公表されてあります。概略の説明は以上でございまして、移動中のバスの中で、若干補足をさせていただければと考えています。","id":"exchange-003"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"本当に早く手を挙げて区民の要望に応える、この土地を求めていきたいという趣旨、そのあたりを伺いたいと思っています。当然、使用目的は保育園になるのかなと思っているのですけれども、そのあたりも含めて説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"国に回答期限を延長してほしいという旨は、行政ニーズであるとか、新たなスキームを検討し直さなくてはいけないだろうというところはあります。国に対して、ある程度期限を延ばしてほしいというのは、そういったところの検討期間が必要だという趣旨で申し上げているものです。","id":"exchange-004"},{"speaker":"南委員","kind":"確認","question":"待機児解消策の保育園、保育事業を行っていくことで検討をしていきたいということで、受けとめていいのかどうかというところをもう一度確認したいと思います。","respondent":"柏原行財政改革担当課長","answer":"新聞報道等では保育所用にという趣旨で報道をされておりますけれども、いわゆる社会福祉的な施設ということで大きく広く言っているところがあります。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、ぜひ保育所をつくるという方向で検討すべきだと強く求めたいと思います。もう一度伺いますけれども、検討としては、いろいろな需要も含めて検討するということなのか尋ねました。","respondent":"桑村企画部長","answer":"それも６月の終わりくらいに、私どもはお話を承っているわけなのです。その１つの方法として、ただ、そこだけに絞って検討しているわけではないということはご理解いただきたいと思います。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"私はぜひ保育園をつくってほしいと思っているし、やはり区民の要求に沿った方向できちんと検討をしていただきたい。選択肢というか、ぜひ需要の高いものを取り入れていただきたいということ、とりわけ保育園を強調したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"かえって、また逆の返事も出てしまうのではないかと思うので、そのあたりはどのように考えていらっしゃるのかと思っています。何かそういうことがプランにあって、先延ばしているのかという質問です。","respondent":"桑村企画部長","answer":"障害者の施設、あるいはほかの場面で施設展開ができないかということをいろいろ検討してまいりました。その検討の中で、国から定期借地という違う考え方が出てまいりましたので、それを含めるとどのくらいの展開ができるか。","id":"exchange-008"},{"speaker":"須藤委員","kind":"質問","question":"林試の森の近くの小山台住宅、あそこ自体は本当に公園とくっつけてあげたほうがいいことなので、東京都が無償でやれという声を国に出している。むしろ活用するためには、無償でよこせという話をしていくべきだと思うのだけれども、そのあたりはどうか尋ねました。","respondent":"桑村企画部長","answer":"これまでの国の考え方は、３分の１とか半分とか、あるいは無償で提供されたりするのが当たり前なことだと思います。買っていただきたいというのが基本の考えですので、その中で実際上、期限が来たものについては一定の判断をさせていただきたいです。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっとまとめて、どことどこが変わったというのを、もう一度確認させていただけますでしょうか。この２点をお願いします。","respondent":"柏原行財政改革担当課長","answer":"おおむね全体の額の１割とか、そういった金額になるのですけれども、そういったものは不要ということです。それを提示するというやり方になってくると思いますので、現段階でこの金額でというのは、こちらもわからないです。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"４カ所の中では、ぜひ積極的に考えてほしいと求めましたし、他の福祉施設がここに移転をしてくる。そして、ぜひご検討をしていただきたいと強く要望をして、とりあえず質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今すぐ数字を求めるわけではないのですが、どの程度、割合としてはごく一部だというものだとは推測できます。あるいは品川区の都合からこことは交渉しようとか、あるいはこれまで交渉したとか、そういう経緯はいかほどあるのかという視点で伺おうと思いました。","respondent":"柏原行財政改革担当課長","answer":"まず、今回の国家公務員宿舎については国が大きな方針を出したというところがございまして、大きな動きということで出てきたところがあります。トータルに考えたときにどうなのだろうかということで、内部の検討レベルといいますか、情報をとる状況です。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問・要望","question":"公と公という、自治体対国という点では、どうしても品川区サイドが受け身のような気がしてしようがないのです。これから、限られた都市部という中では、そういったアプローチがぐっと高まるような気がするのですが、お考えを教えてほしいと求めました。","respondent":"桑村企画部長","answer":"自治体に来る場合は、半分減額ですとか、あるいは無償で貸し付ける部分があるとかいったものがあったりして非常に検討がしやすかった。そういう意味では、なかなかこういう大きな土地については、公有地が１つの有利な条件であることは間違いないだろうと思っているところです。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後に、これからの展開の中で、現状を教えていただきたいのですが、それぞれ所管を中心に用地取得等はアンテナを張られていると思います。あるいは今後、そういう可能性があるのかどうかだけ、最後に説明を求めました。","respondent":"桑村企画部長","answer":"うまい方法がないか、あるいは共同で住宅を建てることはできないか、そういう形で事業を進めしています。開発についての一定のノウハウという意味では、民間にお願いしたり、タイアップしたりして進めているのが現状です。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問","question":"視察も含めて５カ所拝見した中で、あるいは第三者の民間の方とかとちょっと下話的なものを伺ったときに、やはり用途という意味で限界がある。これはやはりまだ時間延長というものも踏まえて、適切な延長願いというのか、事業を判断されるというのが適切だと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今日、５カ所拝見をさせていただいて、小山台住宅は東京都から公園と一体化といいますか、防災目的での要望が出ているということでありました。小山台で、もし地域の声を吸い上げているものがあれば教えていただきたいというのが、まずお伺いしたいところです。","respondent":"柏原行財政改革担当課長","answer":"現段階で直接的に何かお伺いをしているというところではございませんけれども、所管等を通して、この地域での行政のニーズであるとか、施設の状況であるとか、そういったところを調査している状況です。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一体化の整備という考え方もうなずけるところがあったものですから、その考えの１つに、これは個人的な要望として。大きさから言うと南品川はそんなに広くはないですから、私も地元の地域ですから、そこはぜひよく調査をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"こういう話が当然民間にも出ているかと思うのですが、社会福祉法人等から区に声がかかるとか、そういう話は何かあったのか。ある可能性もあるかなと思ったので、その点で民間の動きがわかるようであれば教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"社会福祉法人から国への直接の問い合わせであるとか、区に対する問い合わせというのは、ここの物件に関しては現在のところはございません。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問・要望","question":"これから来る可能性もあるし、それも含めて、来た場合にどう対処するかというのは考えておいていただきたいと考えています。そのような流れに自動的に、今回においてもなっているのかどうか、教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"地元自治体の品川区が、こういった形で全てにおいて取得、貸借を希望しないということであれば、民間のほうに大きく広げる。それが売却のなのか、定期借地なのか、わかりませんけれども、広く民間に門戸を開けて募集する形になると聞いています。","id":"exchange-019"},{"speaker":"浅野委員","kind":"質問・要望","question":"それで、あと、今回はこの１件だけなのですけれども、平成何年ですかね、この件について、国としても、これから動きが活発になってくるのかなと。今回は１カ月待ってもらえればいいのですけれども、早急に並行して検討してほしいと求めましたが、いかがか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"ほかの物件ですけれども、委員がおっしゃるとおりでございまして、こういった形でいずれは出てくるというのが見えてありますので、行政需要等を含めながら、並行しながら、どういったものに使えるかというところで検討を進めていきたいと思ってあります。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"あるいは南品川の１番のほうだって、それはそれでありがたい話ですし、そういった都の動きを教えていただきたい。それから、国に対して、都と一緒になってさらなる条件緩和を引き出していくとか、そういったこともされているのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"東京都にも確認をとっているのですが、正直申しまして、具体的な明確な回答をいただけない状況です。国に無償譲渡であるとか、そういうところも含めて、東京都の動き等の情報は積極的に収集していきたいと思っています。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"では、都と一緒に、国に何かを言っていくという環境にはないということですか。都は、余り自分の動きについては、周りに出していないということか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"東京都と連携をとりながら、国に対していろいろ要望であるとかはしていきたいと考えていますし、所管が動いているという実績があります。","id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうは、南品川、１カ月ということでありますけれども、それ以外のところで、ほかの土地についてはどうなっているのか、まず、その辺をお聞かせほしいと求めましたけれども。","respondent":"柏原行財政改革担当課長","answer":"そんなに遠くない範囲で情報提供が来るのではないかと思いますけれども、いつ来るのかというのは、まだこちらも把握し切れてございません。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"省庁名が書いてありますけれども、実際にはこの省庁という判断でいいのか、それとも管財部ということなのか。ある程度の大きさになってくると、それを財務省に戻したというケースもあるので、交渉相手はどちらなのかというのを教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"動きが決まったときには、財務省の財務事務所のほうに移管を受けて、そこが一括していろいろ交渉するという流れになってあります。","id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"当然あるでしょうから、それは逆に言うと、自治体として花房山の価値を認識していただきたい。ですから、積極的なアプローチをしていただきたいという思いです。","respondent":"柏原行財政改革担当課長","answer":"いろいろ物件がございまして、定期借地それから都との連動、いろいろな考え方があろうかと思います。そういったところを今、順次調べているところですので、そういったところを総合的に判断しながら決めていくものであろうと考えています。","id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、かえってプラスに働いていただければいいと考えていますので、これは要望でお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"以前からうわさが出ていた中の、方向性出てきた部分があると思うのですけれども、品川税務署が１階に移転するだろうという状況がありましたよね。これは、もう正式に廃止になっている話なのか、そこら辺の状況をつかんでいるか尋ねました。","respondent":"桑村企画部長","answer":"平米ができないということなので、そうすると、品川税務署が今持っている面積はここでは確保できないということにどうしてもなりました。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ただ、あの隣が青色申告会とか、法人、税理士会とか、あそこは逆に言うと今、既存不適格的になっている部分です。あそこの建物ももう大分たっているし、区との協力団体でもある中で、そういう折衝というのは行われたものなのか尋ねました。","respondent":"桑村企画部長","answer":"詳しいあれはないのですけれども、十分折衝させていただいて、何とかならないかというお話をさせていただいたのですけれども、どうしても了承を得られなかったということなので、税務署としては、これ以上やっても難しいということで諦めたという経過があります。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今度８月の上旬に委員会があると思いますが、もう一度状況がわかれば、私どもは方向性を出していきたい。ただ、現状のままでは、余り効率的ではないというのが自民党の考え方にはあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"今わかっている範囲でいいですから、教えていただきたいというのが１つと、さっきも言った６月７日付の東京新聞。そのあたり区としては、どういう認識をして、情報提供を受けとめていらっしゃったのかというあたりも確認したいと思います。","respondent":"柏原行財政改革担当課長","answer":"さらに、そちらからの賃料収入が区に入るということになりますので、それも選択肢としては１つ考えられるです。これについて早々に回答をいただきたいということと、こういったところも踏まえて検討していただければという情報提供をいただいたです。","id":"exchange-030"},{"speaker":"南委員","kind":"確認","question":"この５物件に対して、保育園の待機児解消の対象物件だと捉えていいということですか。もう１回、その点を確認したいと思います。","respondent":"柏原行財政改革担当課長","answer":"待機児童対策で使える物件ということで、こちらの４地区５物件が対象になっているということで、情報提供いただいています。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、全体の保育園のバランスとの関係で言えば、私は品川寮か上大崎寮を優先して待機児対策として活用すべきだと思っています。５物件の中で、国の方針を受けとめて、やっていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"南委員はほかに移ったから、あの辺はないという話もありましたけれども、地域の中で要望の数がどれぐらいになるかがつかみ切れていない。そういう考え方です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"今回これだけの物件が出てきて、品川区の区民の要望との関係でも、本当に待機児を抱えている。しかも、これでは５０人以上の待機児を抱えている自治体というところで、特に出てきている情報提供なので、そこは重く受けとめるべきだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"井上副委員長","kind":"質問","question":"先ほど現場でしたので。教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"路地が伸びているという状況で、路地が西側と南側に小さい土地が出てきていて、そこも国の敷地であるです。失礼いたしました。","id":"exchange-035"},{"speaker":"井上副委員長","kind":"質問","question":"今、ここに書かれているのが２,３７５.８９m2です。含まれているのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"路地状の敷地も含めて、この敷地面積になっております。","id":"exchange-036"},{"speaker":"井上副委員長","kind":"質問","question":"５カ所が同じような条件で提示されたということなので、どういう形で、建てられないことはないということですよね。工夫をすれば、保育園の施設とか、もう少し規模が小さければということで理解をしていいのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"路地状敷地ということで、品川寮側に向けて路地が９メートルほどの土地ということで、路地扱いになっています。どういったものができるのか、できないのかというのを今、調査しています。","id":"exchange-037"}]},{"id":"topic-03","title":"契約のあり方に関すること","agenda":"契約のあり方に関すること","exchanges":[{"speaker":"向委員","kind":"質問・要望","question":"３つ契約方法の種類があるということで、これはわからないので教えていただきたいのですけれども、今後もこれはしない方向で変わらないのでしょうか。お考えをお伺いしたいのでお願いします。","respondent":"平澤経理課長","answer":"物を売る、または土地を売る場合にこういったものを使うわけですが、昨年度実は１件、一般競争入札で土地を売りました。せり売りをするような案件が出てきた場合は、当然それはやるですが、今のところ、これまではなかったです。","id":"exchange-038"},{"speaker":"向委員","kind":"質問","question":"そういう案件はなかったということで、それに伴い、区としてデメリットが大きかったわけではないということか尋ねました。","respondent":"平澤経理課長","answer":"手法は当然あってしかるべきだと思いますので、その時代に即した形で今後もいろいろな形の検討をしていくということになると思います。その中の１つの手法として、せり売りも当然考えられるです。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"平成２２年度で比較的新しいのですけれども、改めてどういう性格のものなのかを伺いたいのと、非常にそういうことでこの制度の性格をどういうふうに見たらいいのかを改めて教えてほしいと求めました。","respondent":"平澤経理課長","answer":"もう一つの公共工事代金債権信託制度につきましては、これは資金繰りという意味合いが強いと思います。工事完成前に全額を債権化して、証券化して、その部分を担保に銀行から借り受けるというものです。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"改めてどういうふうになっているのかを教えていただきたいのと、そのほかの契約については、このあたりの区の考え方を２つ目に聞きたいと思います。そのあたりの見解、ここには書いてありますけれども、改めて伺いたいと思います。","respondent":"平澤経理課長","answer":"先ほどご説明させていただきましたが、今年６月から最低制限価格制度の試行を再開させていただいたというところもあります。区もきちんとした見積金額を担保したものを作成させていただきまして、予定価格を事前公表することにより過度な競争を防止しているところもあります。","id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"その労使の関係と、自治体の公共事業に携わる方々の労働条件をしっかりと守っていくという角度は、どんなふうに考えているのでしょうか。時間の関係もありますので、それを最後に伺って終わりにしたいと思います。","respondent":"平澤経理課長","answer":"今回につきましては、国の説明ではそれを大幅に上げたです。国のほうの考え方を準用したところで、契約変更の協議に応じているというのが、今の流れです。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"ですから、その２省単価を大幅に値上げした、まさに今この時期に必要なのではないかと私は思っているのです。もう少しいろいろお話を伺いながら考えて、こういう条例ができるように働きかけをしていきたいと思っていますので、とりあえず今日は以上でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"あべ委員","kind":"確認","question":"１点目、結局、品川区としては特にやっていないということでよろしいでしょうか。あるいは登録できるような区としてのサポートは、何かやっていらっしゃるのか、まずはその３点について説明を求めました。","respondent":"平澤経理課長","answer":"電子入札を入れたことによって、今まで事業者の登録が２年に１回だったのですが、これが適宜できるようになって非常に大きな進歩があります。契約係の職員が１つ１つ個別に、お話をして、ご説明をしています。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"確認なのですけれども、２ページの表には経理課契約は、上限で言えば１,０００万円未満。この表の中では１,０００万円以上の契約は入っていないということなのか尋ねました。","respondent":"平澤経理課長","answer":"それからもう１点、予定価格が低いものにつきましては、各主管課に契約権限があるということになります。事業者のニーズをお聞きしながらご説明していますので、一般的な講習会となりますとなかなか難しいという感じがいたします。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"委員長にお伺いしたいのですけれども、これを１つ１つやっていたら、今日終わらないと思います。今後どこを強調して、契約だったら契約のところを進めていくのかというお考えがあれば、ご周知ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"細かいことは、またいろいろお伺いをして勉強していきたいと思います。今日は１点だけ伺いたいのですけれども、今、そこに集中して社会インフラの整備に取り組んでいると思います。","respondent":"中山総務部長","answer":"こういう面で、さまざまなことのバランスをとりながらやっていくということかと認識しています。これは、いわゆる公契約にかかるものの質の確保といいますか、地元の企業との関係もきっちり考えながら進めていきたいと考えております。","id":"exchange-047"},{"speaker":"浅野委員","kind":"提案","question":"１ページ、複数というと多分２以上だと思うのですけれども、提案書を求めたりしているのかということを教えてほしいと求めました。委託の随意契約が８７億円で、１件当たりが少ないけれども、この件について教えてほしいと求めました。","respondent":"平澤経理課長","answer":"２点目、委託における単価契約、総価契約のお話だと認識しました。先ほどご説明をいたしました、これは先ほどご説明いたしましたけれども、簡易型につきましては随意契約という区分になります。","id":"exchange-048"},{"speaker":"浅野委員","kind":"意見","question":"最後のところで複数年次は２年目以降は随意契約と言われたのが、そうするとその言い方からすると、この場合は単価で決めているのか。単価の出し方なのですけれどもとの意見を述べました。","respondent":"平澤経理課長","answer":"リースにつきましては長期継続契約なので、一番最初の金額でもって、どんと契約してそれでおしまい、それでいくということです。説明が悪くて申しわけございません。","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２３件全部だけではなくていいです。概略だけ説明を求めました。","respondent":"平澤経理課長","answer":"こちらにつきましては道路改修工事ということで、西品川一丁目の先の道路の改修につきまして、総合評価で実施したところです。例えば品川区の高層マンションの防災対策の推進に関する検討、それから品川区の長期基本計画の改訂の支援業務といったところ。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"この委員会の冒頭で、委員長から今年１年の特定事件調査の進め方の説明がありまして、私もそのとおりお願いしたいと思います。これが手元に来るのは２日前ですから、ある程度の計画がわかれば非常にありがたいので、次回でいいですから示してほしいと求めました。","respondent":"山元委員長","answer":"今のご意見、正副でしっかりと検討させていただきたいと思います。以上をもちまして、本日の予定は全て終了いたしました。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/631596?Template=document&Id=5948#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":47668,"voices":116}},{"id":"h25-20130704-17","meetingId":"h25-cm07","date":"2013年7月4日","dateIso":"2013-07-04","committee":"震災対策特別委員会","time":"午前１０時００分～午後１２時１３分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木委員長","kind":"質問・要望","question":"よって、９回目の視察につきましては、正副一任とさせていただきたいと考えております。このような形で今後の委員会を進行していきたいと考えておりますが、よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"６メートルで消防活動は原則可能なわけですから、こうしたことからも、この道路計画は白紙に戻すべきだと私は思います。は区の基本的な考えを伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"こういう、先ほどから説明しました耐震化事業、それから不燃化事業ですね。これで火災、いざ地震が起きたときには対処できるような仕組みづくりをしていかなければいけないというのが、区の考えです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"あわせて耐震改修工事について、具体的に改修工事を７５万円から１５０万円と２倍に引き上げた理由、この点をどうお考えなのか伺いたいと思います。最後にもう１点だけ、こういった実態調査が改めて私は必要ではないかと思いますけれども、以上４点伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"耐震事業の説明をしたり、先ほどは地図しか説明しなかったのですが、こういうものを入れて啓発のほうは図ってあります。それから２番目、平成２３年に耐震改修の費用、上限額ですけれども、７５万円から１５０万円に変更いたしました。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを正していくべきではないかと思うのですけれども、この点伺いたいと思います。建替えを進めるために仮移転先の確保の支援、私はここを進めていくべきではないかと思うのですけれども、改めて伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"決まったこの改修工事は、当然ｉｗ値を、先ほど説明しましたｉｗ値を１.０以上に上げる工事をやるのが耐震改修工事です。１５０万円に、こちら先ほども説明しましたとおり、アンケートの結果で７５万円から１５０万円というふうに上げております。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"基礎もその分大きいですから、３００万円ぐらいの、結局補助を２倍化しても負担の軽減につながっていないという状況があるわけですよね。建替えが進まない物理的要因というのは、品川区はどういうことを認識されているのか、その点も伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"先ほど資料１にも説明しております整備地域、もしくは新防火地域、こういった火災危険度の高いところですね。ということで、建替えが進まないからその対策はという点については、ちょっとお答えはまだできないです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"結局補助の対象、対象でないだけで線引きしているのではないかと私は思いますけれども、改めて伺いたいと思います。こういう支援が私は必要ではないかと思いますけれども、その点で改めて伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"どういう割合になっているかというお話ですが、木造のほうだけ簡単にご説明しますと、耐震診断、これにつきましては国が半分です。それから、こういったところは共同化をして改善をしていくというところを進めていくというのが、区の役割ではないかというふうに考えてあります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"だからこそ、住宅の耐震化こそ思い切って支援を進めていくことを強く求めたいと思いますが、この点は改めて伺いたいと思います。やはり道路ではなく建物の倒壊を防ぐことが防災対策上も最優先事項だと思いますけれども、冒頭の質問とあわせて伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"当然耐震化のほうは、その中で支援についてもいろいろ足りないところ、こういったところについては考えていきたいというふうに思っております。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"そして震災直後の死者の９割が建物の倒壊、そういう死者が９割なわけですから、そして新築や壁も含めて燃えにくくしていく。区も今まで進めてきたわけですから、こういうことをしっかりやっていくことが私は必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"ご説明の中で、ちょっと確認させていただきたいところで、耐震診断ですね。そこちょっと確認したいのが１つと、現状見通しについて何か、もうちょっと詳しい説明ができればしてほしいと求めました。","respondent":"品川木密整備担当課長","answer":"小さかったりによって、診断費用が変わってくるというような傾向がありますので、２つの点で金額の差異が出てくるです。それから２点目、戸越３丁目の防災広場ですが、非常に困難な状況です。","id":"exchange-009"},{"speaker":"塚本委員","kind":"確認","question":"よく案内もしていたものですから、自己負担が６万円以上になる可能性があるよというところ、こういうところはしっかり説明していただいているのかというところをちょっと確認したいと思います。","respondent":"品川木密整備担当課長","answer":"ちょっと説明が不十分だったかと思います。一般的に区が確かに進めるときも、費用は１２万円かかって補助が６万円ありますというような説明はしておりますので。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"合致するわけではないので、その辺専門家がどういう、きちんとアドバイスができているのか。自助とかで促せるようなところまで、そのアドバイザーがきちんと説明できているのか、現状を説明するよう求めました。","respondent":"品川木密整備担当課長","answer":"耐震アドバイザーの件ですが、これはもう基本的に年間３回まで、通算６回までを限度として、マンションの管理組合というところですね。改修のアドバイスとか、それから合意形成の支援なんかは非常によくやってくれているというような形で、お声のほうは聞いてあります。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問","question":"９５％で高くて、この６ページにうたわれているその他の安全対策で、いろいろありますね。それがどこまでできているのか、現状ですとか、目標的なところを概要で結構ですので教えてほしいと求めました。","respondent":"品川木密整備担当課長","answer":"すみません。マンションのほうの支援ということですけれども、その支援の状況ですが。","id":"exchange-012"},{"speaker":"本多委員","kind":"意見","question":"専門家がどういう伝え方をしているかということです。そういうものとの意見を述べました。","respondent":"品川木密整備担当課長","answer":"こういう支援の内容で、ありますよというような形でご説明をしまして、やはり自己負担が出る分が幾つか出ると思います。そういった部分も区有施設になるかと思いますけれども、当然施設整備のほうでこういったところも対策等は行っているものと考えております。","id":"exchange-013"},{"speaker":"本多委員","kind":"質問・要望","question":"安全対策、よろしくお願いします。自助という部分をしっかりと伝えるといいますか、そういったものを促進していただきたいと思いまして聞きました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"松澤委員","kind":"確認","question":"２０万円かかったりするのがあって、そのうちの６万円補助なのかと思っていたのですけれども、ほとんどが１２万円におさまっている。それ以上のものもおさまっていると話を聞いたのですが、ちょっともう一度確認で詳しく説明を求めました。","respondent":"品川木密整備担当課長","answer":"そういう、見ている感じとしては若干半分ぐらいまでいくかいかないかのレベルではないかということで、４割という形で表現させていただきました。それから、必ず１２万円でというお話ですが、事務所協会が診断する場合においては１２万円の範囲内でやっているという状況です。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"東京都建築士事務所協会ということですかね、それがどういう団体かはよくわかりませんけれども、それが５割に満たない。の６割は違う方がやっているのですから、そういうものの話し合いとか、検収とかというのはやっているのか尋ねました。","respondent":"品川木密整備担当課長","answer":"これは事務所協会以外の東京都の耐震診断登録業者の診断費用を見ますと、１２万円以下のものというのは本当に限られた状況です。現状の事務所協会と協定を結んでいる１２万円については、非常に安い金額ではないかということを考えてあります。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"敷地いっぱいに家が建っているわけではないですから、少なくとも５０cm下がらなくてはいけないという家はいっぱいあると思うのだよね。違反した建物に補助金を出していったら、私は税金の使い道としてはおかしいと思っているので、その辺についてちょっと見解をお聞きします。","respondent":"品川木密整備担当課長","answer":"ただ、これ補助をする際に、当然この２項道路については改修の段階で何とかできないかというようなことは、指導はしております。ただ、強制的にやるということはなかなか難しいので、改修の段階で何とかならないかということは必ず窓口等で指導はしていくようにしております。","id":"exchange-017"},{"speaker":"松澤委員","kind":"質問・要望","question":"この網をかぶせたって４０％のところが、７年、８年たったって、５％ぐらい、６％ぐらいしか実績は上がっていないわけですから。それと２３区の中で、違反建築というと極端ですけれども、２項道路みたいなところに補助を出している区というのは何区ぐらいあるのか尋ねました。","respondent":"品川木密整備担当課長","answer":"数は申しわけございません。ちょっと現状では把握しておりませんので、申しわけございません。","id":"exchange-018"},{"speaker":"松澤委員","kind":"確認","question":"２３区中ほとんどやっているので、三区ですよという話だと思ったら、やっているのが数区だという話を聞いた。ちょっとその確認をしておきます。","respondent":"品川木密整備担当課長、片田都市環境事業部長","answer":"これは基本的に建築基準法に違反する物件という形の扱いについて、その扱い方が各区まちまちというようなお話になります。ですので、ちょっと具体的に２項道路についてやっているのか、やっていないかというような調査等は… そういう対応を進めていく中で、やはり１９年に計画をつくるときに、密集地域について除却に支援したいという考え方を実は持っていました。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問・要望","question":"ここでは３つ、終了は何をもって終了されているのかということを教えていただきたいのと、一体どういうことをで終了したと言っているのでしょうか。説明するよう求めました。","respondent":"品川木密整備担当課長","answer":"東京都等と話をして、事業を終了しようかどうかというふうな、本当に申しわけございません。総合判断というような形で事業のほうは終了をしております。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"もう一つここに加えて戸越１丁目・２丁目地区とした場合に、不燃領域率が一体どのぐらいになったということになるのか。その意味はどういったことなのかと思いまして、その辺の、例えば戸越１丁目・２丁目地区というのはどういった形になったのか尋ねました。","respondent":"品川木密整備担当課長","answer":"すみません、ちょっと今現時点で資料を持ち合わせておりませんので、すみません。申しわけございません。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問・要望","question":"はい、わかりました。総合的にということで、これからの不燃化を進めていくということで、引き続きそういう期限を定めずに事業を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"ちょっと教えていただきたいのが、７ページの生命を守るための対策ということで品川シェルター、どういう数値で反映するのかというのをちょっと説明を求めました。","respondent":"品川木密整備担当課長","answer":"こちら耐震シェルターを設置した家に関しては、これは耐震化率の算定の中には入れてございません。は耐震改修費用が出せない方について、経済的にも苦しい方について一時的に命を守るものとして出しているものです。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"７ページの写真を見ても、三次災害に影響、家がさせてしまうよというところがあると思うのですね。かぶっているところというのですかね、把握というか、数字がわかればちょっと教えていただきたいのですけれども。","respondent":"品川木密整備担当課長","answer":"品川区の特性としましては、耐震化のほうの危険度というのは非常に低い形で出てくるのですけれども、火災危険度はご存じのように非常に高い形で出ているというのが実情です。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"ごめんなさい。私の質問の仕方がちょっとあれだったので、そこはそういう考えでいいかどうか、ちょっと説明を求めました。","respondent":"品川木密整備担当課長","answer":"そういう点を考えて進めていかなければいけないということになりますと、なかなかすぐに共同化だとか、区画整理だとかですね。ただ、手法としましては非常に効果の大きいものだということは、私どもも認識しています。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"よろしくお願いします。資料の８－１のところで、もうちょっと容積率というのは各地区で決まっていると思うのですが、その辺の考え方を説明するよう求めました。","respondent":"品川木密整備担当課長","answer":"先ほどご説明しましたところで、壁面後退をした場合、非常に容積率が上げられるというようなお話をしました。その道路車線の緩和をしたりとか、そういったとこをすることによって容積率が高くなると、そのようなことになるかというふうに考えています。","id":"exchange-026"},{"speaker":"吉田委員","kind":"意見","question":"今、特別なルールというお話を聞いたのですけれども、ここ以外ですね。２メートル以上の道路に接していない土地とか、私はとても必要だと思うのですが、その辺の考え方をもう１回お願いしますとの意見を述べました。","respondent":"品川木密整備担当課長","answer":"これはそもそもこの補助４６号線、道路ができた後に、静かな町並みを何とか維持していきたいというような住民の声等がございました。これが方向を進めている現状です。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"住民の声と強調なさっていらしたのですけれども、住民の声があったらほかの地区もそういうこともあり得るのか、どうなのか。道路はいっぱい通さなくてはいけないし、拡幅しなくてはいけない部分もいっぱいありますけれども、その辺だけ最後に１つお伺いしたいです。","respondent":"品川木密整備担当課長","answer":"こういう住民の声があれば、区としても対応のほうはしていくように考えてあります。","id":"exchange-028"},{"speaker":"こんの委員","kind":"質問・要望","question":"この中でお伺いしたいのですけれども、その点を１つ教えていただきたいのと、４つ全部細かくなくても結構です。その考え方というのを１つ教えていただきたいのと、中延２丁目・３丁目地域、こういうお知らせも出ている。","respondent":"品川木密整備担当課長","answer":"それから２点目、これは先ほどもちょっと説明したのですが、整備計画というものが各事業を行う前に計画を立てております。それから３点目、「用地ありませんか」という宣伝をしたり等やっているところではありますが、あとは空き家になっているところですね。","id":"exchange-029"},{"speaker":"こんの委員","kind":"質問","question":"区がやるべき公園整備、区として、不燃領域率を上げていくひとつの手法としてやっていくことが大事ではないかというふうに思うのですね。積極的にしていくとかというところはどうですかというのが１点と、この広報の仕方というのですかね、いかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"アドバイスをしたりとか、そういうことをこれからはやっていこうかというふうに考えているのが、現状としての区の取り組みの方向性です。大体１地区３,０００校近く印刷しまして、各戸配付というような形、そこの居住先まで送るような形をとっております。","id":"exchange-030"},{"speaker":"こんの委員","kind":"質問","question":"そうするとこの１０月分に対しては、ほかもこういうことが、やはり用地として探しているわけです。ほかの月でお声をかけていらっしゃるのか、そういった工夫がどのようにされているのか、最後現状だけをお聞きしたい。","respondent":"品川木密整備担当課長","answer":"そういうところには載せているような形をとっていますので、常に用地情報についてはありませんかということについては、まちづくりニュースの中で取り上げていくような形をとっています。","id":"exchange-031"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"災害時の医療も、医療班は立ち上げられることになっていますけれども、その前に大体各地域の病院の耐震化はどうなのか。避難所に医療班ができるのは１３カ所ですから、いわば混乱も含めて、あらかじめ整理した上でどういう対策が必要なのかの議論ができたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/480548?Template=document&Id=6434#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":41147,"voices":76}},{"id":"h25-20130710-10","meetingId":"h25-cm07","date":"2013年7月10日","dateIso":"2013-07-10","committee":"議会運営委員会","time":"午前１０時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"平成２５年陳情第８号、政務活動費に関する陳情","agenda":"平成２５年陳情第８号、政務活動費に関する陳情","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今読み上げていただいたんですが、１のところは実態がどうなっているのか。３番目に公開質問、ぜひそこのところを利用回数の多い会派の方からお伺いしたいんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に自民党、民主・改革ネット、無所属品川の方からちょっとお答えをほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"今の質問というのは、例えばうちが自民党ですけれども、この内容等について、なぜ多いのか教えてほしいということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"この陳情者から出されています疑問点、率直にタクシーの使用回数が多い、なぜなのかなというところと、利用は一体どういう中身で使われているのかということが、やっぱり一番の大もとの疑問点だと思うので、私たちもぜひそこをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"公開質問状に対するお答えの中で全部回答させていただいていますので、それが私たちの答えであります。それ以上でも以下でもありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問","question":"私どもも公開質問状の中でしっかりとお答えをさせていただいているので、それ以上のことはありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"うちのほうもそれぞれ皆さんに意見、内容を聞きましたが、やはりそれぞれ質問状に対してきちんとお答えをして、必要かというふうにご本人、政務活動に対して必要だと思ったということで、タクシーを使わせていただいたということで、一応きちんと回答もしたつもりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"二重取りはないのかどうかという疑問も書かれていますが、ちょっとその辺もお答えいただきたいのと、どこかなともう１回見直しました。その辺の扱いがこの会派の皆さんのところでどういうふうになっているのか、教えていただきたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"ここの回数が多いところは、その他のところでどういった利用の方法があって、回数が多いのかどうか。その辺を説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"運用指針に沿って行われているということだと思うんですけれども、その辺で、各会派のところがどうなっているのかというのを特にお伺いしたいんです。そこを明確にしてほしいということなんですけれども、現状がどうなっているのかというのを各会派の方にお伺いしたいんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特にさっきもお伺いして、沿ってやっていますというところなんですけれども、大きな疑問点で議会開催中の政務調査費ですよね。そういった疑問は一つひとつ解いていったほうがいいと思うので、こういった陳情が出されたと思うんですけれども、その辺はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"個々のことをどうこう、今おっしゃっていますけれども、それは私どもとしてはこういうものに基づいてやってきたということだけですから。それ以外に答えはないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"今ここであなたの会派のところはどうなんですか、皆さんはどうしているんですかと言われましても、それはなかなか答えようがないんじゃないんですか。このワンポイントだけ捉えられて議論しろというのも、ちょっといかがなものかなと思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"意見","question":"この内容を十分踏まえた中で十分党内議論もするし、それをもって議運の場だったり、通常から検討しているものだというふうに認識しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１番のところで、この回答を見ますと、そういうところでタクシーを使っていますよということで言われているわけですよね。私はこの１のことについては、皆さんで一致させることができるんじゃないかなと思うんですけれども、その点に関してはいかがでしょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"意見","question":"つまりその趣旨を変えるためには、公的な機関が別にあって、その中で各会派の代表者が参加して、議長のもとに。そういう観点から、この場では、意見としてお話をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"陳情が上がっているわけですか、やっぱり議会として議論をしていくというのが区民の皆さんに応える、議会としての役割だと思うんですよね。ここのところがしっかりとわかるような形にしてほしいというのが２番目の要望ですけれども、これは、その点についてもご意見いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"これだけ捉えて、じゃあほかは見過ごすのか、見ないのかという話になるじゃないですか。そういう場できちんと皆さんでまた議論して、次はやっていかなければ、ここの場でどうするんだというのはちょっと違うんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"こういう形で議論するとしたら、こういう中身で人件費をこう支出していますということを、堂々と述べることができるんです。だから、皆さんもそういうふうなことで堂々とここで区民の皆さんが理解できるような形で述べていただければ一番いいんじゃないかなと思うんですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"意見","question":"各会派のいろいろなことを議論する場というのが、先ほど各議員おっしゃったように別なところにつくるべきであって、ここでやるべきではないんです。その切り分けをきちんとした上で進行を進めていただきますようにお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１番、２番という形で出てきているわけですから、これに対して明らかにしてほしいというのがこの陳情の趣旨ですから。そうでなければ陳情審査になりませんから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"意見","question":"答えられないときは、こうこうこうで答えられないとおっしゃればいいのであって、やはりこの陳情に対して誠意を持って答えるべきであると思います。ちゃんとやっています、回答していますでは、陳情者が出した思いに応えていないと思うんですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"渡辺委員","kind":"意見","question":"じゃあ議会はどう答えるかといったら、議題に各論が供されるかどうかという、幹事長会を含めて。その意味での、あとは取り扱いかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"研究していくべきであって、例えば品川区議会の政務調査費に関する使途基準を変えていくとか、できない話ですから。きちんとした公的な機関があるわけですから、それにのっとって対処していくべきであると思いますので、あえて意見として述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"意見","question":"十分今までも検討してきた、そういった方向の中でこの２点をどう捉えていくのかということを、やはり今日はこの場で議論すべきであると思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"やっぱりきちんとどういう回答をしているのかというのを私は残すべきであると思います、この場において。必ず発言をとは思いませんけれども、できましたら皆さんにご発言をお願いしたいと思いますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"やっぱり区民がその政務調査費の中身をチェックをできる、そして透明性を持ったものにしていくというところでは一致できるわけですよね。そこのところはちょっとご意見いただけないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当に議会としてもずっとそういうふうに透明性を持った政務調査費の中身にしていこう、品川区議会、特に努力してきたこの間の経過があると思います。私はやっぱり２番目のタクシー代の支出、ここのところが今のままだったらチェックができないというのがここの指摘ですから、いかがでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、簡単には答えられません。ご理解してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今後どういう形でいくか検討したほうが、議会の中でも検討していった方がいいという、そういうところで捉えていいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私個人の意見としては、それはやるべきだと思っていますよ。それはご理解していただきたいんですけれども、当区議会の中の合意がとれれば、それはやっていくべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"伊藤委員","kind":"提案","question":"鈴木（真）前議長宛て答申があって、その意を受けてまさに今日、これからある議会運営委員会にてその一部が正式に提案されると私は聞いています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問","question":"各会派の今のご意見を伺っていると、それぞれにそれぞれのお考えできちんとされていると。会派としてもそれぞれお考えを持ってされているというご意見を伺う中で、これまでもしかり、この陳情に関しては不採択としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それとあと、先ほどからもお話が出ていましたが、公開質問状の中で私たちも回答させていただきました。その中ではさまざまな理由によって、そういった視点からも不採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。別のところできちんと話し合いを持つべきだというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"意見","question":"特に今回の１の項目、緊急の場合に限る。２点目の利用者、早急にこのことも含めて議会の方で検討すべきである、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/681107?Template=document&Id=5138#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":13073,"voices":56}},{"id":"h25-20130711-5","meetingId":"h25-cm07","date":"2013年7月11日","dateIso":"2013-07-11","committee":"総務委員会","time":"午後 １時２８分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"第５７号議案、杜松小学校跡高齢者福祉施設等整備工事委託契約","agenda":"第５７号議案、杜松小学校跡高齢者福祉施設等整備工事委託契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これ以外にはかかるところがないのかどうなのかというのを、１点お聞かせいただきたいのと、お聞かせほしいと求めました。屋上に太陽光パネルが敷設されるということが書かれていますけれども、これが何キロワットぐらいになるのかということについても説明を求めました。","respondent":"平澤経理課長、小林施設整備課長","answer":"工事の直接金額が１２億円でございまして、いわゆる工事監理部門の経費が、それ以外に３,０００万円ほどかかるという予定です。３番の屋上太陽光パネルにつきましては申しわけございません、正確なキロワット数までは… いわゆる鉄筋コンクリートおよび杭事業が今回はないものですから、ずばっとは言えませんけれども、新築の７割ぐらいだと思います。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういう建物については随意契約でいくと理解していいのか、今回はたまたま随意契約を選んだのだ、選択したんだと。それには何かのメリットがあったからこうしたんだとか、理由があると思うんですけれども、そこだけ説明を求めました。","respondent":"平澤経理課長","answer":"今回につきましては、工事まで一体ですが、こちらにつきましては、施設が多岐にわたっているというのがまず考えられます。今後につきましても、それぞれの施設ごとにその特性を活かした形で、どういう形で整備していくかというのは別の問題だと考えているところです。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"まだちょっとメリットの部分の理由がよく見えないと思うので、そこら辺のところの考え方、メリットを説明するよう求めました。","respondent":"永尾高齢者福祉課長、中山総務部長","answer":"やるときも、目的としては民間の資金や経営能力を活かす、あと民間の自主的な能力を活かしたいというところでモデル的にやってみたところです。実際に入札をした結果を見て、今後のやり方について… 事業者のほうで新たに実施していくわけですが、それぞれ入札を行うという形で、競争性を保ちながらやっていくです。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"提案","question":"ないと提案もできないわけでしょうから、それ以外のこういうことをやってくださいといったほうが、私は工事費も何もメリットがあると思う。設計士か何かがやるわけでしょうから、そこに対するメリットを行政側がもっと打ち出してほしいということを、要望しておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"例えば建設工事の工期を短縮できるのかどうか、そういうメリットがあるのかどうかということを教えてほしいと求めました。何かそういうご意見の交換ですとか、そういうものがあったら、教えていただきたい。","respondent":"平澤経理課長","answer":"２点目、十分な期間が必要ということになりますので、これについてはその期間をとったということでこういう形になっているです。３番目、その中で若竹大寿会のほうで創意工夫のあふれたレイアウトを提案されたということで、それも選定の一つの要素になっていると聞いてあります。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"騒音のことも問題が出てくると思うんですが、その辺に関して、委託してしまったから区は関係ないんだよというふうになってしまうんですか。あくまでもともとは区の施設だし、区でやっているんだと思っているわけですから、その辺に対しての責任はどのようなことになっているんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"７月からは高齢者福祉課の行政財産という取り扱いになりますので、高齢者福祉課のほうで責任を持って対応をするということになると思います。これまでも区民に対しての説明会については、その方向はこのまま継続してやりたいと考えています。","id":"exchange-006"},{"speaker":"いながわ委員","kind":"質問","question":"１件お伺いしたいんですが、これはどういう形になっていくか、多少なりとも何かを変えていくのかというのを１点お知らせください。これ、工事中の体育館の取り扱いとしては、そのまま継続的に利用することができるのか、できないのかを説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"この体育館については、改修をしない予定になっております。８月まで地域の方が今までどおりお使いになっていますけれども、９月から工事に入った場合には、継続した使用は現在できない状況になっています。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"確認","question":"確認なんですけれども、もう一回確認で、すみません。それだけちょっと。","respondent":"永尾高齢者福祉課長","answer":"運営法人である社会福祉法人若竹大寿会で行うことになっております。","id":"exchange-008"}]},{"id":"topic-02","title":"第５８号議案、（仮称）荏原東地区地域複合施設新築外構その他その２工事請負契約","agenda":"第５８号議案、（仮称）荏原東地区地域複合施設新築外構その他その２工事請負契約","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"根本的なことを教えてください。最初の工事のときに一緒の入札でもいいような気もするんだけれども、何でこういうふうに分けているのかというのをまず説明を求めました。","respondent":"平澤経理課長","answer":"第１点目といたしまして、工期が大幅に異なっているです。そういったような仕様の違いがある部分につきましては、できる部分はなるべく支障のない範囲で分けて発注しているということをやっているわけです。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてこんなことを聞くのかというと、杜松小学校跡地もそうなんだけれども、さっきの一括というのもあった。そろそろ私の感覚では、全部一緒だからと思っているんだけれども、そこら辺の考え方を説明するよう求めました。","respondent":"平澤経理課長","answer":"その１工事ということで、体育館、それから二葉すこやか園の解体工事を別途発注しています。こういったところからも、地域の事業者育成という面も含めまして、今のところこういう形でと考えている次第です。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"近隣はそれほどないのかもしれないんですけれども、そのようなことがないような土舗装にしてほしいと求めましたけれども、そこら辺はどのように考えていますか。","respondent":"小林施設整備課長","answer":"委員ご指摘のとおり、土舗装は乾燥すると当然粉じんが舞い上がって、ご近所に迷惑をかけるというのは確かにあります。ＧＬから高さＨ２メートルのところで、それも設置しておりますので、粉じんを抑えるということを検討しています。","id":"exchange-011"},{"speaker":"浅野委員","kind":"意見","question":"確かに水をまいて対処したという例が過去にもあったと思うんですけれども、それでも必ず飛んでしまうというのが私は現実だと思いますので、周りに対しての事前の説明ですとか、そういう細心の注意を払って、後からまた苦情が来るということがないように努力してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"豊葉の杜学園の工事のところで事故があって、その原因究明というのをされているということでの答弁だったと思うんですけれども、その後の経過とか、わかったことがありましたら教えていただけますか。","respondent":"小林施設整備課長","answer":"というのは、本体工事の最後まで、外部での高所作業の許可はなかったわけなんですね。使用禁止ということで最後までいきましたので、まだその原因については、労働基準監督署からの回答はまだ来ておりません。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。豊葉の杜学園そのもののことに対して反対ということで、それの一環ということの契約ということで、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/904361?Template=document&Id=1954#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":10233,"voices":55}},{"id":"h25-20130805-6","meetingId":"h25-cm08","date":"2013年8月5日","dateIso":"2013-08-05","committee":"区民委員会","time":"午後 １時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"の区民保養施設の現状","agenda":"の区民保養施設の現状","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、裏面に記載がある約３億円の経費の削減が図れたということだったのですが、そこをどう分析されているのか伺いたいということです。伺いたいのは、結構大きい金額ですから、それをご説明ほしいと求めました。","respondent":"久保田地域活動課長","answer":"こちらを貸し付けることによりまして、区の支出としてこの委託料がかからなくなったというものです。運営方式を改めてできるだけ区の費用、経費を削減するという形で、こういう方式を導入したというものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"位置づけそのものに変更はないのか、どういうふうに位置づけていらっしゃるのか、そこを伺いたいと思うのです。区の支出は減ったかもしれないけれども、今後どういうふうに考えていらっしゃるのか、そこの考えや見通しを伺いたいと思います。","respondent":"久保田地域活動課長","answer":"その点につきましては、民間貸付方式を導入いたしましても考え方としては変更ございません。ただ、そうした中でサービスの向上と経費の削減という観点の両方から考えまして、こういった民間貸付方式を導入させていただいたというものです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"今は結構６,０００円、７,０００円で、その辺は区としてどのように考えていらっしゃるのか。ただ、本当に区民のサービスの向上にどこまでつながっているのか疑問なのですけれど、いかがか尋ねました。","respondent":"久保田地域活動課長","answer":"そういった数とかバス料金のプランとかで来れば、正直言って料金的にはかなわないものがあるということは、私どもも十分に認識しています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"そこを改めて、位置づけや目的に照らしてどうなのかということですけれども、いかがでしょうか。要するに、気軽に利用ができる、そういう改善が引き続き仕組みからしても必要なのではないかと思うのですが、改めていかがか尋ねました。","respondent":"久保田地域活動課長","answer":"それに対しての受益者負担といいましょうか、利用された方から一定の金額をもらう、これは当然行政が運営していく上で必要なものと考えています。そうした中で、平成２５年度はこうした取り組みを中心に進めていきたいということで、ご説明させていただいたものです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"障害や病気を持っている方も安心して利用ができる、そういう役割としての保養所の位置づけを、明らかにしてほしいと求めました。これは意見で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"この報告事項をまず見せていただいて、そもそも論をまずお伺いしたいのですけれども、してくださっているではないですか。それともある意味思いつきで、これをやっておくか程度なのか、ちょっとそこをお伺いしたいと思います。","respondent":"久保田地域活動課長","answer":"考え方を変えて新たな事業に取り組むといったときには、きちんと事前に議会に報告する、これが基本的な考え方です。あわせて平成２５年度は、平成２４年度の問題点をどう改善していくかといった取り組みをきちんと議会に報告させていただきたいと思いまして。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"今度は具体的なことをお伺いしますが、具体的にこのことがなぜ重要な課題なのか、説明していただきたいのですけれども。","respondent":"久保田地域活動課長","answer":"サービスの向上に努めてきたところですけれども、平成２５年度は利用率の向上を重要な課題として位置づけて取り組んでいきたいということで、ご説明させていただいたものです。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"今すぐどうのこうのではないですが、ここでやはり思うのは、消費者としては民間のほうを使うではないですか。何回も同じことを言ってしまいますけれども、その観点をもう考えていかなくてはいけない時期に来ているのではないですかという思いもあるのですね。","respondent":"久保田地域活動課長","answer":"その一つのあらわれが、この保養施設の運営方式の変更というものです。最重要課題というご説明をしましたけれども、利用率の向上という説明をさせていただきましたので、そのところはご理解いただければと思います。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"官でできることは官でするという形で変えた実績がもうあるわけですから、本当に区民が求めているものは何かということを考えつつ、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"その決定方法を教えていただきたいのと、これはあくまで補助をしている４,０００円の部分の支出であって、その点を教えてください。経費と入ってくるお金とのペイができる最低ラインというのはどこにあるのか、もしわかれば教えてほしいと求めました。","respondent":"久保田地域活動課長","answer":"介護者につきましては、先ほどご説明した障害者を介護する方というものが、それぞれ基準として定めているものです。小破修繕等については、日常の維持管理の中で東京ケータリングのほうが対応していくということで、決定しているものです。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"提案","question":"先ほどほかの委員からもありましたが、民間とではもう勝てないですから、そういったやり方というのをやっていったほうがいいのではないか。これは提案ですけれど、区としてどのようなお考えがあるのか、その辺を説明するよう求めました。","respondent":"久保田地域活動課長","answer":"どうぞお話を聞いてあげてくださいと、そういった協力は十分にしていきたいと考えていますし、いずれそういう形でも進めていきたいと思ってあります。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"提案","question":"しないは別としても、ここではあくまで提案というか提言としますけれど、そういった他課との連携もぜひとも視野に入れてほしいと求めました。これは要望で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問・要望","question":"逆に１室２名利用の場合は、１名につき２,１００円を割り増しするというのは、あくまでも空いていれば２名でも普通の金額でいいということですよね。でも空いている場合、２人であっても別に割り増しはないですよねということを聞きたいのですけれど。","respondent":"久保田地域活動課長","answer":"普通の旅館に泊まるのと同じ考え方と思っていただければと思いますので、いわゆる１室３名以上で泊まるとこの表に書いてある料金で、同じ部屋を２人で泊まると、１人当たり２,１００円の割り増し料金をもらうです。","id":"exchange-013"},{"speaker":"山元委員","kind":"質問","question":"〔「いや、ある」と呼ぶ者あり〕 あるのですか。それ、おかしくないか尋ねました。","respondent":"久保田地域活動課長","answer":"空いているからとかということではなくて、２人で利用したいということで、その部屋をチャージするということであれば、この１人当たり５,９７５円に２,１００円の割り増しを、それぞれ２人分いただくという形で取っているものです。","id":"exchange-014"},{"speaker":"山元委員","kind":"意見","question":"部屋が空いているのに、４人集まらないからといって２,１００円割り増しするというのは、何か納得いかなくて。ごめんなさいとの意見を述べました。","respondent":"久保田地域活動課長","answer":"これはあくまでも東京ケータリングのほうの運営料金でやっているものですので、私どもが２,１００円をいただいているわけではありませんから。それに対してかかった料金の一部、４,０００円については区が宿泊助成をするということで、運営しているものです。","id":"exchange-015"},{"speaker":"山元委員","kind":"質問","question":"ＰＲを実施するということで、例えば他区の学校にお貸しするとか、そういうのはあるのですか。考えていらっしゃるのか尋ねました。","respondent":"久保田地域活動課長","answer":"これはもう当然、契約時の約束、前提としています。そういったことにならないように、その辺ちょっとどのタイミングで話をするかはありますけれども、そういったことは念頭に入れながら話はしています。","id":"exchange-016"},{"speaker":"山元委員","kind":"質問","question":"何人かの委員からも障害者の方たちが使うのはどうなのだろうと言っていましたけれど、全体で何％の方たちが実際に使っているのですか。それがおわかりになれば教えてほしいのですけれど。","respondent":"久保田地域活動課長","answer":"約６,５００人に対して、先ほどの高齢者も品川区ということを前提にお考えいただくということで、ちょっと説明が足りなくてすみませんでした。","id":"exchange-017"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に２９０人ということで、先ほどもお話が出ていましたけれども、やはり障害者の方の使い勝手がいい、あそこは使い勝手がいいから行きたいと、そういう思いになれるようなものにしていただければ、もっと利用率は高くなるのかと思いますので、ぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"一つだけお伺いしたいのですけれど、将来どのような方向性を考えていらっしゃるのか聞きたいのですが。それとも、利用率が上がらなかったらどんどん税金を使って、来てくださいとやるのか、その辺をお伺いしたいのですけれど。","respondent":"久保田地域活動課長","answer":"そういったことがあれば、より経費のかからないような方法を考えながら継続していくということも、選択肢の一つとしてあろうかと思います。こういったことをしましても、税金として使っているところはございませんということは、改めてご説明します。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これで、契約は５年でしたか、その契約期間の間に万が一にも採算が合わなくなってきたというときに、契約の中ではどうなっているのですか。その辺をちょっと説明を求めました。","respondent":"久保田地域活動課長","answer":"双方協議の上で途中で契約を打ち切るということも想定としてはありますが、そういった事態にならないように、双方で話し合いをして運営はしていきたいと思ってあります。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それというのはどのぐらい入っているかというのは、区のほうで把握はしているのですか。確認したいのはその値段は一般の方の場合９,９７５円、その金額になっているのか、そこら辺はどうなっているのか気になるのですが。","respondent":"久保田地域活動課長","answer":"もう一回改めてご説明します。パック料金等をもし考えるということであれば、そういったパック料金等についても事前にお話してくださいということで、話はしています。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"売却予定はまだそのまま、難しいのか、何かつかめているのかどうか。もし答えられたらお願いします。","respondent":"久保田地域活動課長","answer":"直接的には経理課のほうで、普通財産になってありますので対応はしていますけれども、両者で連携をしながら進めているところです。１万２,０００平方メートルの土地を分割して売買してはいけないとか、そちらとも話し合いをしながら進めていっているところです。","id":"exchange-022"},{"speaker":"向副委員長","kind":"質問","question":"ちょっと気になるのが、リピーターの取り込みとかそういったことは、どこまで対策をされているのか、それだけお伺いしたいのですけれども。というのも、民間だとリピーターの取り込みをすごく考えているではないか尋ねました。","respondent":"久保田地域活動課長","answer":"よくなったということも聞いてありますので、すみません、説明がちょっと足りなかったですけれども。ただ、誰々さんが何回目の利用とかいうところの把握まではしてございません。","id":"exchange-023"},{"speaker":"向副委員長","kind":"質問・要望","question":"ちょっとリピーターについてはまた改めて別の場面で質問させていただければと思うのですけれど、今後の施策等に取り入れてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-02","title":"の荏原文化センターの休館","agenda":"の荏原文化センターの休館","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"利用者の利便性を高めるいろいろな工事も検討してほしいと思うのですけれども、そういうところについてはどうお考えなのか、伺いたいと思います。伊藤学園の一般開放が５月で中止になりましたけれども、プール利用者の場の確保を考えるべきだと思うのですけれども、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"前年度も補修を行う予定ではございましたけれども、少し時期を待って、来年度合わせて補修をしていきたいと考えているところです。プールにつきましては５つ、半年間を予定していますけれども、そんな形でお願いしようとしています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう検討の中で、あと何年ぐらいは使えるという見通しがあったと思うのですけれど、そこについて改めて伺いたいと思います。さまざまな要望が上がっていると思いますけれども、具体的にどういうふうに検討をしていくのか、どう具体化していくのか、そこを伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そしてまた放送装置については、カセットデッキで対応されていますけれども、設備関係で放送は対応させていただきたいと考えています。大ホールの磁気ループにつきましては、敷く予定はございません。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際どうなのかというのも伺いたいので、荏原文化センターのプールの改修というのは、そういうコースのレーンなども変わるのですか。ぶつかって大変なのだという話をいろいろ伺うもので、その辺どうなのか、状況も含めてご説明ほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"そのような中でプール利用者の方々には丁寧にご説明させていただいて、お願いしようというふうに考えてあります。今ちょっと資料を持っていませんのでご説明することはできませんけれども、一般的な日野学園ならびに学校のプールと同じような幅と聞いてあります。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"部屋がどうだなどというのはいいですから、大きい形でどうなっているのかということを考えて。だからその数字をいただきたいのと、その辺の考え方を教えていただけますか。","respondent":"安藤文化スポーツ振興課長","answer":"それで荏原文化センターとの兼ね合いですが、ご承知のとおり文化センターは従来、区内に５つあり、昭和４５年から順次つくってきてあります。そんな形ですみ分けをして、今後も利用率アップに我々も進めていきたいと考えています。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"だけれど、これからの施策をやっていく上において、やはり近くはないけれど遠くでもないではないですか。その辺は、どういう形でということだけはしっかり持っていないといけないのですけれども、その辺については改めてどうか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"ホールは３６２席ありますが、地域に密着した、またさまざまな文化的なものも発表とかできるような施設になってあります。今後、荏原文化センターとスクエア荏原の利用につきましては、広く区民などに丁寧なご案内させていただいて、利用率を高めていきたいと考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから荏原文化センターという生涯学習の場、今も必要だし、これからもしっかり応援していくことが必要だと思うのですね。それだけに、先ほど、なぜ新築ではないのですかと。","respondent":"安藤文化スポーツ振興課長","answer":"当初より文化センターについては耐震改修を順次やってきて、平成２７年度までに完了しますというご報告を議会でもさせていただいています。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"耐震の問題は緊急課題として、全ての公共施設は直ちにやらなければいけないですから、この事業は当然必要なわけですよね。私が言っているのは、引き続きあそこの場で区民活動を支える文化施設が必要だとしっかり位置づけて、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-03","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１週間ぐらい前のことですからあれですけれども、今後どうしていきたいのか、それが明らかになればいいかと思いますけれど。それと、まとめですけれど、議論の中で進めていけたらと思っています。","respondent":"渡辺委員長、米田商業・観光課長","answer":"正副あるいは理事者と検討させていただきたいと思います。〔「はい」と呼ぶ者あり〕 区といたしましても今後、その状況等を見据えつつより実施をしていくべき事業であろうと考えてございまして、５カ国語版を用意するとともに。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"発着駅をしながわ水族館とシンクパークタワーにした意味というのですか、しながわ水族館の位置づけと、そこをちょっと伺いたいと思います。よくわからないので、ご説明いただけますか尋ねました。","respondent":"米田商業・観光課長","answer":"まだまだ品川区の魅力というものを、見る方が見れば発出できるのだなということは、改めて認識した次第です。そういうような外国の方々を試験的にお招きする、体験ツアーにお招きするのに、国のほうから補助を半分もらって、事業を実施していくというものです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここと品川区の観光がどうかかわっていくと考えていらっしゃるのか、ここは連携と書いてあるのですが、何を目指しているのか伺いたいと思います。品川区は観光ということで、東京都と一緒にカジノ実現を国に求めていく立場なのか、そこも一点伺いたいと思います。","respondent":"米田商業・観光課長","answer":"都の国際会議等誘致戦略、当然１日で済まなければどこかに泊まって、次の日に供えるということは地方の企業だとあろうかと思います。東京都の振興計画というものも、やはり一つひとつを見据えて品川区としてどう判断していくかということを考えていくべきだろうと思います。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"カジノについて聞いたのですけれども、区として、何か考えていくということだったのですか。品川区としてはこれを歓迎しているのか、カジノを解禁してほしいと思っていらっしゃるのか、区の立ち位置がどちらなのかよくわからないのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"立ち位置はどうなのでしょうか。そこを伺いたいと思います。","respondent":"米田商業・観光課長","answer":"今後品川駅の開発とか、そういうようなところを踏まえて、動きはあるかもしれないというふうに考えているところです。これがどういうふうに動くのかというようなことを見据えて、区として判断すべきときが来れば判断していくということになろうかと思います。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それが正確なものかどうかわからないですけれど、どういう積算で出しているのかわからないですけれど、あるならば出していただきたいのですけれど。ないのであればしようがないので、一定の限定的なものでも、もしあれば、非常に参考になるかと思うので提供ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"中塚委員","kind":"意見","question":"今回の所管事務調査でそれぞれ上がってきたものを調査・研究ということだったので、それぞれの会派で出された内容は覚えてはいないのですけれど、その委員の意見を参考にしながら、正副で調整していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"〔「ありますね」と呼ぶ者あり〕 国も含めて。そこを踏まえて、でも次回以降そういうものが出てくるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/398926?Template=document&Id=2672#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":49468,"voices":109}},{"id":"h25-20130805-7","meetingId":"h25-cm08","date":"2013年8月5日","dateIso":"2013-08-05","committee":"厚生委員会","time":"午後 １時００分～午後 ３時３６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"の１、報告事項のふれあい作業所西大井本部解体工事","agenda":"の１、報告事項のふれあい作業所西大井本部解体工事","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"ちょっと言葉のところなんですけども、施設改築とあるんですけども、建て替えという表現もあるんですが、これは改築で、一部どこか、基礎とかが残っているとか、それとも全く新築なのか、そこを説明するよう求めました。","respondent":"中山障害者福祉課長","answer":"全て撤去して、新しく建て替えをするです。ですので、残る場所というのは、一切ございません。","id":"exchange-001"},{"speaker":"たけうち委員","kind":"質問","question":"すみません、本当に言葉のところで、申しわけない。我々のイメージだと、改築というと何か一部残っているのかなというふうにイメージしちゃうんですけど、改築という表現でやっぱりいいんか尋ねました。","respondent":"中山障害者福祉課長","answer":"新築だと、全く新しいところにつくるようなイメージがあるかなと思ったものですから、そのような言葉で説明させていただきました。ただ、確かに改築というと、一部分残るような表現かとも思いますので、建て替えというふうな形で修正させていただきたいと思います。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"今回現施設が区有施設ということで、既に報告済みかもしれないので重複かもしれませんが、建物については社会福祉協議会がということで、今後は区の所有のところが一切ないというふうなものなのか、どういうふうな区と社会福祉協議会との建物についての役割分担がされていくんか尋ねました。","respondent":"中山障害者福祉課長","answer":"ただ、現在の土地のところは、区所有の土地ですので、その部分は普通財産として社会福祉協議会に貸し付けます。区所有の土地と社会福祉協議会所有の土地の上に新しく社会福祉協議会が建物を建てて全て所有するという形になります。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"土地の貸し付けについては無償貸与という形でいくのか、それとも何らかの方策があるのかということ。建物については、改築とかそういった部分の区が支出していく経費のようなものは、どういうふうな取り決めをされているんか尋ねました。","respondent":"中山障害者福祉課長","answer":"区の土地につきましては、まず無償貸与という形になろうかと思います。ほかの法人の建物についても、必要な経費を認めているところがありますので、それはその都度の話になろうかと思います。","id":"exchange-004"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この老朽化および新制度移行に対応するためという、この新制度に対応するためというのは、いわゆる具体的にどういった建物になっていくんか尋ねました。","respondent":"中山障害者福祉課長","answer":"現在ふれあい作業所では、いわゆる障害者総合支援法の枠外で就労、いわゆる作業のようなことをやっております。ふれあい作業所につきましても、この整備が終わった後につきましては、新法に移行するということで、就労継続支援Ｂ型の作業所に移行する予定です。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"ふれあい健康塾を月１回実施している場所がどこなのかということと、どのようにこの先見ているのか、その辺のご意見をお伺いしたいと思います。","respondent":"江部健康課長","answer":"平成１５年にスタートした事業になりまして、運動とかをすることで転倒防止に努めようということで、事業内容としては変わっておりません。ただ、長期基本計画の今後の進展によって検討の余地があることかもしれないという気はいたしております。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"介護予防事業だから介護予防事業の経費なのか、一般財源なのか、ちょっとそこを説明するよう求めました。","respondent":"江部健康課長","answer":"一般会計だったのが平成２１年から２３年まです。ちょっと定かではないんですけど、ちょっと入れかわっている年度があります。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"そういったところで伺っておけばいいんですが、今回なぜこれを健康課の今の答弁だと指導者というか、そういう整理の仕方の行政の考え方というのはどういうふうになるんか尋ねました。","respondent":"早津健康福祉事業部長","answer":"介護保険会計の中で介護予防事業というのは、地域支援事業というのが新たに設けられまして、そちらのほうに移行させてもらったです。少しこの事業は難しくなりつつあるなというような場合には、その人の状態にマッチした形での事業を、連携をとって行っているというものです。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"そこのところがいかに連携がとれているのかという実態を確認していかなくちゃいけないなと私も思っていて、市民のニーズを的確にそちらで把握していただきたいということはおっしゃるとおりだと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"今までに１８３名の卒業生がいらっしゃって、具体的にはどのような形で今活躍をされているのか、例があれば教えてください。私すみません、２０歳から３５歳までというこの１５歳の間に区切ったという根拠、これについてまた教えてほしいと求めました。","respondent":"亀井品川区保健所品川保健センター所長、江部健康課長","answer":"８月３１日に国民健康保険の健康セミナーがあるんですけど、ここでタニタが「５００Kcal満腹定食のコツ」と一緒に、そういう地域活動。そこには卒業生の方が十数名参加いただいていて、あと卒業式や入学式… それから通知とかご案内につきましても、文字とか表現の方法などを改善したチラシなどをつくってお配りしているというところで努めております。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"今後またそういう方に向けての周知というか幅広く受け入れをするという体制があるのかどうか伺いたいのと、３９歳まででもいいのかなと、その辺の考え方について伺いたいと思います。","respondent":"亀井品川区保健所品川保健センター所長、江部健康課長","answer":"私の説明がちょっと不十分だったかもしれませんけども、幅広くやっていきたいと考えていますので、ちょっと説明が不十分で申しわけありませんでした。 それは５歳刻みの成人歯科健診で、健診によって見つけて、主治医をつくるということが目的でやっているものです。そういったことでご理解いただきたいのと、ちょっと今後の課題にさせていただきたいと考えています。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"確認","question":"確認ですけど、４０代からの健康塾というのと、トリムスクールというのが健康センターでやられていると思うんですけど、それはここに健康センター事業の中でやっているというふうに考えて、それで指定管理者のもとでやっているということで理解しておけばよろしいか尋ねました。","respondent":"江部健康課長","answer":"４０代からの健康塾につきましては、向こう側でマネジメントしてもらっているもので、指定管理事業になります。予算上、健康センター事業という枠の中に入っておりますが、指定管理の中には入っておりません。","id":"exchange-012"},{"speaker":"渡部委員","kind":"意見","question":"６０歳になったから、６５歳になったからというような事業では基本的にはないという考えをしています。今日聞くことなのかどうかあれなんですけれども、そこを説明いただけるんであれば、説明をしてほしいと思いますとの意見を述べました。","respondent":"早津健康福祉事業部長","answer":"そういう説明の場になりますと、この課ではこういうことをやっているしという、ちょっと統一性が見えにくいような経過があろうかと思います。そういう問題意識は私どもも持っておりますので、もっと整理したやり方ができないかどうか、もう少し時間を頂戴できればと考えています。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはりさまざまそういうニーズというのが今増えていて、そういうのを求めてくる方もこれからどんどん増えてくると思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"私２０本あります、私１６本ありますという方がみずから手を挙げてくるものだって聞いたと思うんですけど、もうちょっと掘り起こせるんじゃないかな。２０本ある方、１６本ある方、そこら辺をお願いしますとの意見を述べました。","respondent":"江部健康課長","answer":"そういう名称からだと思うんですけども、諸般の影響を考えまして、個別通知はしておりません。３保健センターですかね、たしか３カ所でやっていると思うんですけれども、２カ所から入ってくるものです。","id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうでなければ９件にとどまってしまうのかなという、何ですかね、あっと思うんじゃないかなと単純に思っちゃうんですけれども。ちらほらちょっと耳に、親御さんから耳にするんですけれども、こういったところの歯科の確保というのはできているんか尋ねました。","respondent":"江部健康課長","answer":"そちらで専門的な治療をするというのがこれまでの流れで、歯科診療所に行きますと、みんな送り込んでいた。区と両歯科医師会の皆様方で検討をして、障害者に対応できる歯科医師を増やそうということで、対応できる先生というのが。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当に大変だなというのは、今後も障害者が気軽に近くの診療所にかかれるように、歯科医師会と一緒に広げていただきたいなと思います。そういう方だったり、周りから声をかけられているのか、それとも区が何らかをしているのかというのをちょっとお聞かせいただければと思うんですが。","respondent":"江部健康課長","answer":"ふれあい健康塾というものに通っていただく方の選定といいますか、候補につきましては、地域の民生委員の皆様方に全面的にご協力いただいて、気になる方をご連絡いただくこと、それからケアマネジャーから連絡がある場合もあります。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こうやってどんどん地域と交流を持つということが孤立死を防止していくということにもすごくつながることなので、閉じこもってしまっている方の把握はどの程度あるのかというのは、民生委員からのお話だったりとかであるんですかね。","respondent":"早津健康福祉事業部長","answer":"ですから、こういう方は閉じこもりの程度からいったら、病的な閉じこもりというようなレベルではない方ということになろうかと思います。程度が進んでいきますと、完全な閉じこもりとか、その閉じこもりの程度によって何人いるかというところまでの把握はまだ現在しておりません。","id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"すみません、先ほどの歯科健診のほうの議論を聞いていて、障害者歯科健診を二十歳から進めたということで、４０歳以上では成人でケアできるんだということだったんですが、平成２４年度の２,５２０名の中に、障害者で歯科健診を受けた方がどのくらい含まれているんか尋ねました。","respondent":"江部健康課長","answer":"その点については、申しわけございません、把握しておりません。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"２割、どのぐらいでしょうかというような状況において、その方たちになおかつお知らせもしていない。そのことについて、何かお考えがあれば健康課のほうで説明を求めました。","respondent":"江部健康課長","answer":"ちょっと私のほうで説明が不足しておりますが、あとは区の７階の窓口、ＰＲに努めております。一斉通知につきましては、今後検討します。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"でも、見られる環境がある、ピンポイントで本当に情報を知りたい人にどう伝えるかというのは研究をしていただきたいというふうに思います。当事者の方からお伺いしたお話として、健康課のほうと障害者福祉課のほうと一緒に取り組んでいただきたいということは要望としてお伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"の３、行政視察","agenda":"の３、行政視察","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"いろいろ希望は出させていただきましたけれども、なかなか先方との調整があるということで、それは伺っております。私はちょっと調べきれなかったんですけれども、ちょっとこれをご考慮いただいて、入れていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/626613?Template=document&Id=3362#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":20059,"voices":58}},{"id":"h25-20130805-8","meetingId":"h25-cm08","date":"2013年8月5日","dateIso":"2013-08-05","committee":"建設委員会","time":"午後 １時００分～午後 ４時２４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件整理しています。","topics":[{"id":"topic-01","title":"」を行います。 はじめに、(1)「平成２５年８月都営住宅入居者募集","agenda":"」を行います。 はじめに、(1)「平成２５年８月都営住宅入居者募集","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"倍率がどうなっているのか状況をお知らせいただきたいのと、７のところ、どういった中身だったのか説明を求めました。","respondent":"大串住宅担当課長","answer":"そのときの倍率が、募集数が２戸に対して１４１件の応募数ということで、７０.５倍の倍率というふうになっておりました。もう少しお時間をいただければと思います。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前回が２戸というのは、これ、単身ですか。中身を教えてほしいんですが、この倍率に対するお考えと今後について、何かあればお聞かせいただきたい。","respondent":"大串住宅担当課長","answer":"都営住宅につきましては、申しわけございませんが、あくまでも東京都の考えで行っている住宅施策です。募集数につきましても、なかなか私どものほうからどうこうというふうには言いづらいところがあるというふうに考えてあります。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"より安価な住宅を求めているというところにおいては、これだけの方が求めているということを意見として述べていただきたいのですが、いかがか尋ねました。","respondent":"大串住宅担当課長","answer":"多分都のほうに申し上げたとしても、全体としては１０倍程度の倍率におさまっているよという回答が返ってくるのかなというふうに考えております。都営住宅について私どものほうから何か申し上げるということは特には考えてございません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区も空き家がいっぱいあるというのだったら、空き家を安く提供できる方法とか、ぜひ考えてほしいと求めました。今日は意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認を１点だけです。それと、それに対する品川区の考え方はどう考えているのかということをお聞きしたいと思います。","respondent":"大串住宅担当課長","answer":"逆に、都営住宅の数としては変わっている可能性はありますけれども、公営住宅法に基づく住宅の数としては変わっていないというふうに認識しています。特にそういう形では聞いてはいないです。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"結構品川区内のものも多いような気がしたんですけれども、数的にはそんなに変わらないという認識でよろしいんですか。そういう動きなのかなというふうに認識していたんですけれども、品川区内の都営住宅の数というのは変わらないですよという認識でよろしいんか尋ねました。","respondent":"大串住宅担当課長","answer":"ここ数年、その数字は特に変更ないというふうに考えておりますけれども。先ほど申し上げたように移管の関係も出てくるかとは思うんですけれども、品川区に関しては特に数字の変動というのはないと考えております。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"壊されてほかのものに運用されているということでなくて、都営の３,４００戸の数は固定で変わりませんよというご認識なんでしょうか。じゃあ、取り壊されて売却したりというものは、品川区のどこかにまた都営という形で建てているという感覚なんか尋ねました。","respondent":"大串住宅担当課長","answer":"そういう意味では数の変動はあるんですけれども、それは都営はかなり前に多分廃止されているかと思うんですよね。だから、ここ数年の都営としてはそんなに大きく数字的には変わっていないというふうに私どものほうでは認識してるところです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"増やしていくのか、その辺の考え方は、もしもおわかりであれば説明を求めました。","respondent":"大串住宅担当課長","answer":"東京都が都営をどのようにお考えになっているかというところですけれども、大きく方針を変えたというふうには伺っておりません。こちらのほうに何らかの説明等々があるかと思いますけれども、今のところそういう形で、増やすとか。","id":"exchange-008"},{"speaker":"原委員","kind":"確認","question":"今ちょっと話が出たので、もう１回確認しておいたほうがいいかなと思いまして。２年、３年でということではなくて、その辺のお考えがあったらお教えいただければなと。","respondent":"大串住宅担当課長","answer":"すみません、長期的な住宅の施策ということでよろしいですか。","id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"ちょっとざっくりとした質問で申しわけないんですけれども、八潮が私は区の中では非常に気になるエリアであるものですから、もし何かあればお話をいただければと思うんですけれども。","respondent":"大串住宅担当課長、藤田都市計画課長","answer":"ただ、八潮の問題というのは、区としても高齢化が進んでいるですとか、そういったところで認識はしております。今後、八潮については… 居住者の高齢化に対応した住宅施設の改修や生活支援機能等の導入を促進し、将来的な団地再生の検討を進めるということで、基本的には住環境としての環境を守りつつ進めていきたいというのが基本的な考え方です。","id":"exchange-010"}]},{"id":"topic-02","title":"大崎駅西口地区および周辺地域におけるまちづくりについて","agenda":"大崎駅西口地区および周辺地域におけるまちづくりについて","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この点についてお伺いしたいんですけれども、なぜこうやって広げていくのか、当初、６０ヘクタールといわれていたんですけれども。要望書なんかも出ていましたけれども、この開発を見直してほしい、まず大きなところでお答えをいただきたいんですけれども。","respondent":"溝口都市開発課長","answer":"大崎西口駅前地区とか、まちづくりを今後も６０ヘクタールとあわせて大崎西口全体の地理発展のためにまちづくりを進めていきたいと考えておりまして。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"たくさんの開発地区があるんですけれども、この中で総事業費とか補助金とか、決まっている地域、金額が出ている地域を教えていただきたいんですが。","respondent":"溝口都市開発課長","answer":"現在、完了地区が１０地区で、事業中地区が西品川地区も入れまして４地区となります。全体の１４地区の総事業費といたしましては、約６,７０１億円が総事業費になっておりまして、約９３５億円の補助金を入れているものです。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全体的なことで教えていただいたんですけれども、せっかくなので西品川一丁目、組合が設立されて事業認可が下りたということなので、ここ、西品川一丁目地区に関して、総事業費と補助金、あと、参加企業の名前を全て教えていただきたい。","respondent":"溝口都市開発課長","answer":"補助金の金額といたしましては、約１４５億円の補助金が入るという計画になってあります。参加組合員が決まっておりまして、参加組合員につきましては、住友不動産が参加組合員という形で入っているものです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１回もとに戻って基本的な質問をするので数字で教えてほしいと求めました。特に西品川一丁目の地域のことをお伺いします。","respondent":"溝口都市開発課長","answer":"権利者の数ですが、土地の権利者としては７０名、借地権者としては１名の方が権利者という形になります。準備組合の参加状況ですが……。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何人なのかという人数で教えていただきたいのと、地権者のところ、マンションが何棟かありますよね。その辺はどういうふうに数えられているのか、ひとくくりでは済まないと思うんですが、そこはどういうふうに考えているのか説明を求めました。","respondent":"溝口都市開発課長","answer":"個々のお住まいになっている方一人ひとりの対応ということですが、今回、一人ひとりに当たっていく中で同意書を取得して進めていくものです。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"今、５８.６７と、その数字が何なのか、もう１回教えてください。この中で商業ベースのところのキーテナントというのが既にもうイメージに浮かんでいるのか、決まっているのか、それも説明を求めました。","respondent":"溝口都市開発課長","answer":"説明が悪くて申しわけありません。今後、事業を進めていく中で、募集をかける中で決まっていくものというふうに考えているものです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"数字のところで申しわけないんですが、全体の中の地権者の中で５８.６７人が同意しているということですか。これからの作業でその辺が詰められるということなのか、ちょっとそこを教えてほしいんです。","respondent":"溝口都市開発課長","answer":"先ほどちょっとご説明しましたが、その持ち分に応じた割合で権利者を１で割っていますので、その辺で端数が出るものです。今後、権利変換に向けて１００％の合意に向けて、しっかりと組合のほうから対応していくというふうに聞いているものです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"公示ですか、公告ですか、出さなかったらどうなるのかという点を一つ。","respondent":"溝口都市開発課長","answer":"それを丁寧に聞きながら対応していくというのが組合のやるべき筋だと思いますので、その辺がもし１カ月でという乱暴なお話があるようであれば。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"担当の事務局から個別にご説明に参りますので詳しくお願いいたします」と、３０日間以内に申し出をしなさいという用紙が届いているそうです。最後は出ていくかどうかという結論を今迫られている段階なんですけれども、そのことに対して区はどう考えているのか、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"そういった中での一定の方向として市街地再開発事業というのは地域の方の多くの意見を聞きながら進めてきたというふうに考えているものです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「近所の３人でみんなで話して転出を希望するつもり、具体的に代替がどうなるのかわからない、この心配に対してどうこたえるのかが１点です。この辺がなぜ住友不動産の単独のマンション建設が広くなってそこに税金が投入され、その辺の経緯、ここの点を説明するよう求めました。","respondent":"溝口都市開発課長","answer":"引き続き、そういったものについては、しっかり相談に乗って対応していくように組合のほうには指導していきたいと考えています。一緒になってまちづくりを考えていきたい、そういったもので今回、３.９ヘクタールという地区に対して市街地再開発事業を行っていくものです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"やめてほしいの意見書も提出しましたが、この方は本当にここ以外で再開発をしてほしい、出さなかったらどうなるんですか。超高層が住みやすくていい町だと言い切るわけですか、それが区民が願っている町だと言い切るわけですか、その点も説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その点を一つ伺わせていただきたいのと、あと、この地域には幾つか町工場もありましたよね。そういった町工場がこの開発の中でどうなっていくのか、ここの地域の町工場の状況をどういうふうに納得されているのか、その辺を説明するよう求めました。","respondent":"溝口都市開発課長","answer":"先ほど、それとも違う形で住宅で床を取得するのか、そういったことは基本的には権利者の方たちのご意向を踏まえて決めていくものと考えています。ただ、従前、権利者の方が工場を操業したいと言われたら、工場をできるような施設計画には今現在しているものです。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"工場のところは、やはりきちんと権利者の要望ということなんですけれども、どういう状況になるのかというのを伝える必要があると思うんです。私は行政としてぜひこのビル風の被害を科学していただいて、わかりやすく解明をする必要があると思うんですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"今回、そういったところと、アセス対象以外のところもアセスに準じた形で風害についてはしっかり調査等を行いながら事業を進めてきているものです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、そこを利用されていらっしゃる区民の方の声をぜひ真っすぐに受けとめて聞いていただきたい、私は強く求めて終わります。〔「対案を出せばいいんですよ、説得力があるから」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"確認","question":"いろいろ今議論がありましたけれども、何点か確認したい部分があります。風害そのものをこの地域で限定して特定して、原因を究明してそう対処していくというのは非常に難しいと思うんですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"そういった中で一概にその年は風が強かったからどうかというところの判断、また、考え方というのはあると思います。これまでもまちづくりを進めてきますし、これからもそういった視点でまちづくりについては進めていきたいというふうに考えております。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、やっていただきたいんだけれども、風害そのものを的確に測定することは私はできないと思うんです。さまざまな面でプラスになっていくと思うんだけれども、そういう観点で改めて品川区のお考え、再開発全体に対するお考えを説明するよう求めました。","respondent":"片田都市環境事業部長","answer":"地域を、地域の方々も十分認識した中で自分たちのまちをよくしていこうといったところを考えて、区としてもそれを支援してきたという経過があります。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問","question":"やはりさまざまな観点からすると、再開発は進めていくべきだと思っていますので、もう一度お話をします。それから１点、ここを防災機能を持たせる機能をつくっていくとか、そういうお考えは何かないのでしょうかということの質問です。","respondent":"溝口都市開発課長","answer":"かまどベンチ、または非常時に使えるマンホールトイレ、そういった広域避難場所に必要な機能はぜひ入れていきたいというふうには考えております。地域の防災に資する、そういった活動ができるような広場、または公園づくりに心がけていきたいというふうに考えております。","id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"確認です。大崎西口、その白くなっているところは、もう既に終わっていますよという認識でよろしいのかをまず。","respondent":"溝口都市開発課長","answer":"ちょっと五反田のほうが切れていますが、これが都市再生緊急整備地域ということで、６０ヘクタールに指定されているところです。西口地区で行きますと、一つ、補助１６３号線と百反通りの交差点部分の大崎西口南地区が現在事業中ということになっております。","id":"exchange-028"},{"speaker":"西本委員","kind":"確認","question":"これくらい緑地をつくってください、それらの実際の利用率というのは調べられるのか、区として確認はとれるのか。そのやりとりについて、どういう経過になっているのかを示すよう求めました。","respondent":"溝口都市開発課長","answer":"そのまま１００平米の床をもらえるかというと、また評価基準をしっかりつくって評価して、そういったものを換算していくという形になります。","id":"exchange-029"},{"speaker":"西本委員","kind":"提案","question":"これ、区として何％使われているのかという、そういうのを知ることはできるんですか。ほかに駐車場として貸すという形もできると思うんですけれども、また別の使い方として、その自由度はいかがか尋ねました。","respondent":"溝口都市開発課長","answer":"再開発に対する区の役割ですが、そういった方々がしっかり対応していくというのが一つだと思います。それに床を張ってほかの床に転用というと、基準法とかいろいろな兼ね合いがありますのでなかなか難しい部分もあるとは思います。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"それからもう一つのつくった後の転用ですね、これは研究してほしいなと思うんですね。そういうまちづくりの考え方というのも、やはり研究していっていただきたいなと思いますので、これは意見としてお願いしておきます。","respondent":"あべ委員長、鈴木防災課長","answer":"ご発言がないようですので、本件を終了いたします。自分たちの町は自分たちで守るという自助、共助の考えに基づいた地域ぐるみの防災意識の向上を図るという目的で実施をしているものです。","id":"exchange-031"}]},{"id":"topic-03","title":"地区総合防災訓練の実施について","agenda":"地区総合防災訓練の実施について","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"大崎第１、第２ということで、それ以上で以下でもない取り組みというのはしないわけですか。それのみの取り組みということか尋ねました。","respondent":"鈴木防災課長","answer":"先ほどご紹介しました大崎第１の大使館、それから大崎第２の区内在住の方の事前の呼びかけをして区としてかかわる参加はこの２件です。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、この３番と４番との関係で、ちょっと僕の読み方がうがっているのは、Ｄ級ポンプは大崎第１地区、大使館かあるから、それと、山形市の協力云々から品川第２地区というふうに、ここはまたどうなのか尋ねました。","respondent":"鈴木防災課長","answer":"日時、参加者の役割分担、こういうものを決めるのは全て地区の協議会で会議を開いて決めていただいております。品川第２地区、特にこの２地区に区として力を入れているとかということではなくて、地区ごとで決めていただいているです。","id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"そもそもこの地区防災訓練は、まずこれ、どこが主体になった事業なんか尋ねました。","respondent":"鈴木防災課長","answer":"主催はここの資料にありますように、各地区の協議会、品川区防災協議会の中の地区ごとにつくられた協議会です。その協議会の構成は、防災区民組織、つまり、町会・自治会になります。","id":"exchange-034"},{"speaker":"大沢委員","kind":"質問","question":"いや、そもそもこの事業を発案したのはどこなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"これ、区の事業ということで、今お話しいただきましたよね。主催が区であって、共催のほうが防災協議会という絵図のほうが正しいと思うんですけれども、どうなんか尋ねました。","respondent":"鈴木防災課長","answer":"説明がわかりにくかったかもしれませんが、主催はあくまで防災協議会です。ただし、それから正しい防災の知識を身につけていただくという事業がございまして、それをあわせて共催という形で実施するということになります。","id":"exchange-036"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、そこのところの位置づけというか、線引きが非常に曖昧な部分があるんじゃないですか。どこまでが区で、どこまでが防災協議会という、そこら辺の線引きはきちっとなっているんか尋ねました。","respondent":"鈴木防災課長","answer":"それから当日の資機材の運搬、設営の部分は、支援部隊の区のほうの事業として行うというのが大きな役割です。ただし、地区によっては、明確に線を引いて分かれているものではないということになっております。","id":"exchange-037"},{"speaker":"大沢委員","kind":"質問","question":"違うんですか。それとも区でやってくださいね、防災協議会が区から依頼があってこういうような形づけができたのか、どちらか尋ねました。","respondent":"鈴木防災課長","answer":"一番最初に訓練を始めたときのことに限定して言えば、多分区からの働きかけがやっぱりあったと思います。自発的に全地区でこういうふうに協議会が立ち上がって訓練を実施されたものではないというのはありますが、大きな役割は分かれていますけれども。","id":"exchange-038"},{"speaker":"大沢委員","kind":"質問","question":"共催はこれ、防災協議会じゃないとおかしいんじゃないかなと思うんですけれども、おかしくないですか。区でも予算を立てているんじゃないですかという話。","respondent":"鈴木防災課長","answer":"すみません、私の説明でちょっとご理解いただけるような説明ができていないのかもしれないですが、あくまで主催は防災協議会です。支援する側で、主体は地区の協議会というふうにやっているので、そこのところをどう説明したらいいですか。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問","question":"一つは、資料の中で、これ、品川区の公文書だと思いますので、１１月１０日のところの鈴ヶ森中学校、「ケ」の字は「ヶ」ですから、これはぜひ対応していただくよう求めました。","respondent":"鈴木防災課長","answer":"すみません、失礼いたしました。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それだと従来の人しか集まらない可能性があるので、これはつまり、もっと広く多くの区民の方々に参加してもらいたいと思っているはずなんですよね。多くの区民に参加していただきたいということを考えるのであるならば、動かしていくとか、品川区の考え方をまず説明を求めました。","respondent":"鈴木防災課長","answer":"まだ具体的なところを今ご報告できるところまで検討を詰めていないんですが、取り組みたいというふうに考えております。それともう１点、前年度の訓練の実施のときの参加者の実績をもとに計算するものとかもありますので、委員ご指摘のように。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"意見","question":"そのことについてのお考えを一つと、このカウントがもしできれば、非常に効果的ではないのかなと思ったことがあります。だけれども、広がりがないというところは皆さん共通の悩みがあるので、そういうことについて含めてご答弁をお願いいたしますとの意見を述べました。","respondent":"鈴木防災課長","answer":"この３者の連絡会議を去年から定期的に開くようになりましたので、連携をして呼びかけの部分もぜひ強化していきたいというふうに考えております。","id":"exchange-042"},{"speaker":"伊藤委員","kind":"提案","question":"提案といいましょうか、前に統合チラシの話をした記憶がありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"原委員","kind":"質問","question":"これはですから、前から一般質問でさせてもらったんですけれども、そういったことが出てきていると。ですから、その辺のところで特色の点が１点、その辺のところの今後の取り扱いがどういうふうになっているのか。","respondent":"鈴木防災課長","answer":"先ほど申し上げたように、初動の対応や正しい行動を身につけるということで、あえて毎年同じ訓練でやっていらっしゃる地区もあります。それが現状です。","id":"exchange-044"},{"speaker":"原委員","kind":"質問・要望","question":"大変なところがあると思いますので、その辺は注意深く、なおかつ、労力を使うことですけれども、一生懸命やっていただきたいなと。ですから、いろいろなところを持たなくてはならないという、その辺についてのご意見があったらお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"各関連機関と連携しての情報提供についてのお尋ねだと思いますが、先ほどご意見いただいたものとあわせて、各機関とよく連携をして相談しながら進めていきたいというふうに考えております。","id":"exchange-045"},{"speaker":"原委員","kind":"意見","question":"個別に突拍子もない意見もたまにはあろうかと思うんですけれども、その辺はご苦労が重々わかりますので、頑張ってほしいと求めました。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"木村委員","kind":"質問","question":"ですから、そのときには本当に区民の皆さんというのは大変な問題として、一番重大な問題としてたぶん捉えていたと思うんです。時期が過ぎていけば薄れていっていると思うので、その点を何か方法があれば、何かお考えになっているのかどうか説明を求めました。","respondent":"鈴木防災課長","answer":"災害自体の怖さなり、今年は今まで防災区民組織を通しての研修の実施しかなかったものを、区民大学で防災のコースを１本つくっていただきました。","id":"exchange-047"},{"speaker":"木村委員","kind":"質問","question":"区民は３６万人以上の方々にそれを配布ということは、それからＣＤですか、そういう方法は不可能かどうか説明を求めました。","respondent":"鈴木防災課長","answer":"それが毎年二、三種類新しいものが出れば買うようにはしております。そのときには、今後もそういうような工夫を凝らして、少しでも多くの方に正しい知識なり情報の提供をしていきたいというふうに考えております。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その他の関連団体というのは一体どこなのか教えていただきたいのと、安否確認というのが具体的にどういう形に捉えていらっしゃるのか伺いたいのと。ぜひ広げていっていただきたい、こういう取り組みは広げていただきたいなと思うので、その辺も説明を求めました。","respondent":"鈴木防災課長","answer":"マンションへの対応ですけれども、そこでいろいろなことを考えたり、町会に加わらないというケースも増えてきているようです。それから、例えば、そういうような形での備えがたぶん外国人の方への対応には比較的すぐ取り組めて有効かなというふうに考えているところです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最初に質問した訓練項目のところも、やはり実りのあったところの交流をぜひ伝えあって、よりよいものにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問","question":"今までずっと質問を聞いていて思ったんですけれども、マンション対策、それから個人情報の話も出ました。よりよい総合防災訓練ができていくことのほうが、私は非常にこれからの行政をやっていくと思うんだけれども、お考えを説明するよう求めました。","respondent":"鈴木防災課長","answer":"実は、各地区ごとにかなり取り組みが違ったんですが、地区ごとの違いをかなり明確に出るような一覧の資料にしてお渡ししたりしております。その考え方はやはり重要だと思いますので、それからいいものの共有、バランスをとりながら進めていきたいというふうに考えております。","id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、結果としてお互いに関連ができていくと私は思うので、それは口で言うのは簡単でやることは難しいのかもしれない。それをぜひさまざまな形で検討して、ぜひ来年度の防災訓練には展開していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"じゃあ、ポンプはありますけれども、倉庫からよいしょよいしょ出してきて、水はどこにあるんですか。町会にしてみれば逆効果、とられちゃったというふうにならないように何かいい方法を考えていただけないかなと思いますが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"いい方法はないのかというのは、相談をして、地域と進めていきたいと思います。そのときにも説明はさせていただいたんですが、その部分を支援したいということなので、委員ご指摘のように。","id":"exchange-053"},{"speaker":"西本委員","kind":"意見","question":"常に実際に使えるように何か区のほうからアプローチができればお願いしたいなというふうに思っております。地域のステップにといけない部分があるので、本来は地域の中でやっていくべきことなんでしょうけれども、ぜひできる範囲でお願いしたいと思いますとの意見を述べました。","respondent":"鈴木防災課長、あべ委員長","answer":"こういう中身、それが町会といいますか、防災区民組織のほうにしっかりとつながっていくようにということで話をさせていただきたいと思います。ご発言がないようですので、本件を終了いたします。これは天王洲のほうで実施しまして、それからそのほかの関連する場所で実施するというところで、総合的な訓練にしたいというふうに考えております。","id":"exchange-054"}]},{"id":"topic-04","title":"区内一斉防災訓練・職員防災訓練の実施について","agenda":"区内一斉防災訓練・職員防災訓練の実施について","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"それだともったいない気がするんですけれども、いかがでしょうか。、答えるよう求めました。","respondent":"鈴木防災課長","answer":"今ご質問いただいたような専門的な災害対応の活動をする組織の参加をいただくということで、ご質問いただいたように。今回はそのときの第１回の課題の解決と、第２ステップということで、ここまでという想定で実施させていただきたいという考え方です。","id":"exchange-055"},{"speaker":"伊藤委員","kind":"確認","question":"救助のプロの方々でしょうから、あと２年後なら２年間の協力を組んで、あくまで想定だけれども全部出ているわけじゃないですか。確かに２年目ということはわかるんだけれども、さらにそういう質的なレベルアップをしていく必要があると思うんですが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"実践に則したものにどんどんレベルアップする必要があると思いますので、あまり１０年も２０年も猶予があるものではないというふうに考えておりますので、できるだけ早くより実践的なものにレベルアップを図るように相談をしていきたいというように思います。","id":"exchange-056"},{"speaker":"大沢委員","kind":"意見","question":"すみません、さっき説明の中では、自衛隊による付近の偵察活動とたしかおっしゃっていた。もう１回その前後の脈絡というか、その前後だけもう１回説明をお願いしたいんですけれどもとの意見を述べました。","respondent":"鈴木防災課長","answer":"昨年度までの職員の初動対応訓練のときには、そこでここに書いてあるような建設防災協議会の参加もいただいた災害復旧対応の訓練をしておりました。たぶんお願いできても陸上からの車両による搬送と訓練の参加というところで、今、調整をしています。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"それをどうされるのか、職員の立場がちょっと明確ではないなと思っているので、そこをどういうふうに考えているのかということをお聞きします。この経緯も含めて大変だというところがどこまで認識されているかなと思っているんですが、その状況をお伝えほしいと求めました。","respondent":"鈴木防災課長","answer":"連携なり支援するという仕組みを組んでいますので、ぜひ各避難所の連絡会議が活発になるようにサポートしていきたいというふうに考えております。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり訓練が必要ですから、これからも続けてほしいと求めました。一番なれているところがいいですから、これも継続的に自衛隊の方々に協力体制を敷いて訓練ができるように体制を工夫していただきたい思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"意見","question":"全体像があんまりよく見えないんですが、規模的に各地区の避難所、昨年はすごくばらつきがあったと思うんですね。昨年はヘリで物資輸送、今年度はどういう状況を想定して何を依頼していくのかというあたりが明確になっているのかどうか、その辺を説明するよう求めました。","respondent":"鈴木防災課長","answer":"それから職員を含めた取り組みの全体像ですけれども、設置、会議が全体をコントロールしながらやっていただくということになります。今年も基本的にはそういうところを中心に相談をしてお願いすることになるというふうに考えております。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"関係機関のところ、大体去年と同じで、ヘリのところは、自衛隊に関しては陸路での物資の輸送をお願いするというところでは、ＪＴ跡地を中心にやっていくということでよろしいのか尋ねました。","respondent":"鈴木防災課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"そこら辺の中身を少し教えていただきたいのと、本当に地域の方も参加をというふうになっているんですか、その辺の状況を説明するよう求めました。","respondent":"鈴木防災課長","answer":"それから、ステップアップする２回目の中身や実施についての協議ですが、各協議会ごとに今ご相談をいただいているところです。もしくは１会場だけれども参加者を増やすことということで、主にどちらかといえば、会場が増えたことで参加者の増になるというふうに考えております。","id":"exchange-062"},{"speaker":"こんの副委員長","kind":"質問","question":"それはいかがでしょうかということです。お一人お一人３日分のお水を用意しましょうと盛んに言われている中で、ここに書いてある応急給水というのはどういったものをイメージしているのか。","respondent":"松代防災まちづくり事業部長、鈴木防災課長","answer":"ですから、ここに予定で３００人ぐらいを今予定しておりますけれども、そういったものを目指して訓練をしていければというように思っております。医療関係ともいろいろと協議を進めているものですから、こういったものも探っていければ… 一つは、ご存じのように、区内に４カ所あります東京都水道局の応急給水所です。この二つが給水の中心になりますので、その辺のどちらか、もしくは両方がこのときに準備が整えばやりたいというふうに考えているところです。","id":"exchange-063"},{"speaker":"こんの副委員長","kind":"質問","question":"ぜひ２回目、３回目とするところで、私たちも協力して進めていきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"あべ委員長","kind":"質問・要望","question":"それで、先ほど防災課長が言われた発災型まちかど訓練、これ、シェイクアウト訓練のことでしょうか、ですよね。私も幾つかの自治体の実践を伺いまして、非常に品川区のような都市部でも魅力的な訓練であろうかと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"}]},{"id":"topic-05","title":"全国瞬時警報システム（Ｊアラート）による全国一斉試験放送について","agenda":"全国瞬時警報システム（Ｊアラート）による全国一斉試験放送について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"国の送信で始まるので変えられないということなんですが、このＪアラートが始動するに当たって、国から東京都知事とか段階を経ているんですよね。そこの流れを教えてほしいのと、今回は「試験放送です」ということでこういうふうに流れますが、実際のときはどうなるのかというのを説明するよう求めました。","respondent":"鈴木防災課長","answer":"それから２点目のほうが、実際の本番のときのメッセージの内容ですね。これも登録して自動音声でやらないと、時間がないときに職員が一々放送するわけにいかないので、そういう仕組みで動く機械です。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"その辺の心構えがあるじゃないですか。実際はどういう、前に福井県ですか、そういうことのチェックというのはきちんとされて……。","respondent":"鈴木防災課長","answer":"横浜だったか川崎だったかありましたけれども、全て人為的なというか、操作ミスです。そういうことになりますので、実際の全国一斉に流れるときには基本的には誤報は考えにくい仕組みになっております。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"今回の、これが正常に動いたかどうかというのは、どういうふうに検証していくんですか。お願いします。","respondent":"鈴木防災課長","answer":"ちょっと確認は１軒１軒とれないんですけれども、放送の中身が違うことで鳴らないということは基本的にはありませんので、それは大丈夫だと思います。四つの商店街については、個別に連絡をさせていただいて、放送が無事できましたかという確認をするということで考えております。","id":"exchange-068"},{"speaker":"こんの副委員長","kind":"質問","question":"２回行われるということで、１１時と１１時半と２回実施というのは、これは同じものなんでしょうか。この中身を。","respondent":"鈴木防災課長","answer":"１１時と１１時半の２回の放送の中身ですが、基本的には同じ放送というか、放送内容の電波が来るというふうに聞いております。ですので、２回ともいきなり「これは試験放送です」という言葉が流れてチャイムで終わるというふうに聞いております。","id":"exchange-069"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"教えていただきたいんですけれども、１１時と１１時半で試験の種類が、これはどういうあれなのか。どういった、どういうものなのか、説明を求めました。","respondent":"鈴木防災課長","answer":"多分その２種類のやり方を放送するということで２種類の情報があるんだと思いますけれども、手元になかったので申しわけありませんが、区の中で流れる放送の内容は２回とも一緒です。","id":"exchange-070"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"でも、全体的にやはり２泊３日の行程がいつも位置づいているというところにおいては、その辺も工夫があるのかなと思いました。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"この日程は、２３日、２４日、２５日ということでフィックスということでいいんですか。それとも、これからの交渉で変わる可能性がありますよという認識か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"対策お疲れさまでした。貯留池の中がどの程度だったのかが把握できているかどうか、それが１点と、教えてほしいと求めました。","respondent":"奥田河川下水道課長、鈴木防災課長","answer":"大体実績としては１０％強ぐらい入ったというふうに聞いております。まだ確定はしていなんですけれども、そういうような形で都のほうからは聞いてあります。 床下浸水ともに、これは川によるものではなくて、道路だとか低地部にたまった水による内水の被害になります。二葉三丁目付近、このあたりが集中して同じようなエリアに床上、床下浸水が出たエリアということになります。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域、結構あちこちで、低いところに飲み込まれなくて集まってしまったという感じなんですかね。みんなびっくりしたということで、ぜひ被害があったところに説明をしてほしいという声が出ていますけれども、受けとめていただきたいんですけれども。","respondent":"奥田河川下水道課長","answer":"１時間５０ミリの降雨に対応できる対策という形をやっておりまして、その分が周りより低いところの低地であふれたというような結果になってあります。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にしますけれども、空気の関係で噴き出したというあたりでは、新しくできた幹線のところが機能していなかったわけではないんですか。調査中ということなので、はっきりしたらやっぱり地元にわかるようにご説明をいただきたいと思うんですが、いかがか尋ねました。","respondent":"奥田河川下水道課長","answer":"貯留容量で大体３万５,０００トンぐらいあるんですけれども、被害想定に応じた形で今、調査検討をやっていると伺っております。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問","question":"８月１日で、プラス被害のところということで、最後の米印のところ、「被害は、他に区民から」、これの取り扱いについて説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"大沢委員","kind":"確認","question":"いや、違います。一番下の確認中ということなので、確認であれば、そこだけ。","respondent":"鈴木防災課長","answer":"失礼いたしました。一番下の注意書きのほうの５件ですね。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"認定、非認定とあるんですけれども、これは何ですかというのと、認定と非認定というのはどこで区分けがされるのでしょうかということ。それから見舞金なんですが、これ、床上と床下で金額は違うんか尋ねました。","respondent":"鈴木防災課長","answer":"浸水した上に、例えば機械であるとか、持っている商品だとかが水に浸かって被害が出た場合にだけ見舞金が１万円出るということです。ですから、非認定のところは当然事業所なので、認定を受けずに見舞金が出なかったというケースになります。","id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/890615?Template=document&Id=4080#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":67359,"voices":204}},{"id":"h25-20130805-9","meetingId":"h25-cm08","date":"2013年8月5日","dateIso":"2013-08-05","committee":"文教委員会","time":"午後 １時００分～午後 ３時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"(1)平成２５年度のいじめ等の対応（目安箱・アイシグナル・専用電話での相談件数等）","agenda":"(1)平成２５年度のいじめ等の対応（目安箱・アイシグナル・専用電話での相談件数等）","exchanges":[{"speaker":"南委員","kind":"確認","question":"もう少しきちんと、どういう状況でそういう判断に至ることができたのかというあたりをしっかり確認しておきたいと、そういう思いで質問をします。そのあたりのことを伺いたいと思います。","respondent":"渋谷指導課長","answer":"南委員のご心配のとおり、いじめについては、これで万全だというような調査の方法というのはないというふうに私どもも認識しております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"その辺があれば、ぜひご紹介をしていただきたいし、考え方も含めて伺いたいなというふうに思っています。それとあと、いじめ根絶協議会のほうについてもいいですか、一緒に報告があったから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと私としては理解できなかったので改めて伺いたいと思うんですけども、自殺とか重大事故、もう一度確認していただきたいなと思いましたので。学校現場はまたそこが粛々とというところでは、設置した意味がないので、どういうふうに考えていくのかなというのを確認しておきたいと思いました。","respondent":"渋谷指導課長","answer":"Ａ３判で前回お示しした中の右側の部分、その防止に取り組むというような形をつくっていけたらなというふうなことは強く思っているところです。この根絶協議会の中身については、役員校長会、また校長連絡会等で各学校にはフィードバックをさせていただいているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"そういう管理職の会議を通じてフィードバックするのは当然だというふうに思うので、ちょっと再確認できればいいなと思います。このホームページ等の文章のところはちょっと確認いただいてからで全然結構ですので、ちょっとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"目安箱の合計の１２６件なんですけれども、数字上かなり高いので不安が起こるなと思うんですけれども、この１２６というのは、１２６人というふうな書き方をされているのか、それとも同じ子ども・生徒が何度もメッセージを出す者も中にはあるのか、その辺の分析というのはされているんか尋ねました。","respondent":"渋谷指導課長","answer":"基本的に記名で入っているものについては、今委員おっしゃったとおり、普通、同一人物が入れたかというようなことについては確認ができているところでありますが、基本的に余り重複のない数字というふうにご理解いただいていいと思います。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"名前を記名しない匿名にしても、何かのメッセージを出しているので３０件と、それとあといたずらのものが１４件ですか。同じ不明なんですが、ひとくくりにしないほうがいいんじゃないかなと、ちょっと意見だけ述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"大倉委員","kind":"質問・要望","question":"どういうふうにこれを捉えているのか教えていただきたいのと、教員や学校への苦情・要望のところで、その学校の６年生の学級だったり。これもちょっと数がどうなっているのか教えてほしいと求めました。","respondent":"渋谷指導課長","answer":"ですから、今回３種類の手だてを講じましたが、さらに検討していく必要はあるんだろうなというふうに一番課題認識を持っているところです。","id":"exchange-007"},{"speaker":"大倉委員","kind":"意見","question":"ぜひそういった発達段階における子どもたちの相談への対応というのをいろいろ検討して取り組んでほしいと求めました。この２３件については、どういう理由かはわかりませんけども、子どもたちにいい教育が与えられるように取り組んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"重大な案件はないということなので、もうちょっと詳しくお聞きしたいんですけれども、現実にいじめと認識される事態があったのかどうか。教育委員会、それに対してしっかりとした解決が今見えているということで受けとめていいのかということでまず最初にお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"教育委員会のほうにこれはいじめですというふうに件数として報告が上がっているものが改めて目安箱に報告されているものと両方あります。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"見守るというような立場になるのかというところで確認をさせていただきたいのと、答弁の中でもあったんですけれども、ＨＥＡＲＴＳとは別に。ＨＥＡＲＴＳはＨＥＡＲＴＳでしっかりやっていただくことが大事なんですけれども、そこら辺に対するご認識をちょっとお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"スクールソーシャルワーカーが継続して経過を追っているというようなケースもあって、本当にケース・バイ・ケースで対応している。学校のスクールカウンセラーにつなぐというふうな方法で継続して観察していこうというような対応をしています。","id":"exchange-010"},{"speaker":"塚本委員","kind":"意見","question":"よくわかりました。大変新しい取り組みであると同時に、期待というとちょっと言葉が適切じゃないかもしれませんけれども、今後ともよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"高橋委員","kind":"質問","question":"児童・生徒がこういうのがあっていいとか、そういうような声があったか、そういうところからの反応というんでしょうか、評価をお聞きしたい。あるいはアイシグナルもそうですけど、投書があるかもしれないんですが、夏季休業中の体制はどういうふうになっているのかちょっとお尋ねします。","respondent":"渋谷指導課長","answer":"すぐにその日のうちに対応すると、その日、あるいは翌日には対応するという体制で取り組んでいるところです。すまいるスクールの対応というのは、校長先生を中心にすまいるスクールの職員から話を聞き取ったりとかして組織的に対応していく。","id":"exchange-012"},{"speaker":"高橋委員","kind":"質問","question":"じゃ、すまいるスクールの場でもどうかとかというのは、学校を経由して校長先生のほうからやっていただくということなんですか。すまいるスクールでの現状をどう把握して、どうしようとされるかということです。","respondent":"渋谷指導課長","answer":"基本的には同じ学校の子どもですので、かなり密接な連携をとらせていただいているところです。","id":"exchange-013"},{"speaker":"沢田副委員長","kind":"質問","question":"１点だけちょっとお伺いしたいんですけども、私も率直に言って、１カ月ちょっとの間でこれだけの件数があるというのは多いなと思っています。この辺を教育委員会としてどのようにこの結果を捉えられているのか尋ねました。","respondent":"渋谷指導課長","answer":"スクールバディ・プログラムにいじめを見逃さない、傍観者をつくらないというところが大きな目的の一つとして挙げられているところです。周りの子たちが見て見ぬふりをしないような、そんな子どもたちにぜひ育てていきたいと強く思っているところです。","id":"exchange-014"}]},{"id":"topic-02","title":"ひとり親家庭学習支援事業の実施","agenda":"ひとり親家庭学習支援事業の実施","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"中学生が２０名、現実的に希望される方のほうから直接品川区のほうに電話なり申し込みをするということなんですか。３点です。","respondent":"伊崎子育て支援課長","answer":"こちらは応募の状況と終わった後の感想等も含めまして、総合的に事業の方向性についてはそのときにまた検討をいたしてまいります。こちらはそもそもひとり親家庭の支援を目的にして設立されているＮＰＯですが、ごめんなさい、あと勉強会などをやっているところです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"全体で１０日間という期日なんですけれども、今何年も前から品川区は夏休みのときにサマースクールというのをやっていますよね。サマースクールとの関係では、どういうふうに調整を図っていくのか、そのあたりの考え方みたいなところがあったら説明を求めました。","respondent":"伊崎子育て支援課長","answer":"それから、夏休みの宿題の対応などもやっていくということで、この時期にいたしました。それから、サマースクールとの兼ね合いですが、サマースクールは７月中に実施をしておりますので、そちらには影響がないです。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"今幾つかの質問のやりとりの中で、この中で別に時間を設けて親御さんと一緒にするとか、そういうイメージなんでしょうか。もう一つ、プロポーザルという手法でということでしたけれども、応募した法人はほかにあったのかどうかお伺いしたいと思います。","respondent":"伊崎子育て支援課長","answer":"お子さん２人に対して指導者１人、１対１で、マン・ツー・マンでついて指導するという方法をとってまいります。それから、プロポーザルに参加した事業者ですが、キッズドアを含めて２社ございました。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、学校との連携とかというのはできないのかなと思いましたので、ちょっと教えてほしいと求めました。","respondent":"伊崎子育て支援課長","answer":"今回初年度ということもありまして、今回は主に福祉的な側面での対応を図っていくというところからスタートいたしました。今後そういったことも含めて、また相談を教育委員会としていければと考えています。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"こういうのもありますので利用されたらどうですか、こういうこともありますので取り組みに参加されたらどうですかというのも必要かなと思いますので。ちょっと質問で教えていただきたいんですが、小学校４年生から６年生、どういう事情があって分けたのか。","respondent":"伊崎子育て支援課長","answer":"６学年にわたるお子さんにお教えするということで、一つは教える側のそういったところでの教え方が違ってくるというのがあります。小学生は小学生で、間にいろんなイベントを入れながら講座を進めていくというのもありますので、そういったことで時間を分けてお願いするです。","id":"exchange-019"},{"speaker":"高橋委員","kind":"質問・要望","question":"ですから、ぜひ連絡を密にしていただきたいと思うんですが、学校教員の先生方はなかなかこういうのを知る機会が逆に言うとないんでしょうか。そこをちょっとお伺いしたいんですけど。","respondent":"渋谷指導課長","answer":"やっぱり区からの情報提供がないと、なかなかこういう福祉的な側面の支援というのは厳しいのかなというふうに思っております。三者面談を実施するところが多うありますので、１学期中にまた情報提供いただければ、学校のほうへ周知をしていきたいというふうに考えております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"４０人、もう少し広げていただきたいというのはあるんですけども、そういう体制で今後の課題として取り組んでいただきたいというふうに思っています。世帯というのかな、子どもの数になるのかしら、どのくらいいらっしゃるんでしょうかね。","respondent":"福島青少年育成課長、伊崎子育て支援課長","answer":"児童扶養手当につきましては、１,８００人余です。ただ、児童扶養手当を受けていなくても、ひとり親家庭というのはありますので、それプラスというふうに考えていただければと思います。今、ひとり親世帯に特化しているんですけれども、年齢が小学校４年生から中学３年生までと限っておりますので、その中の何割かになります。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"受給者世帯が１,８００世帯と、モデルという感じなんだろうとは思うんですけども、やっぱり対象の人数をぜひ増やしていただきたいと。両方が届くことになると思うので、そういうやり方も含めて検討していただきたいなと思っていますが。","respondent":"和氣学務課長","answer":"就学援助とは質が異なるものですので、基本的にそれはそれで別に周知方法を考えておりますので、よろしくお願いします。","id":"exchange-022"},{"speaker":"南委員","kind":"意見","question":"皆さんに行き届く、そういう情報提供ができるようにするにはどうしたらいいのかという角度で検討していただければいいというふうに思っておりますので、その辺はよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"大倉委員","kind":"質問","question":"２名というのはちょっと数が少ないなというのも先ほどもありましたが、ちょっとそこの辺だけどう捉えているかというか、考えているかというのを教えてもらいたい。","respondent":"伊崎子育て支援課長","answer":"中学生ですと１人で行けるというのもありますし、そういったことで集まりぐあいが異なるのかなと思います。実施した結果、まだ募集期間がありますので、もし人数については集まらなかった場合には検証していきたいと考えています。","id":"exchange-024"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろんな意見を聞いて、よりいいものを、受けやすいものをつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-03","title":"悠々ボランティア育成講座の開催","agenda":"悠々ボランティア育成講座の開催","exchanges":[{"speaker":"南委員","kind":"質問","question":"私もそのことを質問しようかなと思っていたんですが、具体的にどういうふうに、いろいろありますよね。どういう場面で、どういうふうにしていくのかというのがちょっとよく見えていないので説明を求めました。","respondent":"伊崎子育て支援課長","answer":"私たち実施する側といたしましては、５５歳以上の方で、こういう講座を企画いたしました。ですので、実施をしながら、そこは探っていくというか、お互いに考えていこうと思っているところです。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"では、その成り行きを見守るしかないという感じなんですかね。見守っていきたいと考えています。","respondent":"伊崎子育て支援課長","answer":"前提としましては、児童センターでやっているさまざまな地域との連携の事業、あとはすまいるスクールで地域の方に参加していただいている教室などもやっておりますので、そういったところにご参加、特技に合わせた形でご参加をいただければよろしいかなと。","id":"exchange-027"},{"speaker":"南委員","kind":"意見","question":"今、そういう４回１クールで講義を受けていくというところで、つないでいくという考え方で取り組んでいくということですよね。そこがないと、予算が７３万円といえども、ちょっとどうなっちゃっているのかなという気がしたので聞いたんですけど、わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"１点だけお伺いしたいと思います。講師というのはどういう方を予定されているのか教えてほしいと求めました。","respondent":"伊崎子育て支援課長","answer":"現在のところ、９月の予定ということで、１クール目の予定です。こちらは４回のうち３回に講師に来ていただくことを予定しておりまして、シニア世代のボランティア活動についてというような講義をいただく。","id":"exchange-029"}]},{"id":"topic-04","title":"国家公務員宿舎「品川寮」の活用","agenda":"国家公務員宿舎「品川寮」の活用","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"幾つか確認したいと思うんですけれども、待機児解消策ということで取り組んでいくということでいいかどうかを改めて確認したいのと、そして。まだちょっとあるんですけど。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほど申しました今年の４月に入りましてから、やはり待機児童対象の保育所等の整備について優先的に処分するというふうな方針です。４点目の借地料につきましては、国からまだオーケーですよという回答が来ておりませんので、国も不動産鑑定はしておりません。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、そのあたり、今後の保育需要との関係でどういうふうに見ているのかということを改めて伺いたいと思います。つまり、もう一度確認なんですけど、一定の保育需要がずっと続いていくというふうに考えているのかどうか、そのあたりを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"平成３０年ごろまでは一定の人数を含めまして、今後新しい制度に変わっていく中で、保育需要は高どまりが続くという認識でおります。国の通達では１０年以上３０年以内となることに留意することという通達が出ておりますので、その範囲の中で検討してまいりたいと考えております。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"あるいは品川区がきちんと運営をしていくと、これからの検討ですから、ぜひその辺は考慮していただきたいというふうに思っています。意見と要望を含めてですけども、考え方も含めてあったら、改めてお願いしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"借地期間の期間ですけれども、事業用に締結するときには１０年から３０年ということで、ちょっと私、行財政改革特別委員会のほうでご説明されたのは、居住用の施設系のときは５０年までというふうなスキームもあったかと記憶しております。","id":"exchange-032"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問","question":"教育環境をどういうふうに整えるとか、そういうところの議論にとどまっていくべきだというふうに思うので、文教委員会の性格としては。ですから、ちょっと気になったところなので、その辺について委員長に伺っておきたいなと思ったんです。","respondent":"若林委員長","answer":"社会科ではないですよねというぐらいの認識では、そこら辺のそもそも論をしっかりと聴取してまいりたい、このような仕切りの意味です。見つけていけるのかな、あれば見つかるのかな、このような思いです。","id":"exchange-033"},{"speaker":"南委員","kind":"意見","question":"成果や課題となると、その成果がどうなのか、悪い、もう少しきちんとやれみたいなことになると、いいのかなと。どういうふうに、こういうのが出てきたんだろうと思うんですけども、ちょっと言葉は悪いんですけど……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"南委員","kind":"意見","question":"教育の介入というと、言葉が変ですけど、なっちゃったら困っちゃうなとちょっと思ったので、その辺どうなのかなというのがちょっと気になったとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"その辺というのはあまり心配することはないんですかね。〔「大阪を意識し過ぎ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"若林委員長","kind":"質問・要望","question":"発達障害のある幼児への支援の取り組みに関しましても、あわせてお話を伺うことができないかと考えているところです。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/646567?Template=document&Id=4798#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":35973,"voices":108}},{"id":"h25-20130805-5","meetingId":"h25-cm08","date":"2013年8月5日","dateIso":"2013-08-05","committee":"総務委員会","time":"午後 １時００分～午後 １時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"品川区長期基本計画の中間見直し","agenda":"品川区長期基本計画の中間見直し","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"事務局からの発言は求めないこととしたいという仕切りがあったということを、第３回目の委員会を傍聴してちょっと不自然な感じがしたんですね。もっと区に質問するということもきちんと保証して、もっと時間を増やすとか、いかがか尋ねました。","respondent":"黒田長期計画担当課長","answer":"限られた時間の中で委員の発言する時間を確保するという意味で、事務局と一問一答形式の質疑は行わないというような委員会の運営です。各分野についてどのようなお考えをお持ちなのかということをお聞きしまして、計画に反映するという形で進めていきたいと考えております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはり区がどう考えるのか、委員がどう考えるのか、まとめてでも構わないと思うんです。私はそこら辺のところをぜひ保証されるような、深まるような委員会の運営にしていただきたいと思っていますけれども、もう一回ありましたら。","respondent":"桑村企画部長","answer":"ほかの委員の方はその点についてどうお考えになるのかという形で、この委員会の場合、大切なんじゃないかと委員長が判断されたんだと思います。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ要望なんですけれども、広報の多分１面でお知らせいただくようになると思うんですけれども、私は区としてぜひ開いていただきたい。原本というか素案そのものは、区民にわかるような形で、どこにどういう形で配布されるのかというところも説明を求めました。","respondent":"黒田長期計画担当課長","answer":"２点のご質問です。１点目の説明会を区として開催してはどうかということにつきましては、説明会を開催する予定はございませんが、そちらのほうをご覧いただきまして。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして区民から意見をいただいていくというところからしても、ぜひ説明会をしていただきたいということを強く要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どれを強く訴えていって、改訂をしていくんだというところの趣旨を教えてほしい。改めてそこら辺の期間とか、今後のそういう部分の意義というか、それを教えてほしい。","respondent":"黒田長期計画担当課長","answer":"緊急的に対応しなければならないということ、なかなか先が見据えないところで言いますと少しわかりにくいという面があろうかと考えています。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで協働でもいいと思います。こういうことを５年間でやってくるんだなという雰囲気がなかなか見えてこないから、そこら辺の考え方だけ、もう一度改めて説明を求めました。","respondent":"黒田長期計画担当課長","answer":"ご近所づきあいが基本になるというところがありまして、その中でいわゆるお互いさまというところが共助の基本的な部分だろうと思います。どうしても事業の実施主体でありますとか、この点につきましては今後さらに検討して、検討させていただきたいと考えています。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お願いだけしておきます。どこの段階でもいいですけれども、それにこの長期基本計画の改訂があるんだということだけはご理解いただければなと、これは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"中小企業センター受変電設備改修その他電気設備工事請負契約","agenda":"中小企業センター受変電設備改修その他電気設備工事請負契約","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"教えていただきたいんですが、予定価格が１億６,４００万円余ということで、例えば当初予算がありますよね。当初予算がどれくらいあって、今後補正も出てくるのかどうかわからないので、ここら辺のところの話を説明するよう求めました。","respondent":"平澤経理課長","answer":"本件につきましては、先般、設計労務単価の改定につきまして、本委員会でもご説明したところですが、５月２０日から新労務単価を適用するです。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"１億５,０００万円だとして、だけど落札が１億４,９００万円で、１億５,０００万円だったらその中におさまったから補正にならないのか。当初予算との関係で、当初予算が１億５,０００万円なのかどうかわからないけれども、それにおさまったのかというあたりの仕組みを教えてほしい。","respondent":"平澤経理課長","answer":"こちらの予定価格は、新たに新労務単価に基づいて積算をし直すものです。したがいまして、予定価格の中で入っていたということで、これは補正をしなくても入札が行えたです。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"９月補正とか１２月とか、今年の１年はそうなりますよと、その考え方を教えて。そういうものが幾つもありますよと理解しておけばいいのかなということを説明するよう求めました。","respondent":"桑村企画部長","answer":"６月補正当時、中でのみ込めるという基本的な考え方でやりますので、これについても当然新労務単価で計算をしているわけであります。ただ、それで例えばほかの工事にも少し回させていただいて、いわゆる議会にかからないものについてはそうするというのが今の考えです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"４ページのほうについて伺いたいんですけれども、電気時計の設備更新で老朽化というのが理由だったと思うんですけれども、５９台の電気時計を今度は電波時計にして、体育館だけが電気時計になるんですが、この電波時計と電気時計の精度とかコストとか、どれぐらい違うものなのか説明を求めました。","respondent":"小林施設整備課長","answer":"時計をそこに設置しまして、管理室のほうまでいわゆるコードが流れていまして、そこで操作ができるんですね。配線が副受信という部分についても用意をしないといけないものですから、そちらのほうが高額にはなっております。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"自動火災報知機なんですけれども、これは３２５カ所とありますけれども、これは何年で更新するんでしょうか。例えば部屋で個別に空調のコントロールもできるんですよねということと、それを設置した理由というのを教えていただけませんか。","respondent":"小林施設整備課長","answer":"個別に出したという意味合いで書いておりますので、ちょっと確認はしておりませんけれども、各部屋では空調の温度設定というのはできないと思います。逆に言うと、個室での個別の温度調整というのはできないと考えています。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"各室ではできないという意味は伺いましたけれども、ちょっとそこの点はどうかなと思いまして、ちょっと考慮してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このエレベータというのは、それが新耐震の基準になるのかどうか、そこのところを教えてほしいと求めました。そのときに難聴者のための磁気ループの設備をぜひつけてほしいという要望をいただいているんですけれども、その点はいかがか尋ねました。","respondent":"平澤経理課長、小林施設整備課長","answer":"１点目と最後の難聴者のお話ですが、まず難聴者のお話ですが、今回の工事では入っていないというお答えしかちょっとできません。こういった資格をつけさせていただいているところです。 耐震については、これは建物自体は耐震化が済んでおります。非常時に停止するとか、そういうところは一部ついているんですけれども、これについては今現在、施設設備課のほうでちょっと調査しているです。","id":"exchange-014"}]},{"id":"topic-03","title":"東品川一丁目付近下水道再構築工事請負契約","agenda":"東品川一丁目付近下水道再構築工事請負契約","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"やはりばらばらにやっているのかどうかということをお伺いしたいのと、同じところを何回も掘って埋めて、掘って埋めてやっていると。こういうような連携をして掘り返す回数を減らすということは、今、当たり前のように進んでいるんか尋ねました。","respondent":"平澤経理課長","answer":"工期につきましては１カ月ほど削減ができると聞いてあります。今回をモデルケースにしまして、メリットが多いことから、今後こういった工法をより進めていくと所管のほうから聞いてあります。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"大切な合理化の流れだと思いますので、多分いろいろな工事の中にもやはりダブっているというのがあるかもしれませんので、積極的にそういうコスト削減と納期短縮も含めて、これからも取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"避難所は１階の水洗トイレが１つ使えるようにということで、その一つとして、今回の下水道耐震化ということになっているということなんでしょうか。水さえあれば水洗トイレが使えるということで考えていいのか、その点、ちょっと説明を求めました。","respondent":"平澤経理課長","answer":"きちんとした形で耐震化を進めるということですが、各ご家庭になりますと、各ご家庭からマンホールまで入ってくる部分の個別の部分の導管があります。そこまではちょっと確認してございませんので、ちょっとそこの部分の完全な耐震化ということは、まだ未確認です。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そこら辺のところをどうこれから計画的に下水道管の耐震化を進めていくのかというのは、ここじゃないから、建設委員会だから難しいですね。結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問","question":"一般質問で道路というのはもちろんみんなが使うところなので、そういったところの調整というのはしているのかどうか、説明を求めました。","respondent":"平澤経理課長","answer":"その後、工事の１週間前には個別に、いついつから始めて、こういう工事になるというご案内をいたします。個別の管といいますか、各世帯から下水まで伸びている部分につきましても、個別にご相談をしていただいて、対応をしていると聞いてあります。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"実際に一般家庭がどういう動きになるかなんていうのは、ただ工事をやりますからというところぐらいで、そのヒアリングは終わっているんですか。せっかく区費でやっているわけですから、また掘り返したらつぎはぎだらけになってくるわけですから、質問しているんですけれども。","respondent":"平澤経理課長","answer":"各ご家庭の建替え計画までとなりますと、なかなか難しいかなということなんです。必ず工事の１週間前に、全て住民の方にお会いしてご説明をしていますので、そこまではなかなか難しいのではないかなと考えています。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっとご説明があったのかわからないんですが、この東品川一丁目の下水道再構築工事、この場所が決まりましたね。なぜここなのかという理由が、順番なんですよといえばそれまでなんだけれども、そこら辺のところを教えていただきたい。","respondent":"平澤経理課長","answer":"８月に八潮地域、それから南大井、この辺のところの改修工事ということで説明をさせていただいたところです。耐震化等も含めてきちんとした工事をやっていくということが必要だということではありますが、少しずつ順番にやっていくというのが現状です。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"意見","question":"どうしてこんなことを聞いたかというと、ここの地域というのは海抜標示板が出て、非常に低い地域で、今、売り物が非常に多い地域です。海抜標示板ですごく海抜が低かったからここをやったんだなと思っただけなんですけれども、そうでないのであれば、それで結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/904361?Template=document&Id=1956#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":18571,"voices":63}},{"id":"h25-20130806-14","meetingId":"h25-cm08","date":"2013年8月6日","dateIso":"2013-08-06","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時５６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"この件、質問の前半はその根拠であって、あるいはそれを下回る条件の工事あるいは製造の請負については総務委員会で報告することが内規としてあると。そちらをもう１回、確認したいと求めました。","respondent":"平澤経理課長","answer":"実を申しますと平成５年４月に条例改正をしてございまして、従前のものが工事請負につきまして予定価格９,０００万円以上となってございました。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"概略はわかりました。そうすると、品川区では実績から考えて、この2)に入ってくるようなものはまずないと考えてよろしいか尋ねました。","respondent":"平澤経理課長","answer":"これは建物がないものでございまして、取得額が５１億円です。区の基準で１件４,０００万円ということで、現在のところ、この基準の中で遵守させていただければと考えているところです。","id":"exchange-002"}]},{"id":"topic-02","title":"特定事件調査」を行います。 はじめに、(1)「公有地に関すること","agenda":"特定事件調査」を行います。 はじめに、(1)「公有地に関すること","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この先、どのくらいまでのスパンで今の状況が推移していくのかというところを、改めて見解を伺っておきたいと思います。それと、これはどういうふうに読んだらいいのかなというのがわからなかったので、ここを教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"今後、保育事業での展開を一定程度方針を出していますので、国等のやり取りも保育の部隊が深く関わっているということに。こちらも今申しましたように保育のほうが事業主体と考えていますので、所管の部隊がそれをいろいろな面で検討していくことになろうかと思います。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、やっぱり税金を使って仕事をしていただくわけですから、税金の使い方をしっかり見守っていくというスタンスでのぞむべきだと思うんです。それが１つと、やっぱり区の直接的な運営が私は望ましいのではないかなと思いますので、そういうことも含めて見解を伺っておきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"さまざまな面を検討しながら施策を打ってきているといったところでございまして、株式会社も含めながら幅広い主体ということで考えているところです。今後、なるべく極端に高い金額になるといったことのないように、交渉に努めていきたいと思ってあります。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"指導も含めてしていくというスタンスがとりわけ求められると思いますので、そういう仕組みも含めてきちんとつくるべきだと思っています。要請だけではなくて見解的なところも伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"当然不適当なことがないようにという、事業者をきちんと調べながら、調査しながら選んでいくといったところは基本的なところだと考えています。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"最後にごめんなさい。私が言ったのはその後の対応のことを言ったわけですが、きちんとした財務状況をチェックする、これ以上今回は答弁を求めませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"今回、今回の加速化プランの中に含まれる可能性があるようなタイミングというのでしょうか、そういうのがやはり出てくる可能性があるのかどうか。今後出てくる国有地の使い道というのでしょうか、また、区の見解を教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"例えばこういう福祉目的の建物は基本的には建てられないというような、条例上、そういう縛りがあるとは聞いてあります。大まかですけれども、今想定できる範囲はそういったところだと考えています。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前回の委員会の中で質問が出たというか、さっき行財政改革担当課長の説明の中で７月末ということで、やむを得ないなということは了解いたしました。ですから、区として地域にどう情報提供していくのかなというのが、その辺はどう考えているのか説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"今後事業を展開していく中で十分そこは注意するようにということで、事業者になる者に対しても話をしていきながら進めていきたいと思ってあります。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"ここに建てる施設はやはり３０年程度で取り壊しても惜しくないようなといいますか、簡易な建物となっていくのかということを確認させてください。この３点を説明するよう求めました。","respondent":"柏原行財政改革担当課長","answer":"基本的に国は、それの変更が可能なのかという話はしたのですが、保育目的で使ってくださいという返事を聞いてあります。それから、これは保育の部隊が今検討していますが、８０名から９０名くらいの規模になるのではないかというのは保育のほうで検討していますが。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"その中で１点、１０年と続いてしまうという状況は、区でやるほうがリスク回避ができないだろうかとも感じているんです。今後の２０年、３０年のスパンでいけば、何か考えていらっしゃることがあれば説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"３０年にするかと、３０年というのが果たして妥当な期間なのか、かと言って２０年ではどうなのか。そういった保育の需要の動向だとか、明確な答えを今出せないのは申しわけないんですけれども、そういったところで今回は判断したところです。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"１点、その状態であれば区であれ都であれ、あの広大な土地は今まではほぼ死んだような状態になっているわけですよね。以前、今後あの土地が売却に出るであろうことを前提に、もう一度考えるということは区ではなさっているんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"その際にも非常に厳しいという返事をもらっていまして、直接的にそこに交渉しているという動きは区としてはとっていませんけれども、動きとしてそこを交渉しながら突破していくというのはかなり難しいだろうとは思ってあります。","id":"exchange-011"},{"speaker":"あべ委員","kind":"意見","question":"あそこはかなり広い土地ですし、有効に使えればいろいろな可能性があるところであろうかと考えています。前回、交渉が難しかったのが価格面なのか、その他の条件なのかは存じ上げませんけれども、何らかの情報を得ておくことは大切ではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"品川区の土地開発公社の場合は２者、２人というか複数でということなんですが、区も用意するということなんですか。国のほうの、多分今ざっくり１,０００万円という金額で３０年という、ないよということであればないよということで教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"参考となる金額が全くないことには検討できませんので、そういったことで不動産鑑定をとりまして、うちの想定の中で金額を捉えていたところです。","id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"今後のスケジュールで平成２６年度、可能であればよりはっきりした形で、定期借地契約というほうがよりベターなのかなと。これは非常にいいことなので、その辺についての区のお考え、２点説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"定期借地権ということの契約になりますので、狭義で言いますと、この言い方ではなくて定期借地権での形となっています。公有地関係の契約関係ですけれども、きちんとした形で、契約関係がわかるように手続をしていくという形で今後も進めていきたいと思ってあります。","id":"exchange-014"},{"speaker":"原委員","kind":"質問・要望","question":"そうしましたならば、その辺のところを結構注意深く、今後。今度は条件的な問題とかもあろうかと思いますので、いい関係でうまく運んでいっていただきたいんですけれども、その辺のことがありましたら。","respondent":"柏原行財政改革担当課長","answer":"委員おっしゃるとおりだと思います。検討を重ねたりとか、綿密にやっていきたいと思ってありますので、そういったいい形で進められるように今後も進めていきたいと思ってあります。","id":"exchange-015"},{"speaker":"井上副委員長","kind":"確認","question":"前回からの説明で、待機児対策として保育園の方向性というのは評価をしますが、ここをそういった保育園ということでされたポイント。どういったところでここを保育施設へということにされたのかということの確認と、あともう１つ、その辺の見通しはどのように捉えているんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"定期借地であるとか、今までにないメリットのある考え方が出てきたということ、それからもちろん保育の需要の関係です。ただ、こちらについてはまだ人が住んでおりますので、そういったところが判断のポイントになってくるのではないかと思ってあります。","id":"exchange-016"},{"speaker":"井上副委員長","kind":"質問","question":"今後のことで上大崎のほうはまだいつ出てくるかということもわからない状況で、やっぱり財政的なポイントというのは確かにすごく大きいと思います。今回、ここの跡地施設のその場所で考えたとすれば、財政的にどういった基準を持っているんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"幾らというわけではないんですけれども、財政的なところではかなり区の負担がない中で事業展開が図れるかといったところがあります。それから行政需要、こういったところがそれぞれ違って複雑に絡んでいますので、それぞれの特性を見ながらの判断になってこようかと思います。","id":"exchange-017"},{"speaker":"井上副委員長","kind":"質問","question":"大井第一小学校の隣にある待機寮の下のそういう建物とか、何かあったときに福祉施設でなければ利用ができるというようなことも検討する余地があるのか、そういったところのお考えはどの程度お持ちなんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"例えば待機児童対策にしても、基本的には福祉目的というところがありますので、こういった定期借地のスキームが使いづらいことになってきます。","id":"exchange-018"},{"speaker":"井上副委員長","kind":"質問","question":"事業者の責任みたいな答弁だと思うんですけれども、あそこに用意をしようとするのは品川区なので、そのレベルではないなと思っています。区として責任を持って、近隣と警察も含めて検討するというのが対策としては必要だと思うんですが、その辺はいかがか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"区が借りるという物件ですので、区に全く責任がないということではございませんので、そういったところは十分注意しながらやっていきたいと思ってあります。","id":"exchange-019"}]},{"id":"topic-03","title":"特定事件調査の(2)「契約のあり方に関すること」","agenda":"特定事件調査の(2)「契約のあり方に関すること」","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"本格的な質問の前に、委員長に若干確認させていただきたい。今回と次回のくくりについて、もう１回ご説明いただいてよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"２つ目の施行能力審査型総合評価方式（試行中）とあるんですけれども、これはご説明を伺うと、平成２１年度から行われているわけですよね。４年間以上試行という形でされているわけですけれども、今なぜまだ試行と呼ばれているのか、この試行の意味を説明するよう求めました。","respondent":"平澤経理課長","answer":"４年というのが長いかどうかということになりますと、各区の状況を見ますと、本格実施をしているのがこの４月で４区です。","id":"exchange-021"},{"speaker":"あべ委員","kind":"確認","question":"別に４年が長いから短いから叱るということでは全然なくて、なぜ試行という段階なのかというところをお伺いしたので、確認をさせてください。それともう１つ、今の施行能力審査型総合評価に変化したというか変わった、そういう名前になったという理解でよろしいか尋ねました。","respondent":"平澤経理課長","answer":"工事の成績と配置予定技術者の資格、それから配置予定技術者の実績の部分だけです。例えば技術能力評価型という複雑な工事を実施する際の評価の仕方、技術的なものを提案してそれを評価する、そういうのもあります。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"労務管理について一定の何かしらの基準を入れられないかということ、あるいは地域貢献といったらいいんでしょうか、そういったことが入れられないか。それは今回の総合評価方式、その他の契約方法の基準というところで何か検討の余地があるかどうかということを改めてお伺いしたいと思います。","respondent":"平澤経理課長","answer":"２つの側面です。総合評価に限ってというんですか、これまでもそういった法令遵守についてはきちんとした形でもって事業者にお願いしているという流れです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"まさに法令遵守ですから、例えば２３区のまさに半分くらいは契約の前段階として労務監査をステップとして入れていらっしゃるようなんです。明確に違法ではなくて、そういった意味での視点は契約のどこかの段階で入れる方向ではあるかどうか、どういう考えか説明を求めました。","respondent":"平澤経理課長","answer":"例えば評判が悪いとか、そういったことで入札に参加できないというのは非常に難しい、おそらく不可能だと思います。ただ、現在のところ、今の２３区の共同運営の入札に参加資格がある等の部分で考えていくのが基本だということは、今はそう考えてあります。","id":"exchange-024"},{"speaker":"あべ委員","kind":"意見","question":"やっぱり契約というのは、単に契約の法令に触れないということだけではなくて、積極的に価値を生んでいくものという考え方もできると思います。それについて次回も時間があると思いますので、本日はここまでにしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"地域貢献度だとか、そこの点以外に、品川区としてはそういう評価は取り入れてはいないかなと。その点についての見解を、今、私が申し上げたような角度での見解がどういうことなのかということを教えてほしいと求めました。","respondent":"平澤経理課長","answer":"その考え方をもとにいたしまして、まず品川区では委託でこういうような考え方ができないかと考えたわけです。環境に配慮した、そういうようなことを標準的に入れるという考え方を取り入れるかどうかというのは、今後検討しなければならない課題だと思います。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"最後に１点だけ、５ページの上から２つ目の表の３番の学校給食の業務委託で、こういう部分での業務委託はいつごろから始まったのか。それがどういう経過で業務委託をするようになったのか、外れてしまうので恐縮なんですけれども、教えていただけたらと思います。","respondent":"平澤経理課長","answer":"経緯までいきますと私のほうで承知していない部分です。申しわけございません。","id":"exchange-027"},{"speaker":"南委員","kind":"確認","question":"文教委員会でも尋ねてみるので、それ以上はいいんですけれども、最後に確認、これは平成２５年４月ということなんですが、過去にはこういう業務委託は、数年のスパンでいいんですけれども、あったのかなかったのかだけ知りたいんですけれども。","respondent":"平澤経理課長","answer":"すいません、ちょっとお時間を。","id":"exchange-028"},{"speaker":"渡部委員","kind":"質問・要望","question":"本当に基本的なところをもう１回確認させていただきたいんですけれども、だけど先ほど伺った中で工事か工事ではないか、実はそこに入札する業者。外部の方とかしかるべき人が見比べてやらないと、その辺と、大きく教えてほしいのですけれども。","respondent":"平澤経理課長","answer":"これはこれに基づいて決めるわけですので、それは申しわけございませんが開示できないことになってあります。ですので、そこの部分も含めて、今現在、見直しをしています。","id":"exchange-029"},{"speaker":"渡部委員","kind":"意見","question":"工事の成績評定に関しては、持っている資料だけだと本当に何が基準かというのはわかりづらい。ただ、今後、ご検討をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もう１回そこの確認をさせてもらいたいのと、それは区の中の資料になってくるけれども、例えばこの工事が終わりましたと。どう判断するのか、そこら辺の考え方を説明するよう求めました。","respondent":"平澤経理課長","answer":"先ほど渡部委員にご説明いたしましたとおり、そこの部分が抜けているということで、現在、その方向で検討している最中です。したがいまして、そういったところもあって、工事の総合評価方式は試行段階にあるです。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もっとうまく、わかるような形を出してもらいたいなというのが要望です。そこら辺はどう判断したらいいのかなという考え方を教えてもらいたい。","respondent":"平澤経理課長","answer":"例えば業務の日報とか、または報告書、そういうのに基いてやっているです。例えば５番目のところでいきますと、申し込みの事業者が１０者ございまして、最もすぐれたものをお願いしているというのは確認しています。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"こういう総合評価で出している一般競争入札になると、金額を安く受けて、安かろう悪かろうという工事も現実に聞いています。何しろ区としていい形を、検査したものができ上がってくるような契約に進めていってもらいたいということは大きな要望事項だということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、やはりそもそもこの法律が定められて、これが今試行していると。それについて区の見解を、ほかの委員の方からもご意見がありましたけれども、ここについてのご答弁をもう一度求めたいと思います。","respondent":"平澤経理課長","answer":"例えば東京都みたいに広域的な自治体では違った考え方でやっていらっしゃるという部分もあります。今後、導入して５年たったという状況もありますので、その辺の部分についていろいろな考え方を見直していきたいと考えているところです。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは、この試行においても土木の４つの、それ以上もやっていると思うんですけれども、これについてもこの意見の聴取は行われたんでしょうか。２名以上となっているんですけれども、現在、何名の方がいらっしゃるんか尋ねました。","respondent":"平澤経理課長","answer":"この案件で変更があったときにお願いしていますので、常時いらっしゃるというわけではありません。必ず意見を聞かなければいけないという段取りになってございまして、地方自治法もそのような形で変更になっているところです。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"３つの段階がたしかあったと思うんですけれども、今までこれはその落札者を決めるときに新たな判断はあったのでしょうか、なかったのか尋ねました。","respondent":"平澤経理課長","answer":"次の、これは今も生きているんですけれども、決定基準を定めようとする、変更するときも同じです、これは必ず聞かなければいけない。ですので、この基準でやっている間は、このまま落札者を決定しようとするときは必要ないとなっているです。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"確認","question":"ちょっと戻りまして、価格点のところで、やはりダンピング防止という中で最低制限価格というのがやはりかかわってくるということがあると思います。念のため確認したいんですけれども、今年６月から最低制限価格制度が復活しましたけれども、組み合わせて行うということでよろしいか尋ねました。","respondent":"平澤経理課長","answer":"この６月から始めたものでございまして、その基準を失格基準として横引きしていくかどうかをこれから考えていくということ。本格実施に向けてはそういう課題があると認識しています。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"失格基準というお話でした。そういったほかの、そこら辺の見解についてこれから検討するというお話でしたけれども、そこら辺の考え方について伺いたいと思います。","respondent":"平澤経理課長","answer":"最低制限価格のほうでお答えしますが、この６月１日から始めたところでございまして、まだ実を申しますとそれほどの実績はないというのが実状です。それについては、一、二年間程度は少なくとも運用させていただいた上で、判断していきたいなと今は考えております。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"今、最低制限価格については伺ったんですけれども、失格基準についてはまたこれもこれから考える。これからこれは議論があるということでよろしいか尋ねました。","respondent":"平澤経理課長","answer":"失格基準を含めた総合評価の本格導入というんですか、これは全体にわたって考えなければいけないことだと思うんです。そういったところも含めた上で、研究・検討していかなければいけない課題だということは認識しています。","id":"exchange-039"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、そこに関してもまず質問というか、区民としてありがとうありますというエールを送らせてもらいたいと思います。ですから、頑張っていただきたいというところがあるんですが、一般的にその辺のところをまず１点お聞かせ願えればと思います。","respondent":"平澤経理課長","answer":"例えばですが、総合評価の部分でいきますと、平均的な申込者が大体５者ぐらいになってくると思うんです。やはり４０分とかそのぐらいの時間は十分にとった上で、事業者からの提案ならびに質疑をするというのが通常の例ではないかなと私は理解しています。","id":"exchange-040"},{"speaker":"原委員","kind":"意見","question":"やはり携帯の問題で、子どもたちが持つ携帯のところの問題が発生したり、それから給食の不手際的なことが発生したりしている。こういったことというのは、もう一歩踏み込んで、そういった事態がないような形で持っていけるかどうかというご意見をほしいと求めました。","respondent":"平澤経理課長","answer":"こちらは先ほどちょっとご説明させていただきましたが、経理課で保存しまして、主管課には行きません。そういったところからも総合評価に限ってではありますが、透明性をなるべく担保しているというのが現状です。","id":"exchange-041"},{"speaker":"原委員","kind":"質問・要望","question":"要はいろいろな形で２３区でいっぱい、総務もお手伝いをいただいて、やはりいつもいつもアンテナを張っておいていただきたいという思いがしています。今までと同様か、それ以上にも注意を払ってお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"須藤委員","kind":"意見","question":"今後、こういうものも総合評価に入れてほしいというような話をしている中に、そういったことをどうやって見てくれるのだと。そういうものについてお考えがあれば説明を求めました。","respondent":"平澤経理課長","answer":"そういったところもあわせて区として評価し、考えていかなければならない課題だと認識しています。現在の予定価格のつくり上、申しわけございませんが、できない形をとってあります。","id":"exchange-043"},{"speaker":"須藤委員","kind":"質問","question":"今お話があったように、個別の事情で事業が集中してしまったというのも１つあるんだろうということなんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"井上副委員長","kind":"質問","question":"指名型についてお伺いしたいんですけれども、品川区簡易型総合評価の場合は３,０００万円という仕切りであるということだったんですが、これはどういう基準なのかということを説明するよう求めました。","respondent":"平澤経理課長","answer":"例えば先ほど申し上げたとおり、大体の基準で申しますと、１回で５,０００万円を超える分については８者以上は標準的な基準となっています。１件ごとにその内容を見て、基準というような考え方をとっていないというのが、そういうことです。","id":"exchange-045"},{"speaker":"井上副委員長","kind":"質問","question":"２ページの表でいくと、主管課から推薦をして経理課がそれを決定するというような以前事業でそういうふうに伺っていたんですが、ここのやり取りの矢印はどういう仕組みになっているんか尋ねました。","respondent":"平澤経理課長","answer":"例えば１０者ぐらい経理課でもってプロポーザルの指名業者にはこういった業者がありますよという名簿みたいなものを主管課のほうにお出しします。指名業者を例えば２者にしてしまうとか、３者にしてしまうとか、相談の中でやっていくです。","id":"exchange-046"},{"speaker":"井上副委員長","kind":"質問","question":"では、名簿というか、推薦があって、その中から何者か主管課のほうで選んで、その先へ進んでいくということで、決定は主管課がされているということでいいか尋ねました。","respondent":"平澤経理課長","answer":"失礼しました。簡易型プロポーザルにつきましては、委員ご指摘のとおりです。","id":"exchange-047"},{"speaker":"南委員","kind":"質問","question":"仕事の中身そのものがちょっとわからないのが１つあるんですけれども、その７番のところだと、５番のほうはどういうことなのかなと。だから、そういうことを知りたいなと思っているんですけれども、そのあたりの資料は提供していただけないでしょうかということなんです。","respondent":"平澤経理課長","answer":"ただ、５番目のところにつきましては、これはデータ入力等の業務をお願いしているというのは聞いてあります。窓口で審査書を受けとってデータ入力をしていくというのは聞いております。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"意見をいただいたり、教えていただいたりという作業の中で、なかなか目が届かないというか気がつかないところは多々あると思うんです。当該のテーマに応じた状況が、資料として、ぜひ正副のほうで検討して求めていただけるように取りはからっていただきたいと思っているんですけれども。","respondent":"山元委員長","answer":"今の件に関しましては、正副で検討させていただきたいと思います。","id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"一委員の要望ですから、そうやって聞いていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/631596?Template=document&Id=5950#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":51552,"voices":123}},{"id":"h25-20130807-17","meetingId":"h25-cm08","date":"2013年8月7日","dateIso":"2013-08-07","committee":"震災対策特別委員会","time":"午後 １時００分～午後 ３時２４分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この目的とは、区民の自助・共助の防災意識の向上ということなのかどうか、目的を伺いたいと思います。どういう意識、認識を区民自身に持っていただきたいということがねらいなのか、そこもあわせて丁寧にご説明ほしいと求めました。","respondent":"鈴木防災課長","answer":"先ほども説明いたしましたように、もしくは地域の防災力の向上を図るというのが目的になっておりまして、それは委員のおっしゃるとおりです。災害への対応も変わってくる、地域全体の人たちにお持ちいただくというのが、この共助の意識の向上と考えているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"確認","question":"伺いたいのは、３・１１の教訓がなぜ自助・共助の再認識なのかと。どんな準備が必要なのか、そのための訓練や防災計画の視点を位置づけることが必要だと私は思いますが、区の見解を伺いたいと思います。","respondent":"鈴木防災課長","answer":"もしくは応急対応時の行動、全てに共通する考え方、自助・共助・公助の考え方です。区の考え方としては、災害直後の対応、震災等の災害に立ち向かえるというのが区の考え方としております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"災害関連死のほうが多い自治体もあると伺いました。改めてなぜ自助・共助の再認識なのか、役割分担の教訓なのか、そこを伺いたいと思います、それが質問。","respondent":"鈴木防災課長","answer":"区もその認識の上にこのようにしっかりと計画を立てて、区民の皆様にも役割分担なり、こういう対策を講じていただきたいというご説明をして。実際の対応もかなり重要なもので、防災対策の中心を担うと考えているのが、区の見解です。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、実際の被害をなくすための事前の対策の徹底、ここにあるのではないかと私は思います。そのこと自体が間違っていると私は思いますけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"もし私の言い方がうまくなくて伝わらなかったのなら、もう一度言いますが、自助・共助・公助は考え方です。具体的な個々の対策、取り組みということで整理しているのが、区の考え方です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"訓練を通じて、どういう意識を持っていただきたいのか、この点を改めて伺いたいと思います。住民から訓練を通じて感じたことを、区の計画につなげていくことが必要だと私は思いますけれども、いかがか尋ねました。","respondent":"松代防災まちづくり事業部長、鈴木防災課長","answer":"私どもが考えているところは、防災対策は一つの対策で完全に対応できるものではなく、総合的な対策で対応するものであると考えています。こういった事態に地域の皆様とどう対応していけばいいのかというのを… これについては、町会だけではなくて、地域の方だけでは対応できない方の支援や救出・救助も行うべきだというご意見でございました。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、冒頭から目的は一体何なのですかと伺っているのです。改めてそのことを伺いたいと思います。","respondent":"片田都市環境事業部長","answer":"今、自助・共助・公助の関係のお話がありましたので、私どもの考え方をちょっとご説明します。住民の方が認識し合って、それぞれの力を高めていこう、これが自助・共助・公助の考え方です。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"正しい知識による避難とありますけれども、どんな知識とどのような行動を指しているのか、区の考えを伺いたいと思います。なので、避難について、防災計画上どういうふうになっているのか、そこをあわせて伺いたいと思います。","respondent":"鈴木防災課長","answer":"何度もお答えしたように、これは考え方ですので、何かの公式の証明から導き出されるものではございません。もしくは減災を少しでも実現して、区民の方の命や財産を守るというのが、この防災計画の考え方になっております。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"どういう行動なのかということを先ほど伺ったので、もう一度伺いたいと思うのですけれども、避難だ」と。それについても最後に伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"議事進行について、１人で１時間しゃべっているのですから、委員長、しっかり采配してください。こんな委員会、冗談ではない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"２万件の火災が消防自動車を待つだけでは、２万件の火災を消防車が来るのと同時に、頑張ってほしいと求めました。この２万件の火災を、２万件に対する消火の斑がこれだけ必要だとか、どのように考えられているのか説明を求めました。","respondent":"鈴木防災課長","answer":"何もしないわけにはいきませんので、現在の考え方をご説明いたしますと、約２万件という割合で火災が多発する。自助・共助の取り組みがまずは初期消火、火を消し止める効果も一番大きくて、早く対応できる部分を行います。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"あのスプレーの効力とこの消火器の効力の検証みたいなものはどうなのでしょうか。もしスプレーでも効力があるのであれば、もうスプレーの補給でいいと思うので、その辺の現状を教えていただきたいのですが。","respondent":"鈴木防災課長","answer":"区でも同じような認識をしておりますので、今ちょうど検討しておりまして、またご報告させていただきたいと考えているところです。一般の区民の方で初期消火が対応できるのは、家庭で対応できる、能力的には家庭用消火器のほうが少し上回ります。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"何点か質問させていただきたいと思うのですけれども、多くの方に参加していただくためには、どのような工夫をなさるのかということを１つ。区切ってやるのか、それとも全域でやるのか、また区民へどのような周知をして実施するのかをお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"対応できる方や対応の仕方も変わってくるというご質問については、理想としては、曜日や時間帯や天候がそれぞれ違うときに訓練を実施して。今後の地域での取り組み状況や、そこでわかった課題も踏まえて、今後検討していきたいと考えております。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど意識と知識が必要であるというお話をお聞きしまして、やってみたほうがいいということは、皆様に周知してほしいと求めました。何度も繰り返すことによってまた周知して、参加者も増えていくのかと思いますけれども、その辺をもう一度お願いします。","respondent":"鈴木防災課長","answer":"そのときの個別の対応は、発災型防災訓練で十分対応できるものが同時にあちこちで起こるということですので、現在のところの見込みです。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"発災型防災訓練ということで質問をします。今後全地区に広げていくというお考えがあるのかということと、主にどういった感想、意見が出ているのかということを説明するよう求めました。","respondent":"鈴木防災課長","answer":"大井第二地区におきましては、３町会実施しております。平日の昼間が多いということがありますので、一気に開催の地区数や回数を伸ばすというのは、なかなか難しいとは考えております。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"大変だということがわかったことで、自分たちはどうするかということを考えるわけですから、ぜひともこの訓練を広めていってほしいと求めました。地区ごとにレベルというか、訓練の度合いのばらつきをすごく感じるので、この辺の区としての考え方はどうなのか尋ねました。","respondent":"鈴木防災課長、松代防災まちづくり事業部長","answer":"本部長、つまり、町会長からよくお聞きするお話だと、どうしても役員がもう固定されていて、町会として取り組むことはほかにもたくさんある。区からの情報提供や啓発をする内容と、その伝え方をもう少し工夫して… 今回私どもは、少し違う角度で認識を持っていただいて、さらに地域の防災力を高めていただく手段にしていただければと思っているところです。","id":"exchange-015"},{"speaker":"沢田委員","kind":"意見","question":"その３者の連携というのはすごく大切なことだと思いますので、そういったこともぜひとも進めていきながら、地域の防災力向上に努めていってもらいたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問・要望","question":"これは確認です。どういった形でやりましょう、やりますという町会のやりとりというのでしょうか、そこら辺をちょっと教えていただきたいのと。","respondent":"鈴木防災課長","answer":"昨年度実施したところも、その事務局的機能を担う地域センターがその間に入って実施して、支援。この内容と方法をうまく組み合わせて、委員がご指摘のように、できるだけ区内に拡大していくという方向に努めていきたいと考えております。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問・要望","question":"その現状をひとつ教えていただきたいのと、海沿い地域の方は、津波から来る発災というのもあるかと思います。消防署の方はそこまでまだというのであれば、区はここら辺の発災型はどういうふうに考えていらっしゃるのか。","respondent":"鈴木防災課長","answer":"考え方としては、昨年度実施のときには、消防署で持っている資機材を提供いただいております。津波に関しても、何か発災型訓練のスタイルの中で取り入れられるのかどうかというのは、消防とも相談をして検討してみたいと思います。","id":"exchange-018"},{"speaker":"こんの委員","kind":"確認","question":"実際どうするのかというところは、資機材に関しても、一つ考えていかれるものではないのかと思います。あれは経路を確認するだけでしたので、ぜひ発災型というところも今後考えていかれたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"つる委員","kind":"意見","question":"昼間人口の方に担い手になっていただくという、まさに強力な担い手の集団だと思いますので、ぜひ積極的な声かけを私からもお願いしたいと思います。今日配っていただいた中の３ページの訓練項目のところにありますが、まず設定をする主体はだれがやるのかということですとの意見を述べました。","respondent":"鈴木防災課長","answer":"シナリオとか、訓練状況を設定する役割をどなたが担うかというご質問ですが、基本的には実施主体の防災区民組織の方で考えていただくのが本来です。習熟する回数の実施とか実績がございませんので、実施主体の方の意見を入れて、少しアレンジをすると聞いております。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"普段日常的にこれまでの取り組みの中でやってきたことを確認するという訓練のやり方も、確認の場で非常に大事だと思うのですが、例えば。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"そういったことを一つ乗り越えた中で、その辺のこととあわせて、もともと消防署がこういうことを消防署としてやっていた。もともとのまちかど防災訓練というのをやろうとしていたねらい、この辺はどういうふうになっているのか、ちょっとお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"その中で訓練とか、知識の普及啓発をやっている一つのメニューといいますか、項目に入っていたということだそうです。具体的にやろうという団体や町会が幾つか、早く取り組むところはもう昨年、おととしあたりから取り組みを始めたというのが現状と聞いております。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"ありがとうございました。ということは、発災型防災訓練をやるに当たっては、予算的なものが実際どの程度かかるのかというのをお伺いしたいと思うのですけれども。","respondent":"鈴木防災課長","answer":"申しわけありません、１本何万円かすると、多分高いものなのだろうと思います。今の消防との連携で訓練をやる場合には、特別な資機材を用意しないという前提から考えると、現在の予想です。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"そういうことでいいますと、１回やった町会がまた今年ももう１回やるという、複数やっていきたいというご希望もおそらく出てくるかと思います。消防の人が、消防署の方の負担なく実施するということもでき得るのではないかという思いもあるのですけれども、その辺はいかがお考えか尋ねました。","respondent":"鈴木防災課長","answer":"確かに消防の支援や人的な支援部隊が軽減、消火栓から、火災が起きたと仮定した場所の公園までが１００メートル以上離れていたのです。例えば、そうすると、多分実際の訓練の行動をする方と同じぐらいの安全確保とかの支援部隊が必要になるというのがあるかと思いますので。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"最後に意見だけ言わせていただきたい。これは意見ですので、答弁は結構ですけれども、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"木村委員","kind":"質問・要望","question":"その中で一番大事なことというのは、訓練の振り返りが大変大事なことだと思っています。それとも当日皆様が集まって、ミーティング形式でやるのか、このことを教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"ディスカッションをし、そこで課題の振り返りとか、気づきの共有をされたと聞いております。それを継続して訓練に反映させて、さらに次の課題をと見ていけば、地域の方でも効果を出すことが十分可能だと考えております。","id":"exchange-026"},{"speaker":"木村委員","kind":"質問","question":"今までこういう事例というのは、そんなにはなかったのですよね。よほど何か緊急めいたこととか、危機感を感じている、そういうもののあらわれだと思っていいのか尋ねました。","respondent":"鈴木防災課長","answer":"区も同様ですが、以前にも増して、具体的な対策についての行動が増えてきたというのはあると思います。地域の方、町会の方の防災に対する知識や意識も高まってきたというのがうまく合致したところで、この訓練の実施が増えてきたと区では認識しています。","id":"exchange-027"},{"speaker":"木村委員","kind":"意見","question":"この訓練は、先ほどからも言っていると思うのですけれども、区内一斉の防災訓練が行われました。１２月にまた行われるということなのですけれども、こういうものが年に２度、３度と続く予定というか、見通しは何か立っていますかとの意見を述べました。","respondent":"鈴木防災課長","answer":"訓練の種類を総体的に、回数や実績を増やすということで、地域全体の防災力の向上が多分望ましいかと考えております。今年２月に初めて実施して、今年１２月８日に第２回目をやるところですので、一斉訓練は１回を予定しています。","id":"exchange-028"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、今までお話を伺っている中で、どの辺まで区が入ってお話していくのかというのをちょっと。","respondent":"鈴木防災課長","answer":"まずは連携する協力支援機関と綿密に打ち合わせをして、月に何件ぐらいなら可能なのかとか、地域の皆様にはお知らせをしていきたいと考えております。","id":"exchange-029"},{"speaker":"大倉委員","kind":"提案","question":"提案ではないのですけれども、どうやって建物に挟まれた方を助けるのかといったときに、実際ないわけですね。ちょっと柄の長いほうき２本にＴシャツ何枚も入れてとかというのは、そういったことを取り組まれるのかどうか、とりあえずとの意見を述べました。","respondent":"鈴木防災課長","answer":"実施をしている中で、物干し竿２本と毛布があれば、こういうものでできますという関連情報もお伝えしてきているところです。特にこういう訓練を実施するときには、そういう情報提供とかもいろいろ共有して、地域の方にもお知らせしたいと考えています。","id":"exchange-030"},{"speaker":"こんの委員","kind":"質問","question":"訓練に限らず、ただ、訓練のときにそれがわかるというこの現状はどうなのでしょうかというのが１点です。そこら辺の仕組みはあるか思いますけれども、この消火栓については、どうか尋ねました。","respondent":"鈴木防災課長","answer":"２つを合わせますと、今年度、区で模擬の消火栓を特別注文でつくったのが３台あります。各地区から問い合わせがあると、貸出しをして、使っていただいているところです。","id":"exchange-031"},{"speaker":"こんの委員","kind":"意見","question":"訓練のときにわかったところが、きちんと点検をされていくことをお願いしたいというのが、話の筋でしたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"前回の想定では４２件ということですから、２万件に拡大することを止められるのだということがわかるような訓練の中身や情報提供、いかがでしょうか。どういう状況だったか伺いたいと思います。","respondent":"鈴木防災課長","answer":"先ほどもご説明しましたように、そのエリアの中で何件焼失するという計算ですので、都の被害想定では出火件数という言い方では情報は出ておりません。かつ、区民の方の命や財産も守れるので、ぜひ力を合わせて取り組みましょうというのが区の考え方です。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"想定の範囲ですけれども、今の４２件はどうしても発火が考えられる。リーダー育成のための新たな仕組みづくりもやっていくことが非常に効果的ではないかと思うのですけれども、その点についても伺いたいと思います。","respondent":"鈴木防災課長","answer":"区民大学で全６回のコース、１コースを防災用にいただきまして、実施したところです。具体的に訓練をしたりという取り組みも今進めておりまして、ご指摘のあったような、必要な対策を講じていきたいと考えております。","id":"exchange-034"},{"speaker":"松澤委員","kind":"質問・要望","question":"そんな意味では、情報の共有というか、こういう災害のときに一番大事なのは情報ですから、そこの点は本当にしっかりしてほしいと求めました。お金をかけてスタンドパイプを買ってこれが役に立つのかと思うのですが、その辺、ちょっと見解をお聞きしたいと思う。","respondent":"鈴木防災課長","answer":"昨年度はとにかく被害想定で大きく出ました火災の初期消火対応で、スタンドパイプ単体で使うとき、もしくはあれはポンプと連携しても使えるのです。","id":"exchange-035"},{"speaker":"松澤委員","kind":"意見","question":"昨年度の事情はわかった。これからどう考えますかということの意見を述べました。","respondent":"鈴木防災課長","answer":"現在どういう工夫をしたらうまくできるのか、もしくは都とか国から補助みたいな制度がないかとか、そういうのを今検討しています。現時点では、検討するというところで、お答えするにとどめさせてください。","id":"exchange-036"},{"speaker":"松澤委員","kind":"質問","question":"スタンドパイプは消火栓がないと使えないものですから、スタンドパイプとホースと全部自費で買ったという町会が、わかりますよね。そこまでする町会もあるのですから、そんなことをしたら、区長も困ると私は思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/480548?Template=document&Id=6436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":46811,"voices":82}},{"id":"h25-20130826-6","meetingId":"h25-cm08","date":"2013年8月26日","dateIso":"2013-08-26","committee":"区民委員会","time":"午後 １時００分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"スポーツ祭東京２０１３（第６８回国民体育大会・第１３回全国障害者スポーツ大会）","agenda":"スポーツ祭東京２０１３（第６８回国民体育大会・第１３回全国障害者スポーツ大会）","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"区としては、権利としてのスポーツを保障するために、何が必要だと考えているのかを伺いたいと思います。実行委員会を開いて、スポーツ祭東京２０１３を始めているわけなので、そのスポーツ施策についての理念を伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そういう中で、平成２２年に総合型地域スポーツクラブ、「スポクラ・しながわ」ができました。そのような形で、私ども、権利としてのスポーツの推進のためには、そういう基盤整備を主に手がけてやっているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"スポーツを通じて熱くなることも含めて、参加だと私は思いますけれども、そこをどう位置づけていらっしゃるのか伺いたい。やはり、しっかり位置づけて、スポーツを進めていくことが大事であると私は思いますけれども、そこはいかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"高齢者についても、ハンドボールはできませんけれども、観戦した感動だとか勇気をもらって、日常の生活の中に取り入れていきたいと考えています。そういう中で、昨年、グラウンド・ゴルフのデモンストレーションの場、１年前イベントとして行いました。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"そういう障害のある方が応援という形の視点は、具体的にどう位置づけ、具体化されているのか、また、目指しているのか、そこら辺についても伺いたい。そちらの現状も含めて、目指している方向も含めて伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"障害のある方々に、国体を通じてぜひスポーツをというご案内は、非常に難しい。今後も、あらゆる手段を通じて、障害者福祉課とも協力・連携をしながら、普及に、ケアに努めていきたいと思うところであります。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"スポーツ基本法第２条というか、国民体育大会のことはわかりました。品川区の中の部分が全然出てきていないような気がしたので、そこら辺をもう一度確認したい。","respondent":"安藤文化スポーツ振興課長","answer":"それがまずよりどころになって、その後、平成２２年３月に、文化芸術・スポーツ振興ビジョンをつくりました。失礼いたしました。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問","question":"当然、そういうつもりの質問ですけど、その中では、たしかスポーツをやるのと、スポーツを見るということも、かなり強くうたって出したはずです。全会一致で承認していただいた条例ですので、ぜひ積極的にまたその辺も意識しておいてもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"意見","question":"」と出ておりますが、開始は平成２５年１０月３日、４日の木・金曜日の平日の日中ということで、非常に限られた方になってしまうと思うのです。ですけど、こういったときに、課外授業ではないですけど、そういった部分で何かされているということがあるのかどうか、その点を説明するよう求めました。","respondent":"安藤文化スポーツ振興課長","answer":"スポーツ祭東京２０１３を品川区でやっている事実、最後ではないですけれども、本当に偶然の内容です。お邪魔して、ぜひ来てくださいということでお願い申し上げまして、もう既に何校かが応援に来ていただけるというお約束をさせていただいています。","id":"exchange-006"},{"speaker":"山元委員","kind":"意見","question":"私も本当にそう思って、３日、４日は、私たちは決算特別委員会が入っていて、見に行けないと思いました。そういう意味で、学校に何校かお話をしたというけれども、それ以外に、周知というか、何かなさっていることはありますかとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"ご指摘のとおり、丁度３日、４日の平日です。見にきていただけるということで、あらゆる方法を通じまして、周知しています。","id":"exchange-007"}]},{"id":"topic-02","title":"の品川区民芸術祭２０１３の開催","agenda":"の品川区民芸術祭２０１３の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"品川区民芸術祭２０１３の目的と事業を説明されましたけれども、聞きに行く、それは幾らなのか。それをご説明いただけますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"とりあえず、プロのオーケストラということで、こちらはコンサートで５００円という割安で開催する予定です。大変申しわけございませんが、最後のチェコ国立ブルノ・フィルハーモニー管弦楽団コンサートについては、６,０００円と５,０００円です。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"そこを１点伺いたいと思います。それこそ、そう言えるのかと非常に疑問ですけれども、あえて伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"社会人まで通じて、こういうものをやるところは、非常に少ないのではないかと考えています。そういう中で、品川区民芸術祭としての位置づけだとか、参加費については、今、ご紹介をさせていただきました。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを伺いたいと思います。自治体がやるわけですから、この機会にどうぞという、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"この低廉の価格については、先ほど言っているように、ドリームコンサートは５００円。秋川さんのもが３,５００円と、これが本当に低廉の価格と私どもは考えてあります。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"いかがですかと、何が大事なのか、そこを改めて伺いたいと思います。子育て枠と言うのでしょうか、そういう考え方というのは、全くないということなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。２カ月ずっと区民の方が、芸術祭をやっているという意識をキープできるのかどうかといったら、非常に難しいと思うのです。","respondent":"安藤文化スポーツ振興課長","answer":"そういう中では、平成２４年度から、実行委員会もそうですが、事務局でも、期間のことについては、議論をしてまいりました。ご報告させてもらいますが、前回、平成２４年度に３回目を行いましたが、これが９月９日から１２月７日まで、約３カ月やってございました。","id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"３カ月が２カ月ということは十分承知をしておりますが、その点をぜひ再検討としてほしいと求めましたので、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"ニューフィルハーモニーオーケストラ千葉を、どういう意味で、質ということで選んでいらっしゃるのか、その辺をお聞きしたいことが１点。その２点お願いします。","respondent":"安藤文化スポーツ振興課長","answer":"オーケストラのことですけれども、今回、ドリームコンサートということで、きゅりあんの大ホールで行います。そういう中で、今回は、一応、区民の方とプロですので、千葉ということで、御紹介をさせていただいて、決定いただいたところです。","id":"exchange-014"},{"speaker":"吉田委員","kind":"意見","question":"千葉の方がどうのというわけではないですけれども、できれば、品川区の方を起用していただいたらと思います。その辺をもう一度お願いいたしますとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"合唱、管弦楽、吹奏楽と新たに編曲をしました。品川区民の方たちに、「しながわ物語」の普及をさせていきたいということで、プロの方にお願いをしたです。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"「しながわ物語」と品川音頭は、ジャンルも規模も違って、内容的に難しいとは思いますけど、お考え等は分かりましたので、ぜひ、これから、決まったものがどうのということではなくて、そういう品川区の方々にトライできるような機会をつくっていただけたらということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"東海道４００年祭のリメイクということで、東海道４００年祭は、平成１２年でしたよね。平成１２年のあの日を思いつつ、質問しますが、ドリームコンサートの予算は、どのぐらいつけているのか教えていただけますか。","respondent":"安藤文化スポーツ振興課長","answer":"〔「はい」と呼ぶ者あり〕 そうしますと、編曲と……。〔「編曲は、ちょっと」と呼ぶ者あり〕 今、ちょっと見つけることが困難なので、後ほど、ご報告させてもらいます。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"技術力、市場力、品川ブランドの寄与度、事業への意欲ということですけれども、品川ブランドとは、具体的にどういうことを指していらっしゃるのか。そこを補足的にご説明ほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"販路を開拓するという、さまざまなこの３段階のニーズに合わせて、支援メニューを行ってきているです。品川区の場合、地場産業として強い分野がここだという部分ではありませんので、メードイン品川の製品をＰＲしていこうという意図・趣旨です。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川のブランド力について伺ったのですけど、パンフレットを見ても、こういう技術があるというＰＲになっているとは思うのです。周知やＰＲにも位置づけていくというふうにやっていったら、どうかと思いますけれども、２点目はいかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"なかなか１つの製品として認知されるというものではなくて、そうした点も広くメードイン品川の事業に当てまして、ＰＲをしてまいりたい。すぐれた製品・技術の認定を経て、適宜、販路開拓などの支援に結びついていければと考えています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"それまでにはたくさんの失敗があったわけですから、そこもしっかりつかんでいただいて、ＰＲに位置づけてほしいと求めました。これは要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"商品を見て、どうやってわかるのかということを、まず教えていただきたい。３点目は要望で終わりますので、２点だけお答えほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"今年度も予定しておりますけれども、昨年２月の品川区新製品・新技術クラスターフェアというところで、プレゼンテーションを行ったのです。そうした場の設定も検討させていただいて、考えてありますので、しっかり考えてまいりたいと考えています。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"済みません、基本的な質問かもしれないのですけど、特許はどうなっているのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"特許につきましては、既に今回ご説明をした製品の中でも、特許を取っている製品もあります。そうしたところについては、当然、製品開発支援の中でやらせていただいているところです。","id":"exchange-022"}]},{"id":"topic-03","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"どう中心的なことなのか、現状の考えを伺いたいことが、一つ。どういう意図と狙いを持って、この２点だけ追加して、説明していただけますか尋ねました。","respondent":"米田商業・観光課長","answer":"戦略２のほうですけれども、都の中心部において、できるだけ国際会議等を誘致していこうという考えであろうかと思います。そういった関係で、大田区と連携しながら、この水辺空間を活用した補助事業も実施してきたという経緯があります。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"伺っていて、願う品川の魅力の発掘とは、全く異なる都市型観光の位置づけだとも思いました。それが都市景観と言っていますけど、区民は、もうそんな高い建物を望んでいませんから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"意見","question":"品川にとっても、メリットはありますけど、そこら辺の活用をどう考えていくのか。とりとめないですけど、とりあえず自民党としてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"要は、何を目標にして、どうやって整備をしていくかだと思うので、その点を区としてもしっかり僕は考えていっていただきたい。それこそ水辺とか、さまざまな資源、既に品川区にある豊かな資源をどうやって生かすということが、１つ大きい課題になっていくのかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"確認","question":"今お話を伺っても、目玉やターゲットがよくわからない。再確認し、いわば、愛着を持っていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"吉田委員","kind":"意見","question":"３地区みたいなものを含めて、これから東京都を考えると、必要ではないかと思うのです。そういうことで、勉強してまいりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"私は、生まれも育ちも品川ですから、子どものときを考えたのです。誇りに何を思っているかということを改めて把握することは、品川のＰＲにも、すごくつながっていくのではないかと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"山元委員","kind":"意見","question":"戦略５の人材の育成云々とありましたけれども、また、それを観光に活用する。そういうものを使っていけたらといいのではないかということを感じていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"渡辺委員長","kind":"質問","question":"正副委員長の前に、一つ、委員の皆様にお知らせします。３時過ぎに公務の関係で、事前に委員長として伺っておりまして、御了解いただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"向副委員長","kind":"質問","question":"品川区内を見ると、商店街がいっぱいあって、安い定食屋もいっぱいあるではないですか。そういったいろいろな目的を、どこに置くかということが大事だということを、今、すごく考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"１２時ちょっと前になったら行って、みんな大事にされているということが、だんだんうれしくなってきたということを感じるのです。そんなにすごいことですかねと、いろいろな発見や新たな評価が生まれてくるのかと、皆様の意見を聞いて思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ここはどうなのかと、いろいろ教えてもらいながら、やらなければいけないのかということを具現化していく。せっかくあるのですから、最後に、１点加えたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"山元委員","kind":"意見","question":"何かそういうあるものをもっと活用して、手を入れていったら、四季折々、外からも来る人たちがいるのではないかと思うのです。正直、それを使って、何かできたらいいのにと思っておりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"意見","question":"テレビ東京で、勝島の紹介をやっていて、１位が、たしか、しながわ水族館。勝島をどう活用するかということを、どう考えているかということで、いろいろこれからの課題ではないかと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"動線をどうやって生かしていくかということも含めた考え方をしなければ、ぜひ、行政のほうにも理解していただきたいなと思います。少し変化をさせるだけでも、これは本当に外国人が一番好きなものは、歴史ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/398926?Template=document&Id=2674#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":45307,"voices":92}},{"id":"h25-20130826-7","meetingId":"h25-cm08","date":"2013年8月26日","dateIso":"2013-08-26","committee":"厚生委員会","time":"午後 １時００分～午後 ３時２６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"平成２５年陳情第１０号、希望する区民に救急キットの配布を求める陳情","agenda":"平成２５年陳情第１０号、希望する区民に救急キットの配布を求める陳情","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"救急キットの配布を求める陳情ということで、読ませていただいた中で幾つか、この救急キットに関してもう１回説明もお伺いしたいと思うんです。は仕組みは別として、２３区で救急キットというものがどの程度普及されているかというところが、わかれば教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"緊急時の対応というのは、区のほうといたしましては、町会の見守り活動を進めていくというふうに考えているところです。平成２３年度から開始して、現在５,６４２個、５９団体にやっていただいているところです。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"何かあったときの安心感を求められている方、何のときに気づいていただくことができる、早いわけですよね。私はやらないという人はやらないでしょうから、例えば、そのような取り組みを区でやることは可能か尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ただいろいろな考えやいろいろな環境の方々がいらっしゃいますので、フォーマットをちょっと検討しなければいけないのですけれども、この方のご希望を多少でもかなえることは可能ではないかと考えています。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"緊急マークではないけれども、何かあったら入っているんです、というような仕組みでもいいのかなと思います。きっといろいろな方がそれで助かるのかなと思ったので、ぜひ検討をしてほしいと求めました、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問・要望","question":"概要については、さっき渡部委員とのやり取りで伺いました。障害者の方々にお願いしてつくっていただいて、その方たちの工賃になっているんですか、そこのところの確認をしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"切り取って書けるようなものをつくってありますので、それをいつも手帳の中に携帯するようにということを、障害者団体の方にはご説明をしています。それから、つくっているのは知的障害者の就労支援Ｂ型のさつきというところで、同時に就労支援ということもやっているところです。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"民生委員の件は、お薦めをしていただいて、そういうものをやっていただくというところから広げていくということができないのかなというのが趣旨です。たしかその前にお聞きしたかなと思ったので、いい意味で障害者の就労支援にもつながるということであれば、もう１回お願いします。","respondent":"永尾高齢者福祉課長","answer":"そういうところが出てきてしまうようなこともありますので、ちょっとその辺は今後の課題ということにさせていただきたいと思います。緊急のこととか、そういう情報を常日ごろから、そういう内容についても周知をしていきたいと考えています。","id":"exchange-005"},{"speaker":"井上委員","kind":"確認","question":"２点、確認をさせてください。さつきを言っているのか、どこかほかの何らかの会社なのか、ちょっとそこがわかりませんでしたので、お願いします。","respondent":"永尾高齢者福祉課長","answer":"費用についてですけれども、さつきは町会に２５０円で売ります。それから、４２０円ということですけれども、これはさつきではなくて、製造会社が別にございまして、そちらで購入する場合の金額です。","id":"exchange-006"},{"speaker":"井上委員","kind":"提案","question":"私も救急キットを提案するにあたって、消防署のほうにお話を伺いにいったときに、ということでした。救急キットの、多分要望もあるかと思うんですとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"直近では、特に私は受けてはいないけれども、雑談の中で、といったような情報です。用意していないので、その中に入れるものを組み込んでもらって、それで徴収をするという内容のことを委託しているということです。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"１１０番とか、ただ手を挙げて誰でもということではない仕組みが間に入ってもいいし、有料でもいいと思うんです。２５０円で販売をしているのであれば、ぜひ検討していただければと思うんですが、その辺はいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"更新とか、そういう場面でも、地域や町会の見守りネットワークの仕組みというのは重視していかないといけないと思います。無料なり、町会のネットワーク以外で配布というのは、もうちょっと考えていきたいと考えています。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"ぜひ、そこはもう少し離した中でやってほしいと思います。手当、そこにこだわらない政策として取り組むことができない理由はないと思うんですが、その辺はいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"服薬のこととか、そういうことが緊急隊員にわかればいいと思いますので、そういうような方法の工夫というのを考えていきたいと思います。それを、生活弱者の方々にきちんとお知らせするような方法をとっていきたいと考えているところです。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"これが５,６４２個、５９団体まで広がっているというところでは、広がったんだなということは感じました。こういったところでも、町会・自治会のみんなの反応とか、それに対して、区はどう考えたのかというのを説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"これは非常に便利なものだし、非常に安心できるものだからぜひというような声は出てきて、そういう形での広がりを見せているところです。特に、町会の方にも高齢の方もいらっしゃいますので、そういう方の声を中心に広がっているところではないかと考えています。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ほんとうにわかりやすく、素早く対応ができるものなんだなと、出た当初も感じたんです。私は要望したんですけれども、５,６４２個出回っている中で、品川区は見ていないんですよね。","respondent":"永尾高齢者福祉課長","answer":"品川区のほか１０区という話ですけれども、３.１１の震災があったことを受けて、防災の関係で始めたという区も幾つか聞いております。町会で配ることによって、よりきめ細やかに配られているのではないかなと考えています。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やっぱり必要だという方に届くことが大事だと思うんです。先ほども出ていましたけれども、４２０円のものを買うときに、製造会社から購入というのは、電話すればすぐにという形のものなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"フリーダイヤルで、通話料無料で問い合わせ等はできますので、そういうご利用の方法はあるかと思います。","id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"じゃあ、そこを通さない人は４２０円ですよっていうことは、何だか対立をさせてしまうのではないかと思うんです。ですので、そういう方には配付して、そして使える形まで一緒にやっていくということを進めていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"それにかわるいろいろな方法が考えられますので、そういうものも含めた中で、地域にいる体の弱っていらっしゃる方の緊急時対策というのを考えていきたいと考えています。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問","question":"うちの町会は会長の英断で１００本単位で町会のほうに準備をされて、私もマンションに住んでいるものですから、私もご案内をさせていただきました。１点だけ伺いたいんですけれども、この２５０円と４２０円の差というのは、やっぱりこれはスケールメリットでこういう差が出るんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"スケールメリットと、あとは入れ込むのも障害者の仕事としてやっておりますので、そこの部分の差が出ているです。販売業者のほうは、もう全てセットした段階で、それを１セット４２０円でお売りしているというようなことです。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"どうしても欲しい方には、例えばホームページとか、何かわかるような形にしておいていただきたい。「じゃあ、やめた」という方もやっぱりいらっしゃるので、そこのところは何か工夫をしていただけたらなと思います。","respondent":"永尾高齢者福祉課長","answer":"区のほうで、どうしても欲しい人は直接その業者へというのは、なかなか、固定した業者を出すということは難しいところはありますので、個別のご相談ということになるだろうと考えています。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"という答弁があったんですけれども、見守りネットワーク事業として税金を投入しているので、なかなか難しいということだったのかということが１点。その辺については、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"販売業者のほうとやり取りをして、材料を手に入れて、製作をして販売をするという流れをとっています。橋渡しなり、そういうことをやっていき、どうしてもということになったときに考慮するというような方法をとっていきたいと考えています。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"ただ、常に更新をしていっていただかなければ全く意味がないものになってしまうわけですから、そのような形で広まっていけばいいのかなと思います。ご説明に行ったりとか、またどうですかという意味合いのものにはなっていくと思うので、いいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問・要望","question":"必要と思われる方が増えてくる中で、今ほんとうに頑張っていただいて、スピードをさらにアップしていただきたい。仕組みということをおっしゃっていますけれども、その趣旨は賛同できるということで、趣旨採択にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"井上委員","kind":"質問・要望","question":"その医療の情報をどう伝えるかというところのものであるということで、この方も医療情報を伝えるという趣旨は十分に理解されているんだと思います。そういう意味では、趣旨採択だと、本会議場では、もう不採択という評価になってしまいますので、ぜひ採択ということで進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これはこれ以上のものでもないし、これ以下のものでもないから、現状でいいと思います。もっと誰かに伝えるような別のツールを考えればいい話ですから、それはそれで救急キットを安易に転用するというのではなくて、趣旨採択に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"この陳情者も難病を抱えられているということで、いろいろな不安があるんだと思うんですね、私たちにはなかなか想像ができないような。これが欲しいという方には届くようにしていいのではないかと、私は思いますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問","question":"私どもも同じで、救急キットも大事だし、それにこだわらず、とにかくそういう情報を必要な方が見れるような仕組みという面では理解できますので、だから救急キットにこだわると、なかなか区のほうが、すぐにはということもあると思いますので、趣旨採択でどうでしょうかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"はじめに(1)の平塚橋会館跡高齢者福祉施設等の整備","agenda":"はじめに(1)の平塚橋会館跡高齢者福祉施設等の整備","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"お願いにいけば、空いていれば、普通に利用料があって借りられるんでしょうか。今までと何か違うようなところがあるんか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"今後の平塚シルバーセンターの利用者の方々のことも考えますと、大体５０から５５団体の登録団体がありますけれども、考えているところです。それ以外に、区独自、あるいは指定管理者候補のほうの自主事業というものを、これから考えていきたいと思っているところです。","id":"exchange-023"},{"speaker":"渡部委員","kind":"質問","question":"今の平塚橋会館で入って右側を借りているような借り方は、逆にできなくなるということですか、一般の方が。","respondent":"白鳥高齢者いきがい課長","answer":"これまでの集会所機能といいますか、一般の方も利用できるような予約システムでもって考えているところです。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"これは要望でいいんですが、多分パーテーションか何かで広く使うこともできれば、区切って３団体に貸し出すということもできると思うんです。にっちもさっちもいきませんので、そういう要望があるということだけ、お願いいたします。","respondent":"白鳥高齢者いきがい課長","answer":"このパーテーションにつきましては、この施設の１階のフロアにスタジオということで、ここだけは防音仕様ということで行っております。そのような場合の対応については、そういったことも考えながら、その辺のところを十分に注意していきたいと考えています。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"その中でお伺いしたいのが、１室当たりどれくらいなのか、１床当たりどれくらいなのかということ。もし当てはまるんだとすれば、この図で言うと、どこの部分をあらわしているのかを説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"高齢者部門の建設によりまして、東京都の補助金として６億７,０００万円を、現在予定しています。この中には、防災の拠点というのも入ってあります。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"私があらあら計算したところ、大体同じような金額になったんですけれども、この中に、今日説明に出ている防災の福祉避難所機能、具体的にはどの部分を指して、どういうことをおっしゃっているのか、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"備蓄倉庫については以上なんですけれども、あと防火水槽を用意しておりまして、２００人想定で３日分くらいの水を確保しております。それから、共用の子どものスペースが西と南のところにありますけれども、こちらに、かまどベンチや収納ベンチを用意する予定になっております。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"説明は、備蓄と、かまどベンチ等の一般的な災害の用意をするものというのは、よくわかったんですけれども、要援護者受け入れというところの特筆すべき点というのは、何かあるんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"今後の予定ですけれども、二次避難所でもさらに対応が難しいような方々について、こちらで受け入れを行うことになる予定です。主に考えられることとしては、１階の部分の使い方になるかと思いますけれども、使い方について決めていきたいと考えています。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"まさにモデルケースになるところだと思いますので、しっかり指定管理者とも協議をしていただいて、しっかりした機能を持たせたところにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"１階の平面図のところになるかと思うんですけれども、２の(2)で、どういうふうな仕切りになるかというところ。それから、コミュニティ室の３部屋分の一番左は、これは調理室仕様の図なのでしょうか、その辺をちょっと説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"高齢者福祉課長のほうから説明がありましたが、そういった中では、こういったことを考えているところです。そういったことを支援するという意味合いの中でも、これからも展開していければいいかなということから、調理台を用意しているものです。","id":"exchange-030"},{"speaker":"井上委員","kind":"意見","question":"そういう目的外使用バージョンなのか、それともそれは撤廃なのか、その辺はどのような感じで考えていますかとの意見を述べました。","respondent":"白鳥高齢者いきがい課長、早津健康福祉事業部長","answer":"日曜日の利用につきましては、従来どおりこの中で利用していただく、こんなようなことで考えているところです。ですから、目的外使用は、今のシルバーセンターの運用形態と同様に考えていきたいと思っているところです。 これは条例の案文等を考えたうえでやりたいと思うんですが、一般の方の利用のような施設になりますが、目的外使用ではなくなるかもしれません。それは構成を、新しい施設の条例の中で考えさせていただきたいと思います。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"この辺は緑色スペース状態と考えていいのか、いやここはシルバーセンターのところですよいうふうに考えているのか、図面の説明が１点。ここをどのように思っているかということを、この図でちょっと疑問なんですけれども、いかがか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"やはりここは、今現在の中では、共有スペースというような捉え方をしています。この中で、あとは運用面の中でいろいろと可能性を探りながらの十分な地域交流として充実した施設になるように検討してまいりたいと考えております。","id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"７５％くらいのものにして初めて１００％使えるみたいなことになっていますので、ちゃんととめれられるような対策をとってほしいと求めました。なかなか変えていただけませんので、気をつけていただきたいということで、強く要望をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問","question":"今の井上委員の質問と、また多世代というものの何かモデル的な位置づけなのか、その辺を説明するよう求めました。","respondent":"白鳥高齢者いきがい課長","answer":"こちらのほうにつきましては、先行モデルというような考え方で、今現在進めているものです。","id":"exchange-034"},{"speaker":"たけうち委員","kind":"質問","question":"その背景というか、そうすると、そのねらいは何になるのか。高齢者の使えるスペースというのは増えていくべきなんでしょうけれども、子どもの施設等の統合ということですか、その辺はどうなんか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"確かに高齢化率が高くなっている現状の中で、平塚橋会館、シルバーセンターも、地域の高齢者の方々に多く利用されてきたという実績を持った施設です。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それから、トイレの個数ですが、１階部分だけを見ても、男子トイレ、女子トイレあって、図にあるだけの数なのかどうか、何個あるのかということ。資料には記載がされていないんですけれども、特別養護老人ホームの部分、どういう形になるのか、ちょっとお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"そこでの検討をしていきたいと考えています。避難経路を２カ所、エレベーターを三つ設置しておりますので、どういうような避難対策をするかということも一緒に検討してまいりたいと考えています。","id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"非常用電源というのは、ここは整備されるのかどうかということ。新しくできる施設は、ぜひボタン型にしてほしいと思うんですけれども、そこはいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"今、実施設計をやっている最中でございまして、それができるかどうかということも確認をしてまいりたいと思います。","id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それから、マンホールトイレなんですけれども、外観イメージを見る限りでは、結構マンホールトイレをつくれる余裕があるのではないかと思うので、スクエア荏原なんかもつけられていましたけれども、ぜひ、できる限りつくる形でお願いしたいんですけれども、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ちょっと見づらいんですけれども、１階の駐車場と書いてあるところに丸が四つ縦に並んでいるところがあるかと思うんですけれども、そこがマンホールトイレを予定しています。","id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"では、今のところ四つということで、もうちょっとできないものかというのは、ちょっとこれからになってしまうのか、設計はもうそれで決まってしまっているのでしょうかね。","respondent":"永尾高齢者福祉課長","answer":"こちらについても、設計の段階で、水の管理とかそういうものもありますので、どうなっているかということを確認しつつ、増やせるどうかということも相談していきたいと思います。","id":"exchange-039"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"いろいろ設計なんかも今後になってくると思うんですけれども、要援護者の受け入れの場としては、ほんとうに多く求められているものですので、対応ができるだけのものを、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-03","title":"の平成２５年度、高齢者福祉週間行事","agenda":"の平成２５年度、高齢者福祉週間行事","exchanges":[{"speaker":"井上委員","kind":"質問","question":"その２のほうの社会福祉協議会主催事業のアスタリスクの、１０年ということで、今年で終わりということは、これは社会福祉協議会が１０年をめどにということで計画をされていて、そういう判断なのか、社会情勢においてということなのか、これはどういった形での期間満了ということなのか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"社会福祉協議会のほうでは、８０歳以上の方々のお祝い事業というものは、米寿の方々から節目のお祝いということで続けていくと聞いております。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺は説明ができるという部分で載せたんだろうと理解しますので、そういうところで、ちょっと整理はしていただきたいと考えています。その１のほうのしながわ出会いの湯なんですけれども、通常やっているのと何か違いがあるんでしょうか、説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"これにつきましては、敬老集会にちなんでということで、また別に設定しているものだとは認識はしています。この高齢者週間行事に合わせまして、皆さん方に知っていただくという意味合いの中で、あえてここのしながわ出会いの湯を掲載させていただきました。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"何か通常やっているのとの違いはあるんですか、ないんですか、ちょっと説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"２時から始まって、３時から入浴というようなタイムスケジュールの中で行っていくというのは、そのとおりです。実施する曜日につきましても、毎週木曜日というのも変更してございませんけれども、改めて掲載をさせていただいているものです。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"意見","question":"傘寿から百一歳以上、民生委員が訪問してお祝金をお渡しするというという事業なんですけれども、原則、ご本人にお会いして、ご本人が入院とかの場合には、ご家族のサインか何かもらってお渡しするという形でしたっけとの意見を述べました。","respondent":"白鳥高齢者いきがい課長","answer":"対象者の名簿が、それぞれ節目のお祝いごとの年で出ております。ご本人の受領印をいただく、そこで、お元気でいらっしゃるかどうかというご様子も伺いながらお祝品をお渡しするというようなことで行っております。","id":"exchange-044"},{"speaker":"たけうち委員","kind":"質問・要望","question":"でも一方で、やっぱり実態がないということも確認しなきゃいけないということで、民生委員は大変ご苦労されると思うんです。ぜひその辺はアドバイスをしていただいて、スムーズにいくようにお願いしたいという要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"改めてこの所管の中で伺いたいのが、いわゆる応札が不調に終わった原因というのでしょうか、そこの原因が何だったのか明確にお教えいただければ。前回の８月１４日の入札の条件から、９月２０日に入札するにあたっての条件変更等が何かなされたのか、わかる範囲でお願いします。","respondent":"永尾高齢者福祉課長","answer":"建設業者について応札いたしましたけれども、結果的にこの金額では落ちなかったというのが正しい表現だと思います。方法として、もうちょっと範囲を拡大しまして、都内の業者Ａランクまでを対象に実施する予定になっております。","id":"exchange-046"},{"speaker":"渡部委員","kind":"質問","question":"お伺いしまして、ということですが、要するに条件変更はなされてないという感じで捉えさせていただいたうえで再度の質問なんですが。例えば９月２０日にまた不調になってしまった場合、なってしまった場合は、また同じような繰り返しがされるのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"都内にいたしますと、かなりその範囲が広がりますので、対象になる業者の数も増えると見込んでおります。金額につきましては、もう１回、予算どおりの金額でやる予定になっております。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"今のに関連して、１点だけ伺いますけれども、杜松小学校跡地の特別養護老人ホームなんですけれども、ここに関しては、補助金はどのくらいなのか、全体がわかれば、それだけ説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"ちょっと今すぐに資料が出てこないので、もうちょっとお待ちいただけたらと思います。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました、所管も異なるというか、また後ほど個別に教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"去年だと思うんですが、見守りをしていただくような事業があったかと思うんですけれども、今年はそういったことがされているのか、何か取り組みとして変化はあるんか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"熱中症の予防と対応をやっておりまして、民生委員が高齢者相談員という立場ですけれども、要援護ひとり暮らしの高齢者の世帯の訪問をしております。","id":"exchange-050"},{"speaker":"井上委員","kind":"質問・要望","question":"９０名の方がどういった対応で、点滴で帰られたとか、何かその結果がわかれば教えていただきたい。今年はそういったことも考えなければいけないくらいの猛暑だったんですが、そういったところは、区はどのように対策をとられていたのか尋ねました。","respondent":"永尾高齢者福祉課長、高山品川区保健所生活衛生課長","answer":"民生委員は、このときだけではなくて、常に日ごろから高齢者相談員として訪問活動、また電話で対応等をしています。電話での対応ができづらい方、電話での対応等、いろいろな方法で確認をされていると思います。 口頭での報告で大変恐縮ですが、９０名のうちの、いわゆる中等症以上と言われる方が３９名ということで伺っております。中等症以上の方が３９名、軽症で帰られた方が５１名ということで、入院をしなかった方が５１名ということです。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/626613?Template=document&Id=3364#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":37304,"voices":129}},{"id":"h25-20130826-8","meetingId":"h25-cm08","date":"2013年8月26日","dateIso":"2013-08-26","committee":"建設委員会","time":"午後 １時００分～午後 ４時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件整理しています。","topics":[{"id":"topic-01","title":"」を行います。 初めに、(1)「区民住宅（あき家）入居予定者登録募集","agenda":"」を行います。 初めに、(1)「区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１個だけいいですか。あき次第抽選するということで、抽選で順位を決めるということだと思うんですが、現時点であき家はあるのか尋ねました。","respondent":"大串住宅担当課長","answer":"その審査の結果、この２戸が埋まってしまうと、全部で今のところ１９戸が今現在はあきが出ているということです。今現在のところは２１戸、２戸は審査中という、そういった状況になっております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"大体どのくらいの応募があるんですか。どのくらい応募があるのか。","respondent":"大串住宅担当課長","answer":"１３６件申し込みがあったんですけれども、登録という形でされた方が１１１件という形になっております。毎年、大体これぐらいの数字になっております。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"規定外ですよということで却下という形になる場合は、どのようにお知らせをして、そういうケースがあるのかどうか。いかがか尋ねました。","respondent":"大串住宅担当課長","answer":"入居の予定登録という形になりますので、２戸審査中というふうにお話をさせていただきましたけれども、こういった可能性は出てきます。それはお断りをするという形です。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"要は、基準があって、それに合わないという形の場合には、事前に、あなたは規定から外れますよということでお断りするのか。でも、受付は受付でしてしまって、順番が来た段階で規定に対してどうかということをするのか、いつの時点で見分けというのをするのか尋ねました。","respondent":"大串住宅担当課長","answer":"その時点でこちらは該当しませんよということでお答えはさせていただいていますので、一定程度要件を満たしている方という形になります。一時的には一旦事前の前払いといいますか、そういったことはさせていただいている形になります。","id":"exchange-004"}]},{"id":"topic-02","title":"平塚橋会館跡高齢者福祉施設等の整備について","agenda":"平塚橋会館跡高齢者福祉施設等の整備について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"地域の方が使えるところがあるようなことを伺ったんですが、その辺の点がわかったら教えてほしいのと、わかったら説明を求めました。","respondent":"大串住宅担当課長","answer":"それから、こういったところで地域の方もご利用できるようなスペースというのは、１階部分については考慮させていただいているといったところです。そういったことは検討の俎上に上がっているというふうには聞いておりますけれども、詳細につきましては、よろしくお願いします。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"意見","question":"人の動きとか、私は集中してしまっていいのかなという率直な疑問を持ったので、その辺はこの間の議論の中で行われていたのかどうか。そういう検討があったのかどうか、意見が出たのかどうか、その辺を聞かせてくださいとの意見を述べました。","respondent":"大串住宅担当課長","answer":"すみません、高齢者関係の施設には若干変更点が幾つか出てきているのかと思うんですけれども、当初の予定から大きくは変更はしてございません。基本的には５階まで住民の方だけがご利用できるという形にするつもりです。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"人の流れがスムーズに行くように考えていただきたいので、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"空室が３戸で五つあくんですよねというのと、どういう形になっているのか、はっきりと分けられてわかるようになっているのか。ここは完全に住居者だけの出入りとしてセキュリティがきちんとかかるような形になるのかというのを説明するよう求めました。","respondent":"大串住宅担当課長","answer":"うち２世帯の方については、部屋は５戸あいておりまして、４３世帯の方が戻ってくる予定になっております。こちらについてのセキュリティ、今のところ防犯カメラ等々の設置を考えておりまして、このように考えておるところです。","id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"そういうふうにならないような構図になっているのかどうかということと、暗証番号というような部分があるので、その辺はどうでしょう。防犯カメラだけだと、別に出入りは自由なわけであると思うんですが、そこら辺をもう少し、セキュリティに関してどういう対策をとられるのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"なので、どういう形で仕切りをつくって区分けをするんですか、それがないと、いろいろ入ってきてしまいますよということなんです。その部分はいかがか尋ねました。","respondent":"大串住宅担当課長","answer":"そこの中を入ってくるような形になりますので、まず一般の方がここはオープンな駐輪場だというふうな認識はできないような状況になっています。ですので、あまりそれでほかの方の自転車が置場がないのでこの中にということは考えにくいのかなというふうには思っているところです。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"確認","question":"やっぱり議会としてそれを確認したいので、例えば、国の補助金なんでしょうか。同じ行政同士ですので、事前から手を組んでスケジュールを組むことはできなかったのでしょうかという二つの質問ですが、ご答弁をお願いいたします。","respondent":"大串住宅担当課長","answer":"１日も早く開設したいという思いでいろいろ調整を進めてまいりましたけれども、それはなかなか最終的には東京都の最終的な判断として、回答として。そうした中で開設時期を残念ながら変更していくというのがこういった状況になっているところです。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"それが結果として工期のずれに響いているということなんでしょうかという再答弁をもう一度お願いしたいのと、先ほど、区には責任がないわけですよね。繰り返しませんけれども、そういう情報なり、都側の動きを事前にとらまえた上で対応することはできなかったのでしょうかというのは。","respondent":"大串住宅担当課長","answer":"先ほど申し上げましたように、東京都が窓口になって国の補助金も含めて交渉をしてまいりました。都側の最終的な回答として、両部門、品川区が求めるような時期での補助金のスキームは難しいというご回答をいただきましたので。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"それと、この図面を見ていると、１階のところに総合案内というところがあります。２階、３階の当該施設については介護職員室ということがあるんですけれども、どの事業部が中心になってここは切り盛りをされるか説明を求めました。","respondent":"大串住宅担当課長","answer":"それから、１階の事務室の関係です。こちらにつきましては、高齢者部門のほうの関係が事務室の総合案内等々は行うと、このように聞いています。","id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"私、担当の課ではないのでわかりませんというようなことがあると困るなと思って聞いたんですけれども、そこのところはどういうふうに対応がとられるのか説明を求めました。","respondent":"大串住宅担当課長","answer":"こちらの特養関係につきましては、法人に委託をするというように聞いておりますので、この法人を通しての管理ということになろうかと思います。一体的な管理を行うというところで、そのような状況が発生しないような形に努めていきたい、このように考えております。","id":"exchange-014"},{"speaker":"原委員","kind":"質問・要望","question":"大体図面的に、細かく入っていってしまうとすごい時間がかかってしまうので、ざっくり先にお聞きします。その向かいに備蓄倉庫があるので、これはもう少しどうにかならなかったのかなと、まずそこまで教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"答えられる範囲で結構。後の質問と絡んできますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"５３平方メートル、これがちょっと大きさ的にどうなのかなという、これが質問第１です。その辺が１点と、その３点、お願いします。","respondent":"大串住宅担当課長","answer":"世帯交代のニーズの多い世帯の対応もある程度考えなければならないというところで、今のところ、こういった部屋の構成を考えてやっているところです。","id":"exchange-017"},{"speaker":"原委員","kind":"質問","question":"非常に理想的な理想形の形だと思うんです。ですから、それ以上に立っていけるようにお願いをしたいので、そこの点でご意見があればお願いいたします。","respondent":"大串住宅担当課長","answer":"やはり早晩、どうしても築年数の関係で建て替えということも検討せざるを得ない、こういう状況になってこようかと思います。こういったものを図っていきたいと考えていますし、こちらの建て替えについては将来を見越した形で進めていければというふうに考えております。","id":"exchange-018"}]},{"id":"topic-03","title":"大崎西口公園の整備に向けて","agenda":"大崎西口公園の整備に向けて","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"新たなここのところで、この公園は品川区立の公園になるんですか。品川区の公園が変わるのだったら、その辺も説明をしてほしいと求めました。","respondent":"溝口都市開発課長","answer":"公園の考え方ですけれども、現在、資料の下の図に黒く塗られているところに移設して新たに都市計画変更して定めたものになっております。整備はあくまでも再開発組合が整備を行いますが、以後、区立公園として維持管理していくという形になるものです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"質問は、品川区立でいいんですね。開発組合が整備をするけれども、区立だということでよろしいんですね。","respondent":"溝口都市開発課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"どういう形で、その辺の手法がどうなっているのかというのと、現地に表示がされるだけなんでしょうか。もうちょっと広く利用者がいらっしゃると思うんですが、その辺はどうなんか尋ねました。","respondent":"溝口都市開発課長","answer":"町会のほうからさらに説明会を開いてほしいとか、説明に来てほしいという要望は、今日現在まで来ていないというふうに聞いているものです。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひいろいろな部門で意見を集めてほしいなと思うのと、なるべく災害時に活用できるようなものを広場があったら置いてほしいという願いがいっぱいあるんですけれども、どのくらいを考えているのか説明を求めました。","respondent":"溝口都市開発課長","answer":"一応、ベンチを配置するところにそういった機能をということを考えていて、まだ今後詳細を詰めていく中で決めていきたいというふうに考えております。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"防災性というのはかなり求められていくと思うので、ぜひその辺は十分検討して配置をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"今後の予定で、「現在、整備方針・基本計画を地元町会等へ説明中」ということで、これを使って説明をしているんですね。どういう説明、何か全然この計画図がわからないんですけれども、これは何を意味しているんか尋ねました。","respondent":"溝口都市開発課長","answer":"町会等の説明についてですが、裏面の整備方針、基本計画図、こういったものをお示ししながら説明していっているものです。薄く緑で塗られているところには低木の植栽、丸く書かれているところについては高木の植栽が入る、そういった計画になっているものです。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"今の説明を受けたのでわかるんですけれども、これ、説明をもらわないと何の丸かよくわからないんですけれども、地元の方たちには、これは説明しているんか尋ねました。","respondent":"溝口都市開発課長","answer":"すみません、地元の方には、図の見方を含めて説明しているというふうに聞いております。申しわけありません。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"今のに続けてですけれども、この基本計画図をパッと見たときに、補助１６３号線がどこに走っているかわからないんです。今のような質問は出なかったでしょうし、もう少し指摘がちゃんとできたと思うんですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"交通広場との境、そういったものがわかりづらいまま資料を出しまして、これにつきましては申しわけありません。以後こういったことがないように、皆様方にわかりやすい資料の作成には努めていきたいというふうに考えております。","id":"exchange-026"}]},{"id":"topic-04","title":"使用済小型電子機器等（小型家電）の回収について","agenda":"使用済小型電子機器等（小型家電）の回収について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"乾電池とか、携帯電話なんかでも、販売店で回収をしているところもありますよね。その辺の働きかけがどうなっているのかと、あと、リサイクル費用の負担が新しい法律のところでどういうふうになっているのか説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"いずれにいたしましても、事業者、製造者責任、あるいはそれに対する対応というものは引き続き求めていくというのが区の立場です。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"意見","question":"そういった面でもぜひ事業者への責任を拡大していく方向が必要であると思っていますので、この辺の働きかけをよろしくお願いします。運搬とか、今までよりも増えますよねとの意見を述べました。","respondent":"小林品川区清掃事務所長","answer":"今回できるだけそういった負担を新たに発生させずに効率的に進めていくということで、ただ、そのトラック４台分ほどの費用は新たな負担になります。極力自治体の負担を発生させないようにという形で、今、事業化の具体策を進めていくというスタンスにはなってあります。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"確認","question":"回収ボックスを監視するような形になるのでしょうかというのが１点と、そういうところの体制も検討されたらいかがでしょうかということで質問したのですが、いかがか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"新しい箱をそこへ置いて、回収された箱を交換で持っていくということで、持ち去り等をまず入り口で防止しようというふうに考えております。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、だからといって、私たちは税金を使って全部それを対処しろとは言いません。それはできない話ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"すみません、一言だけ。ちょっといい話ではないんですけれども、これによってどこかが利益を出すというようなことはあるんか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"国の方針としては、いわゆる持ち出し、結果的に区から委託の費用を出さなければならないという可能性もあるというふうに危惧されているところです。いずれにしましても、採算面から言うと、非常に厳しいと考えています。","id":"exchange-031"},{"speaker":"木村委員","kind":"質問","question":"これ、国が相手の事業になると思うんですけれども、これによって、金、銀、銅、レアメタル等で大体どれぐらいの量が、都市にある鉱山みたいなものですけれども、その中からどれぐらいの量がとれるのか、わかったら説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"新聞報道やいろいろなもので都市鉱山という形でいろいろな数字が出てくるんですけれども、それぞれいまいち責任をもってこのぐらいでしょうというところまで、申しわけありません、不勉強で出ていないのが現状です。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"補助金のほう、自治体が持ち出しをしてしまうケースもあるだろうということなんですが、これは品川区としてはどのように考えられているんですか。品川区の持ち出しをどのような、全くないと思っているのか、そこら辺はどういう形なんか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"つまり、従前それはどうやっていたかというと、既存のリサイクルルートで回収していくことで対応していくのが現実的な対応かなと考えております。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"それについては、こちらサイドから指導されよという形で請求はできるものなんでしょうか。それはどう考えていますか。","respondent":"小林品川区清掃事務所長","answer":"現行の規定以下、全て目を通したんですけれども、請求できるというふうにはなっておりません。別途、国が若干助成をしても、それをシステムとして成り立たせる責務が国にはあるということは求めてまいりたいと思っています。","id":"exchange-034"},{"speaker":"原委員","kind":"質問・要望","question":"１点質問なんですが、国へというお話だったんですけれども、もう１回その辺のところをご答弁いただきたい。","respondent":"小林品川区清掃事務所長","answer":"価値としてコストの中にも反映していく必要はあろうかと思いますが、基本的にはそれが原因で多くの負担を逆に区民に求めることのないように、事業の進め方については十分留意して対応してまいりたいと考えています。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"それから、もっと広範囲に考えていくのがいいのかどうかわからないまま質問しているんだけれども、そういうことも含めてどうなんですか。品川区の単独事業である必要はないんじゃないかと思うんですけれども、現時点でのお考えを説明するよう求めました。","respondent":"小林品川区清掃事務所長","answer":"今年度中に実施済みないしは近々実施というところは、２３区の中でもここ一、二年の間に過半数の区が事業参画してこられるものと思います。今年、この辺で一定採算ラインが成り立つということになると、後発の区も参加してきてくれるものと期待しております。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"実証実験という話を聞いたんですけれども、これは言葉はおかしいですけれども、実証実験ごとに見た事業と判断していいですか。何を言いたいかというと、この事業は実証実験で終わるんか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"回収する家庭、いわゆる採算ラインで安定したシステムとして継続していくのかというところの実証実験事業に品川区は参画、採択されたです。説明が下手で申しわけございません。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"意見","question":"それから、これがうまく回っていけば、さっきの話に戻りますけれども、品川区単独でやる必要はないと私は思うわけです。やっぱり２３区に働きかけをしていく、２３区だけの事業の中で考えるのであれば、まずは実証実験を成功しますようにお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"これまで小型家電も回収しますということですから、いわゆるここに書かれている地域のところで、シルバーの方がやっていらっしゃったのでしょうか。なかなか出しにくいという、ここら辺のところの工夫が必要かなと思いますが、いかがか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"今後いろいろな媒体を通じて、安心して出していただけるような方法の提示、それからシステムのＰＲ等についても見てまいりたいと思います。今、拠点ではシルバーの方を中心に対応していただいておりますので、こういうことで安心ですよというような対応も含めてできるように。","id":"exchange-039"}]},{"id":"topic-05","title":"大井町駅区営自転車等駐車場大井陸橋下の供用開始並びに大崎駅東口区営自転車等駐車場の台数変更について","agenda":"大井町駅区営自転車等駐車場大井陸橋下の供用開始並びに大崎駅東口区営自転車等駐車場の台数変更について","exchanges":[{"speaker":"こんの副委員長","kind":"質問","question":"大崎駅のほうの駐輪場には、チャイルドシートつきの自転車利用者からの声ということで、それを踏まえて平置きスペースをとあるんですが、大井町駅のほうは、これはどのようになっていらっしゃるのか尋ねました。","respondent":"谷口交通安全担当課長","answer":"大井町のほうにつきましても、６７台を設置する予定です。","id":"exchange-040"},{"speaker":"こんの副委員長","kind":"質問","question":"６７台分、チャイルドシートがついた自転車が置けるスペースをというところであるわけですね。まだその場所が決まっていないというのであれば、手前側のほうにして差し上げるといいかなというふうには思いますが、その点はいかがか尋ねました。","respondent":"谷口交通安全担当課長","answer":"委員ご指摘のとおり、今回の場合は平置きスペースを確保していますので、出し入れについては特に問題ないと考えておりますので。出し入れしやすい場所の設置を考えております。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"今の件ですが、６７台、平置きということですけれども、これは区別がつくんですか。それはどういう形になるのか尋ねました。","respondent":"谷口交通安全担当課長","answer":"そういうのが区別つくように、ちゃんとスペースはチャイルドシートつきということで設けてありますので、それは大丈夫なように整備しています。ご理解いただきたいと思います。","id":"exchange-042"},{"speaker":"西本委員","kind":"意見","question":"ということは、せっかく６７台確保しても、チャイルドシートつきの自転車ではなくて、普通のママチャリが入れられてしまう可能性もありますよね。それの区別をどうされるのかとの意見を述べました。","respondent":"谷口交通安全担当課長","answer":"その件につきましては、定期利用と当日利用がありますので、ご利用の方につきましては、ちゃんと定期利用の番号もちゃんとしていますので、それは安心していただければと思います。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"それは定期利用だけということで、当日利用にはないですよということの理解か尋ねました。","respondent":"谷口交通安全担当課長","answer":"当然、当日利用も準備しています。係員もおりますので、その辺は巡回しながらやっていきますので、よろしくお願いしたいと思います。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"定期利用はいいと思うんですよ、定期利用はその自転車ですから。専用につくりましたと言っても、実際に使われていないとなれば、むだですよねという考え方になりませんか。","respondent":"谷口交通安全担当課長","answer":"委員のご指摘のとおりそうだと思うんですけれども、実際は、９月１日に移設しましてから、利用状況等を踏まえながら、その実態を踏まえて、また引き続き、どのような方たちの利便性が向上するかということで検討しながら進めてまいりたいと思います。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"要望を聞き入れていろいろ工夫されました、実際使っていただきたい方々が使えないというようなことでは、何の意味もないと思うんです。大抵モラルがないので自転車問題が起きるので、そこも含めて今後対応を考えていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"国道１５号線徒歩帰宅者支援対策の実施について","agenda":"国道１５号線徒歩帰宅者支援対策の実施について","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"そのことの確認をまずお願いします。いかがか尋ねました。","respondent":"鈴木防災課長","answer":"とりあえずこの１５号線の徒歩帰宅者のほうについては、先ほどご説明いたしましたように、医療関係の対応も考えられると思いますので。申しわけありませんでした。","id":"exchange-047"},{"speaker":"伊藤委員","kind":"意見","question":"例えば、国道１５号線沿いでは、山手通りの交差点に品川医師会がたしかありますね。〔「陸運局」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問","question":"陸運局か。あれも広大なスペースがあるでしょうから、それはいろいろな検討なりを加えてはいかがでしょうかという質問なんてすが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"例えば地域の方からこういうところがあって協力してもらえるよというような情報があれば、もちろんお声かけをするように考えております。","id":"exchange-049"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そういうお考えの中で、ぜひともその中に入れていただきたいのが、１,０００名ぐらい入るスペースがあります。ですから、そういうことも含めて連携をとっていただけますように、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"２点伺います。おのおの上に課題が書いてありますけれども、何をどう活性化させるのか、そこのところをどういうふうにお考えなのかを教えていただきたいのが一つ。","respondent":"鈴木防災課長","answer":"具体的な行動ができる対策なり考え方を決めるのが目的なのかというご質問ですが、実際の支援ができるような体制、環境をつくることが目的です。","id":"exchange-051"},{"speaker":"大沢委員","kind":"質問・要望","question":"モデルということで、先ほども課題のモデルということでやるということなんですけれども、何が言いたいか。そこのところはしっかりとした意識を持ってやっていただきたいんですけれども、それを受けてもう１回、この事業に対する思いをお述べいただくよう求めました。","respondent":"鈴木防災課長","answer":"今ご質問いただきましたように、区としましては、しっかりとした地域における支援対策ができる体制を組むというのが目的になります。目的をはき違えることなく、地域で実際にしっかりとした支援ができる体制を目的にこの事業を進めていきたいというふうに考えております。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"１５号線、なるべく企業であれば企業の中にとどまるという、そういう動きも出てきていると思うんです。３・１１を踏まえ、こういう１５号線の帰宅困難者というレベルは、その辺はいかがか尋ねました。","respondent":"鈴木防災課長","answer":"やはり取り組みが始まっておりますので、もしくは入らなくても、対策についての協力をいただくようなお話はする予定でおります。コンサルも委託をかけながら、いろいろな関連情報を集める中で、できる限り必要な情報の一つとして集めたいなというふうには考えているところです。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"具体的にどういう、全部動いていくなと思うので、それをしっかりとしていただきたいなと。ぜひ成功をさせていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"木村委員","kind":"質問","question":"これは実験的な取り組みだというようなことだったと思うんですけれども、でも、これはせっかくのチャンスでもあると思います。これをどのように今度は実際にそういう方々に周知するのか、そういう方法というのは何か考えているのか尋ねました。","respondent":"鈴木防災課長","answer":"これから協議会でお話し合いをしていただきますが、その結果を踏まえまして、基本的にはやはり沿道の区民の方が中心になると思います。","id":"exchange-055"},{"speaker":"木村委員","kind":"質問","question":"各企業、たまたまそこを通りかかるようなことで、そういう災害に遭われる方もたぶんいると思うんですよね。ここから２５０メートル先、５００メートル先、そういうふうな話にもこれからなっていくような可能性というのはどうか尋ねました。","respondent":"鈴木防災課長","answer":"都のほうの事業の中で徒歩帰宅者の支援ステーションに指定されている、今後、協議会の中で話し合いをして決めていただくことになると思います。","id":"exchange-056"},{"speaker":"木村委員","kind":"意見","question":"これには国道１号線、そして１５号線、中原街道ということが出ているわけですけれども、これ以外にもいろいろな道があろうと思います。もっとどんどん品川区内中もっと広げていくというお考えとか、そういうふうにしなければならないと思いますけれども、お考えを説明するよう求めました。","respondent":"鈴木防災課長","answer":"国道１５号線で協議会を立ち上げて、対策を練りながら実働訓練まで約２年近くをかけて実施する予定です。国道１号線、それから中原街道と同じような帰宅支援道路、地域によってまた対応してくるメンバーとか対策も変わってくるかと思いますけれども。","id":"exchange-057"},{"speaker":"伊藤委員","kind":"質問","question":"たまたま国道１５号線沿いを見れば、それから、青物横丁駅にもたしかあります。協力は結んでいるはずでしょうから、人数が収容できるスペースが当然あるでしょうからと思うんですが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"実際には通常の利用客の方への対応も当然事業者としていますので、２階、３階の低層が商業施設のところが多いんですね。個別にお声かけをさせていただいて、状況がもし合ってご協力をいただけるようであれば、当然お願いしたいというふうに考えております。","id":"exchange-058"},{"speaker":"伊藤委員","kind":"質問・要望","question":"港区と大田区と協力してお話ししていくわけですから、それは協力をして中で対応してほしいと求めました。それはさまざまなところから検討していっていただきますようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"こんの副委員長","kind":"質問","question":"その点はどうされるのかというところと、この１５号線の状況はわからないということだったんですが、ある程度のデータが必要かなと。どういった形でその数字が出てくるのか、社内で社員の方をきちんと避難の体制がとれる、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"対策を進めるためには、正しい前提となる情報が必要になりますので、その辺は区としてもしっかりと情報収集したいというふうに考えております。商店街や町会の町会長にもお聞きする予定なんですが、２年前の東日本大震災の実際のときに、そのときにどのような対応をされたり。","id":"exchange-060"},{"speaker":"あべ委員長","kind":"質問","question":"すみません、私からも１点お伺いしたいと思います。この一連の対策においては、どういった状況を前提にされての訓練になるのかということを説明するよう求めました。","respondent":"鈴木防災課長、松代防災まちづくり事業部長","answer":"規模ですが、基本的には、東京都と品川区の地域防災計画にあります最大規模の地震の想定をベースに考えることになるかと思います。ただ、徒歩帰宅者支援に限らないのですが… 駅自体ではＪＲがしっかりと対応するというふうになっておりますので、目黒区と品川区が共同で支援していこうと、こういう協議会も立ち上げています。","id":"exchange-061"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"本日も出されたと伺っているんですが、一つは、都市計画道路補助２９号線沿線地域を除外することを求める要望書」というものが出されています。ぜひ今日はよい機会なので、この要望書が届いていることに対して、区の見解をお伺いしたいなと考えていますとの意見を述べました。","respondent":"品川木密整備担当課長","answer":"要望書の中で補助２９号線の、先ほど説明しました1)番のところかと思います。こういった点から、区のほうも、ここの補助２９号線沿道３０メートルについて、特区を入れてやっていくという考えです。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"提案","question":"私はぜひ地域の皆さんからこの２９号線、これを切り離して提案すべきではないということを議論していただきたいなと思うのが１点です。そういったうわさも流れているといった声も伺うので、大もとのところではなくて、ぜひその辺も入れていっていただきたいなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"伊藤委員","kind":"提案","question":"そうしないと、一方的な議論ばかり進めていく姿をすごく感じるので、そういうところの資料なり、お考えも示していただきたいということがありますね。そういうことでよろしいんですね、今の提案としてはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"西本委員","kind":"提案","question":"今、伊藤委員の提案での中間情報ですね、これはきちんと当委員会の中で話して提案していかなければいけないと思うんですね。何人かに出てきてもらうとかでもいいし、討論会でもいいしという、そういうのをやりたいなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"西本委員","kind":"意見","question":"この委員会の中ではなくて、もっと違うものもできるのではないか。的な意見だけをたくさん持っていてもしようがなくて、隠れている意見もやっぱり収集していくのが私たちの仕事ではないかということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"木村委員","kind":"質問","question":"ですから、そういう中で、少しでも住民の皆さんにそれがしっかりと説明できるようなことをやるべきではないかなとも思っています。自分たちの生活をしていく場所、そういうこともやっぱりしっかりとしたものを提示をすべきだろうと思いますし、そのように思っています。","respondent":"あべ委員長","answer":"安全なまちをつくっていくということ自体は、その手段と将来的にということで、効果の調査、そして生活の支援あるいは補償について勉強していくということですね。","id":"exchange-067"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もしくは災害を減災するための目的に賛同しますという方もいらっしゃるでしょうから、繰り返しになりますけれども、やっぱり私たちが思うところは。それをただ口で言うだけではなくて、行政なりにお願いしたいのは、阪神・淡路大震災の中でもこれだけ被害が減少したんだという実績を示してほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、特に一番強調して職員の方にお願いしたい、区民に対して一番身近なところにいるんだよというプライドを持って当たっていただきたいと。ですから、いろいろなことがオープンに出せるような形での委員会運営をしていきたいと思いますので、そういうのが意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"原委員","kind":"質問","question":"それが１０メートルずれるのかと言ったら、こんな形になるのではないですかと、参考にどうでしょうと持っている議員もいると覚え聞きます。ですから、そういった具体的な資料を、より具体性のある資料を提出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これからもこんな資料をとお願いしたら出していただきたいなと思うのと、住民の方々の意見も真摯に受けとめていくという意味では、ぜひ住民の声を聞く場所をつくっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/890615?Template=document&Id=4082#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":64607,"voices":177}},{"id":"h25-20130826-9","meetingId":"h25-cm08","date":"2013年8月26日","dateIso":"2013-08-26","committee":"文教委員会","time":"午後 １時００分～午後 ３時２４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"(1)平成２６年度新入学生の学校選択希望理由調査の実施","agenda":"(1)平成２６年度新入学生の学校選択希望理由調査の実施","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ちょっと確認なんですけども、中学校では３５９人の内訳という理解なんですか、こういう具体的な項目ではとっていないんですか。具体的に学校運営の改善というのはどういうことを想定してこういうふうに書いているのか、そのあたりをもう少し詳しく教えてほしいと求めました。","respondent":"和氣学務課長","answer":"アンケートを今回２６年度に実施するのが希望したのみの方たちなので今回出しましたが、数字は別に持ってあります。やっぱりここが増えていくということも１つの大きな努力結果ですので、そういう意味で、現状をしっかりつかまえたいです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、近々教えていただきたいということで、かいつまんでどういうことを皆さんが考えていらっしゃったのかをぜひ教えてほしいと求めました。その点についてはいかがか尋ねました。","respondent":"和氣学務課長","answer":"そのときに全体もあわせて、２５年のものはお示ししたいというふうに考えております。そういうところも含めまして、しっかりと受けとめて改善に努めていきたいというふうに考えてあります。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"中学校は７％で、そのほかの9)から14)ぐらいの項目のところに比べると多いので、どういう内容かなというのを非常に興味を持ったところです。小学校のところでは意外に少ないので、その辺はどういうふうに教育委員会としても見ているか、それについてもちょっと伺っておきたいと思います。","respondent":"和氣学務課長","answer":"一概にこれがあるから効果がないのではないかということは考えておりませんし、交流活動自身は、その選択のためのものということでもございません。小１プロブレムを解決するというのが一番の目的ですので、そういう点から、また別の評価をしてくれるハガキもあります。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"改めて今回のところにも入れたという基本的な概念、教育委員会の、その辺はどういうことなのか。その教育委員会の思いはこういう数字にあらわれていることがどうなのかというところを、もう一度ちょっと説明を伺いたいと思います。","respondent":"和氣学務課長","answer":"これが少ないから、多いからといって、直ちに保幼小交流が無意味かどうかというのはまた違うだろうと思ってあります。傾向をあくまでも知りたいということで入れた限りですので、これについては先ほど私のほうで回答させていただいたとおりのことであります。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"そういうものもつくって保育課というんですかね、残念ですけれども、理解も含めて十分に浸透している状況ではないんじゃないかと。本来の保育活動、それは１つの意見として聞いていただいているということで結構ですが、そういうふうにちょっと思うところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"大倉委員","kind":"質問・要望","question":"できるだけこう、さらにその保護者がどういったことを重点的に捉えているかというのをもう少し反映できるような選択肢というのは可能なんでしょうか。その選択肢をもう少し５段階に増やすとか、そういったアンケート方法というのはできないのか、そういったものが可能なのか。","respondent":"和氣学務課長","answer":"第２希望とか、理由の１とか２とか３とか、区役所の今の既存のシステムで集計できるようにマークシートにしています。もし１位、２位とやると、またそれも考えさせていただきたいという考えです。","id":"exchange-006"}]},{"id":"topic-02","title":"鮫浜小学校通級指導学級（情緒障害等）開設（平成２６年度）","agenda":"鮫浜小学校通級指導学級（情緒障害等）開設（平成２６年度）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"情緒障害ですから一概にそういうふうな発症率みたいなのはないんじゃないかなと、その何というんですか、ちょっと１つ教えていただきたい。鮫浜小に１クラス、１０人程度というふうに考えていいのかなというのは、ちょっとそのあたりを説明するよう求めました。","respondent":"渋谷指導課長","answer":"２５年あたりの利用率から、平成２６年度以降も同程度利用率があるというふうな見込みをもとに、品川区の場合は算出をしております。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"普通に考えても１学級となると思うんですけれども、そうすると教員配置は２人というふうになるのか。３０年度は７,０００人にもなるわけですから、３学級と必要だったら、そういう考え方なんか尋ねました。","respondent":"渋谷指導課長","answer":"平成３１年度ぐらいまでの人口推計を見ていったときに、鮫浜小学校に１学級増級することで、そこの部分では収容できるだろうというような判断です。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"予算的なところをもう少し教えていただきたい。教員が２学級に３名とかいうところなんですけれども、今までの区の予算がどのぐらいで、２６年度はこのぐらいとか、概要で結構なので。","respondent":"渋谷指導課長","answer":"その教室整備等で若干工事関係のお金がかかるというようなことで、これはこの後予算要求をしていくものです。ただ、水回り等の大きな工事がないので、それほど大きな工事にはならないというふうに思っております。","id":"exchange-009"},{"speaker":"塚本委員","kind":"確認","question":"これはいわゆる発達障害の方々を主に対象とされているということでいいのかどうかというのを確認しておきたいです。みたいなところでの保護者の希望というのは、基本的にどういう扱いになるのか、その辺をちょっとお伺いしたい。","respondent":"渋谷指導課長","answer":"ＬＤだとか、ＡＤＨＤだとか、そういった子どもたちが対象になります。新たな学級が設置されることによって、また、その辺は十分配慮させていただきながら対応させていただきたいというふうに考えております。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"いわゆる通級ですから、通級を勧めるというんですか、ちょっとお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"情報をお伝えしながら、望ましい就学先についてご相談を差し上げていくと、そういう体制で臨んでいるところです。専門的に判断をさせていただいて、ご相談しながら進めていくと、そういう手順です。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、学校あるいは教師の側から通級に行ったほうが望ましいのではないかというような、保護者に全くその考えを持っていなくて、そういうアプローチというのは、基本的にはないんか尋ねました。","respondent":"渋谷指導課長","answer":"あります。相談をしながら、時間をかけながら、徐々に徐々にステップアップしていくというような形をとるケースもあります。","id":"exchange-012"},{"speaker":"沢田副委員長","kind":"質問","question":"今の塚本委員の質問とちょっと関するところもあるんですけれども、今回１クラス１０名ということでおさまるというふうに考えて、今回１クラス１０名ということで考えているのか尋ねました。","respondent":"渋谷指導課長","answer":"現在３つの情緒障害学級に在籍している子どもたちの住所はわかっておりまして、大体半径８００メートルあたりの円を書いたときに入ってくる子どもの数を見たときに、そんなことで判断をしています。","id":"exchange-013"},{"speaker":"沢田副委員長","kind":"質問","question":"そうすると今、例えばその通級学級に通っていなくて、この地域で発達障害の方とかも、普通の学級に行っている方は余り入っていないという形なんか尋ねました。","respondent":"渋谷指導課長","answer":"そこまでのニーズは正確には把握していないですが、余りそんなに必要な方は多くないだろうというふうなことは見込んでおるところです。","id":"exchange-014"},{"speaker":"高橋委員","kind":"質問・要望","question":"そういう要望を出して、その３つも活かして、どのようにお考えか尋ねました。","respondent":"渋谷指導課長","answer":"全く通級指導学級のご経験のない方をいきなり都から２人ポンともらって配置するというのは、なかなか厳しいだろうというふうに思っています。","id":"exchange-015"},{"speaker":"高橋委員","kind":"意見","question":"小学校でこれまで通級で培われた指導について、どのように鮫浜で活かしていくかという、その体制というか、鮫浜のところだけというのではなくて、宮前ではこうでした、源氏前ではこうでしたみたいな、そういうものをどう活かして、そういう体制が実際あるならばその辺の話とかとの意見を述べました。","respondent":"渋谷指導課長","answer":"品川区の現状では、専門家による巡回相談を行ったり、かなり区全体、組織的に特別支援教育の充実というものに取り組んでおるところです。そういったところでの横の連携等々、鮫浜小学校だけということではなくて、区全体の特別支援教育の充実に取り組んでいるところです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"送迎をするということのいろいろなご要望はあって、それはこっちに置いておいて、とにかく週に１回か２回子どもさんが通うわけですよね。この際教えていただきたいんですけれども、１クラス１０人ですからいろいろな子がいて、こういう考え方なんか尋ねました。","respondent":"渋谷指導課長","answer":"歩いて行かれれば、一番それはベストだろうなというふうに思っております。それが１学級で１０名、在籍が１０名という形で、ずっと開いているという形になります。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"小学校１年生からも含めて、成長していくわけですから、交通の便というのもある程度考慮したほうがいいんじゃないかなと私は思うんですね。そのあたりの検討した結果みたいなのを教えていただきたいなと思っています。","respondent":"渋谷指導課長","answer":"８００メートルというのは大体１分８０メートルだから１０分以内で歩いていける範囲というような、そういうイメージで地域を選択しているということ。","id":"exchange-018"}]},{"id":"topic-03","title":"品川区子ども・子育て会議","agenda":"品川区子ども・子育て会議","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"いろいろと要望もさせていただきたいし、考え方として伺っておきたいと思っているので、ちょっとまず聞きたいなというふうに思っています。住民の声を聞く場を確保するような考え方についてはどういうふうに思っているのかなというのを、まずそのあたりをちょっと伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"少なくとも３回は開催する必要があるのではないかと考えておりますが、会議運営の中で会長、副会長を含めて検討していく内容だと考えています。この計画ができましたら、計画案のパブリックコメントも予定しておりますので、現在のところ公聴会等を開く予定は考えておりません。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"そこが品川区であってほしいというのは当然のことなんですが、そこをしっかり守るということを、そのあたりの考え方について伺いたいと思います。そこのうちで見ると１６％という状況になっている株式会社立の保育園を、きちんとその点についての見解を伺っておきたいというふうに思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"前回の子ども・子育ての条例のところでもご説明したところですが、この子ども・子育て支援法自体が。この姿勢も変わるところではございません。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"今申し上げた３種類の補助金、それが１園に対して、私はちょっと知りたいなというふうに思っているんですね。品川区がこれまで、文教委員会ですから、教えていただきたいなというふうに思っています。","respondent":"今井制度改革・待機児童対策担当課長","answer":"開設準備経費を含めた、多分運営経費に及ぶ、今のご質問だったと思います。安心こども基金を含めて８分の７とか、また改めて正副委員長等とご相談しまして、確認させていただきたいと思います。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"私の調査では１１園進出、進出というのかしら、出てきて保育を担当してくださっているわけですね。出していただけるようにお願いしたいというふうに思っておりますので、次回でいいですから、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"とりあえず出していただけるよう要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"最初にちょっと１つ確認させていただきたい。兼ねるということの意味合いをお伺いしたいんですけれども、一律にどこもそのような対応をされているのかというところで、ちょっとお尋ねします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"平成２７年の３月までですので、今おつくりいただく計画自体が２７年４月からということで、ご審議をいただくということを考えております。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"今お伺いして、あと構成２０名の中で子ども・子育て支援に関する事業等に従事する者１０名という中で、そういう意味合いなのかどうかということ。この商工会議所が結びつかなかったので、そこのところをちょっと教えていただきたいということです。","respondent":"今井制度改革・待機児童対策担当課長","answer":"次世代のほうの委員構成につきましては、次世代の育成推進協議会のときの構成も踏まえながら、構成を検討した経緯があります。そしてホームページ等の情報公開などでさまざまな子育て情報などに従事している方も含めて、こちらが委員として委嘱を検討した背景があります。","id":"exchange-025"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"この委員構成の確認をさせていただきたいんですけれども、それから公募区民が３名ということですけれども、どういった形で選ばれたのかということを説明するよう求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"最後に公募委員につきましては、こちら３名に対しまして１８名の応募がございました。その応募の方につきましては、あと作文などを書いていただきましたので、それをもとに子ども未来事業部の中の選考という形で選考しています。","id":"exchange-026"},{"speaker":"沢田副委員長","kind":"確認","question":"その委員会構成、日本労働組合総連合会の中で選んでいただいたということでよろしいということだと思います、その辺を確認させてください。教職員じゃないのかということを確認しました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"２点です。２点目の出席状況ですが、保護者の中でご欠席になるというふうに聞いている以外は、現在のところ欠席のご連絡はいただいておりません。","id":"exchange-027"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"２回目以降、また１１月となっていますけれども、やはり保護者の方というのはなかなか、特に保育園に預けられている方というのは平日の日中仕事をされている方がほとんどだと思いますし、幼稚園もそういう方がいらっしゃると思いますので、また日程のほうはご検討をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"それと、具体的に品川区のこれからの保育事業の量だとか、いろいろなことを具体的に議論していくのが２回目以降になるんですかね。ちょっと一定の考えていることがあったら教えていただきたいなというふうに思っておりますし、私はぜひ冒頭に質問としていろいろな会議の。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今年度の末までには東京都のほうに量の見込みの部分は報告、量の見込みは東京都のほうに報告できるように準備をしていただくように考えております。３点目の公聴会につきましては、こちらは計画の策定主体は品川区ですので、私ども今現在は公聴会のほうは予定していないです。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとごめんなさい、そうですね。そのあたり教えていただきたいということと、区民の方が８名いらっしゃるので、配慮をしていただければいいかなというふうに思っておりますけれども。","respondent":"今井制度改革・待機児童対策担当課長","answer":"最初に傍聴人数ですが、傍聴人数は１０名という形で、先着というふうに予定しております。先ほども申しました量の見込みは今年度末で、この計画自体は２７年の３月までに事業計画と各方策を含めたものを東京都の方に最終的に出します。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"子どもの学童だとか、そういうところも、学童というのかしら、すまいるのほうも移管されてきたわけですから。これからの品川区の事業内容がここで決まっていくというわけですから、ちょっとくどいですけれども、強調して意見として終わりたいと思います。","respondent":"若林委員長、立川保育課長","answer":"ほかにございませんか。ご発言がないようですので、これで本件および報告事項を終了いたします。なおかつ地域における子育て支援を実施する機能を備えるということが原則でございまして、都は認定こども園として認定するものです。","id":"exchange-031"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"４・５歳児で３０人に対して１人の職員という、現実はこういうふうになっているけれども、数字が違いますよね。一番多い、４・５歳児で１人の職員に対して３０人を超えている最大の数は幾つなのか、どういう状況なのか教えてほしいと求めました。","respondent":"立川保育課長","answer":"この規定というのは、例えば４・５歳児合計で３０人以上いれば、それに従って保育士を配置するということになってあります。現状、区立につきましては、年齢で区切った場合の３０名以上のクラスというのはございません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"５歳児と全部の年齢で、現実的にはどういうふうになっているのかなというのを、全年齢で。１園１園聞くわけにいかないので、一番多いところが何人いるのか、その数字を教えていただきたいということで質問したんですけれども、全年齢で。","respondent":"立川保育課長","answer":"いわゆる２０人に１人とか、３０人に１人とか、それに従って人数のカウントをしていくということになります。ですから超えていて人が足りないとか、そういうような現状ではございません。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"当然これに関して質疑するということがあるわけですから、やっぱりできるだけ対応していただけるようにお願いしたいなというふうに思っているんです。したがって、やっぱり質問に答えていただきたいと、そういうふうに思いますのでよろしくお願いしたいと思います。","respondent":"立川保育課長","answer":"職員配置につきましては定員で配置をしているわけではございません。職員については配置していますので、現行の厚生労働省が定める基準を下回っているとか、そういうようなことは一切ございません。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"２１人になったらもう１人職員を増やしますよという、こういう考え方ですよね。違うんか尋ねました。","respondent":"立川保育課長","answer":"子どもの数と基準の人数、その辺を細かく端数まで計算いたしまして、その合計で基準の職員の人数というのを配置しているということになります。非常勤の職員、また派遣の職員を配置いたしまして、全体として適正な職員の配置を確保しています。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"まずちょっとそれを１つお願いしたいのと、全体でいいですから、栄養士はいないのか。その辺の人数と非常勤の職員、どういう種類が何人ぐらいいらっしゃるのか、そこもちょっと含めて教えてほしいと求めました。","respondent":"立川保育課長","answer":"看護師２６名、用務４２名ということで、一覧になっているところです。非常勤につきましては、有資格、無資格含めまして、約６００名を配置しています。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"首を振っていたあたり、ちょっと説明してください。説明を求めました。","respondent":"立川保育課長","answer":"職員配置についての説明をもう一度します。その端数については全部合計いたしまして、１つの定数、１人の定数としてカウントしていくというのが区の配置の基本の考え方になります。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"非常勤が６００人というふうな数と、正規職員の９４０人という数を比較して見ちゃったら、間違いがあったら指摘をしてほしいと求めました。園長職というのは保育士に入るのかなとちょっと思ったんですけれども、これでいいかどうか確認をしたいんですが、正確に説明を求めました。","respondent":"立川保育課長","answer":"４ページの表ですけれども、合計欄の１つ上のところが保育課というところになっておりまして、園長については保育士６８４名の中に含まれております。園長によっては看護師の資格である者もいますので、それもこの２６名の中に入っているところです。","id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"私今質問して一番知りたかったのが、例えば保育士６８４名は、園長も含んでいる。そうするとダブルカウントになっちゃうじゃないですか、看護師。","respondent":"立川保育課長","answer":"保育園４２園というブランチがあるんですけれども、この７５２名の中には、看護師の者がやっているというのが現状です。そういった園長につきましては保育士の配置の基準の、子どもの数に対する配置の基準の人数としてはカウントはいたしません。","id":"exchange-039"},{"speaker":"本多委員","kind":"質問・要望","question":"今後の国の動向をにらみながら、いろいろいと取り組みを考えていっていると思うんですけれども、国の方針が決まる以前に、区でできること、独自の取り組み、なかなか難しいのかもしれないんですが、今後の取り組みについてどのようにお考えなのか、まず方針をお聞かせほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"順次それぞれの施設に対して子ども・子育て支援制度の説明をやっておりまして、新制度に柔軟に対応して移行していくかということの、区としては。子ども・子育て支援制度では、そのような変更のところの内容につきましては、それぞれの施設に対応して説明している段階です。","id":"exchange-040"},{"speaker":"塚本委員","kind":"確認","question":"特に何もしなくても平成２７年度４月を迎えられるというようなご答弁があったんだと思うんですけれども、もしかしたら今のままではまずいかもしれないというような課題となり得るようなところがあるのかどうか、というのを１つ確認をしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"６人から１９名までの方をお預かりする小規模保育事業という形がつくられてまいりまして、この基準も今、国は検討中です。今品川区の類型でまいりますと、区としても小規模保育事業の国の基準に合わせて検討しておりますので、この辺の状況を今確認しています。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"今の話で、施設型給付というものを受けていくためには、区としての基準を満たしていただく必要があるので、そこに一定のハードルなり何なりというのが出てくるかもしれないというお話だったんですけれども、施設型給付を受けない選択肢というのはあるということか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"国の方針はなるべく認可外ということではなくて、施設型給付の中で、子ども・子育てという大きな枠の中で補助していこうというのが国の方針ですが。","id":"exchange-042"},{"speaker":"沢田副委員長","kind":"質問","question":"こういう制度をいろいろ、子ども・子育てを国は考えてやってきて、認定こども園とかができてきたと思うんです。何というんですか、その辺の方向というのはどういうふうに区として考えられているのか、改めてお伺いします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１つは、やはりいろいろな施策を合わせながら、総合的に対応していくしかないというふうに考えております。制度の中へ入ってきますので、より質を担保しながら、安心して区民の皆様が通っていただけるような体系になってくるというふうに考えております。","id":"exchange-043"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"その行政側のいろいろな所管とかもあるのかもしれません。そういうのを使い分けて子育てが充実していく、品川区は子育ては進んでいると言われていますから、充実していく方向になってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"高橋委員","kind":"質問","question":"区としてそこにどう達していこうとするか、インセンティブがどうとかというのはちょっと置いておいて、というところがどうなのかということを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区は、やはり平成１３年度のモデル実施から、幼保一体施設という品川区独自の取り組みを国に先駆けて進めてまいりました。そしてプログラムが決して引けをとるものではないので、逆にどこの部分が違ってくるのかなというところを今確認している作業の部分です。","id":"exchange-045"},{"speaker":"高橋委員","kind":"確認","question":"確認をして、必要がないというか、そういうようなところまで考えていると。今、じゃあ差を、どういう違いがあるかを検討されているという状況なんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"この幼保連携型認定こども園は、そういう意味では運営といいますか、そういうものがしやすくなるのではないかというふうに考えております。","id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"０歳とかそういう小さな年齢の子どもは、やっぱり保育室だけでは不十分ですから、そういうことも日常的にやらなきゃいけない。それで、さっきの話に戻るんですけれども、私立じゃなくて株式会社立の保育所で、園庭・屋外運動場あるところ、何園ぐらいあるんか尋ねました。","respondent":"立川保育課長","answer":"園庭の有無につきましては、ちょっと現在手持ちの資料がございませんので、後ほどお示ししたいと思います。","id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"そういう何というんでしょうか、設置の思いのある保育園で、園庭がなくても仕方がないと思っているのか。意識のところはどういうふうに考えておられるのか、ちょっと教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"開設の支援のところは、私のほうの担当でやっております。区としては、実際その中でどのような保育がなされているかということを、施設基準を踏まえまして運営を管理監督していくというふうに考えております。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"子ども未来事業部しかそこのところは主張できないところなんですから、やっぱりそこは何としても頑張っていただきたいというふうに思っています。答弁できる部分じゃないと思うので答弁は求めませんけれども、しかし本当に率直に、真摯に受けとめていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/646567?Template=document&Id=4800#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":43255,"voices":126}}]);
